import sys
from collections import Counter

VOWELS = frozenset("aeiou")

DEFAULT_SAMPLES = ["Hello World", "Python", "", "rhythm", "AEIOU sequence"]


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, ignoring case."""
    if text is None:
        raise TypeError("count_vowels() needs a string, not None")
    return sum(1 for ch in text.lower() if ch in VOWELS)


def normalize_line(raw):
    """Strip a raw input line, returning None when nothing useful is left."""
    if raw is None:
        return None
    stripped = raw.strip()
    if not stripped:
        return None
    return stripped


def first_vowel_index(text):
    """Index of the first vowel, or None when the text has no vowel at all."""
    for index, ch in enumerate(text.lower()):
        if ch in VOWELS:
            return index
    return None


def vowel_ratio(text):
    """Vowels per alphabetic character, or None when there are no letters."""
    letters = [ch for ch in text if ch.isalpha()]
    if not letters:
        return None
    return count_vowels(text) / len(letters)


def dominant_vowel(text):
    """The most frequent vowel, or None if the text contains none."""
    tally = Counter(ch for ch in text.lower() if ch in VOWELS)
    if not tally:
        return None
    return tally.most_common(1)[0][0]


def format_report(raw):
    line = normalize_line(raw)
    if line is None:
        return "(blank input skipped)"
    parts = ["{!r}: {} vowel(s)".format(line, count_vowels(line))]
    index = first_vowel_index(line)
    if index is not None:
        parts.append("first at position {}".format(index))
    ratio = vowel_ratio(line)
    if ratio is not None:
        parts.append("density {:.2f}".format(ratio))
    top = dominant_vowel(line)
    if top is not None:
        parts.append("most common {!r}".format(top))
    return ", ".join(parts)


def load_lines(path):
    if path is None:
        return list(DEFAULT_SAMPLES)
    with open(path, encoding="utf-8") as handle:
        return handle.readlines()


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else None
    total = 0
    for raw in load_lines(path):
        print(format_report(raw))
        line = normalize_line(raw)
        if line is not None:
            total += count_vowels(line)
    print("total vowels: {}".format(total))


if __name__ == "__main__":
    main()

