def sum_list(numbers):
    """Return the sum of all numbers in the list; 0 for an empty list."""
    if numbers is None:
        raise TypeError("sum_list() requires a list, not None")
    total = 0
    for value in numbers:
        total += value
    return total


def average(numbers):
    """Mean of the list, or None when there is nothing to average."""
    if not numbers:
        return None
    return sum_list(numbers) / len(numbers)


def extremes(numbers):
    """Return (smallest, largest) of the list, or (None, None) when empty."""
    low = None
    high = None
    for value in numbers:
        if low is None or value < low:
            low = value
        if high is None or value > high:
            high = value
    return low, high


def parse_number(token):
    """Convert a text token to int or float, or None when it is not numeric."""
    text = token.strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return None


def parse_list(line):
    """Split a comma/space separated line into numbers, reporting bad tokens."""
    numbers = []
    rejected = []
    for token in line.replace(",", " ").split():
        value = parse_number(token)
        if value is None:
            rejected.append(token)
        else:
            numbers.append(value)
    return numbers, rejected


