def find_max(numbers):
    """Return the largest number in a non-empty list of integers."""
    largest = None
    for value in numbers:
        if largest is None or value > largest:
            largest = value
    if largest is None:
        raise ValueError("find_max() requires a non-empty list")
    return largest


def parse_int(token):
    """Return the integer value of token, or None if it is not an integer."""
    text = token.strip()
    if not text:
        return None
    sign = ""
    if text[0] in "+-":
        sign, text = text[0], text[1:]
    if not text.isdigit():
        return None
    return int(sign + text)


def parse_row(line):
    """Turn a comma- or space-separated line into a list of integers."""
    separated = line.replace(",", " ").split()
    numbers = []
    for token in separated:
        value = parse_int(token)
        if value is None:
            raise ValueError("not an integer: %r" % token)
        numbers.append(value)
    return numbers


def describe(numbers):
    """Return a one-line description of a row and its maximum."""
    if not numbers:
        return "(empty row skipped)"
    maximum = find_max(numbers)
    position = None
    for index, value in enumerate(numbers):
        if value == maximum:
            position = index
            break
    return "max(%s) = %d at index %d" % (
        ", ".join(str(n) for n in numbers),
        maximum,
        position,
    )


def report(lines):
    """Describe every row, collecting the overall maximum as we go."""
    overall = None
    output = []
    for line in lines:
        try:
            numbers = parse_row(line)
        except ValueError as error:
            output.append("bad row (%s)" % error)
            continue
        output.append(describe(numbers))
        if numbers:
            row_max = find_max(numbers)
