def filter_even(numbers):
    """Return a new list containing only the even numbers of `numbers`."""
    if numbers is None:
        raise ValueError("numbers must be a list of integers, not None")
    result = []
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("expected an integer, got %r" % (value,))
        if value % 2 == 0:
            result.append(value)
    return result


def parse_int(token):
    """Convert a text token to an int, or return None when it is not numeric."""
    text = token.strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        return None


def parse_numbers(line, rejected=None):
    """Parse a whitespace/comma separated line into a list of integers.

    Tokens that are not integers are appended to `rejected` when a list is
    given, otherwise they are silently skipped.
    """
    numbers = []
    for token in line.replace(",", " ").split():
        value = parse_int(token)
        if value is None:
            if rejected is not None:
                rejected.append(token)
            continue
        numbers.append(value)
    return numbers


def split_label(line):
    """Split an optional "label: values" prefix, returning (label, values).

    The label is None when the line carries no prefix.
    """
    head, separator, tail = line.partition(":")
    if separator:
        return head.strip() or None, tail
    return None, line


def summarize(numbers, label=None):
    """Build a one-line report about the even numbers found in `numbers`."""
    evens = filter_even(numbers)
    name = "input" if label is None else label
    if not evens:
        return "%s: no even numbers among %d value(s)" % (name, len(numbers))
    body = ", ".join(str(value) for value in evens)
    return "%s: [%s] (count=%d, sum=%d)" % (name, body, len(evens), sum(evens))


