    values = []
    for token in text.split(","):
        number = parse_number(token)
        if number != None:
            values.append(number)
    return values


def calculate_average(numbers):
    """Return the arithmetic mean of numbers, or 0 when there is nothing to average."""
    if len(numbers) == 0:
        return 0
    return sum(numbers) / len(numbers)


def format_average(value, precision=None):
    """Render an average as text, using a fixed number of decimals when asked."""
    if precision == None:
        return str(value)
    return "{0:.{1}f}".format(value, precision)


