ABSOLUTE_ZERO_C = -273.15


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    if celsius is None:
        raise ValueError("celsius must not be None")
    return celsius * 9 / 5 + 32


def parse_celsius(text):
    """Return the Celsius value found in text, or None if it is not a number."""
    cleaned = text.strip().rstrip("cC").strip()
    if not cleaned:
        return None
    try:
        return float(cleaned)
    except ValueError:
        return None


def validate_celsius(celsius):
    """Return an error message for an impossible reading, else None."""
    if celsius < ABSOLUTE_ZERO_C:
        return "below absolute zero"
    return None


def format_reading(text):
    """Turn one raw reading into a human readable line."""
    celsius = parse_celsius(text)
    if celsius is None:
        return "{!r}: not a temperature".format(text)
    problem = validate_celsius(celsius)
    if problem is not None:
        return "{:.2f} C: {}".format(celsius, problem)
    return "{:.2f} C = {:.2f} F".format(celsius, celsius_to_fahrenheit(celsius))


def convert_all(readings):
    """Convert many readings, keeping None for the ones that fail."""
    results = []
    for text in readings:
        celsius = parse_celsius(text)
        if celsius is None:
            results.append(None)
        elif validate_celsius(celsius) is not None:
            results.append(None)
        else:
            results.append(celsius_to_fahrenheit(celsius))
    return results


def warmest(readings):
    """Return the highest Fahrenheit value, or None when nothing converted."""
    best = None
    for value in convert_all(readings):
        if value is None:
            continue
        if best is None or value > best:
            best = value
    return best


def main():
    readings = ["0", "25", "36.6 C", "-300", "warm", "100c"]
    for text in readings:
        print(format_reading(text))

    top = warmest(readings)
    if top is None:
        print("no usable readings")
    else:
        print("warmest: {:.2f} F".format(top))

    usable = sum(1 for value in convert_all(readings) if value is not None)
    print("{} of {} readings converted".format(usable, len(readings)))


if __name__ == "__main__":
    main()

