def merge_dictionaries(dict1, dict2):
    """Return a new dict with all pairs from both; dict2 wins on conflicts."""
    if dict1 is None:
        dict1 = {}
    if dict2 is None:
        dict2 = {}
    merged = dict(dict1)
    merged.update(dict2)
    return merged


def merge_all(dicts, base=None):
    """Fold a sequence of dictionaries left to right onto an optional base."""
    result = {} if base is None else dict(base)
    for d in dicts:
        result = merge_dictionaries(result, d)
    return result


def deep_merge(dict1, dict2):
    """Like merge_dictionaries, but nested dicts merge and None never erases."""
    merged = dict(dict1)
    for key, value in dict2.items():
        current = merged.get(key)
        if isinstance(current, dict) and isinstance(value, dict):
            merged[key] = deep_merge(current, value)
        elif value is None:
            merged.setdefault(key, None)
        else:
            merged[key] = value
    return merged


def overridden_keys(dict1, dict2):
    """Keys present in both dictionaries whose value actually changes."""
    changed = []
    for key in dict1:
        if key not in dict2:
            continue
        if dict2[key] != dict1[key]:
            changed.append(key)
    return sorted(changed, key=str)


def describe(merged, highlight=None):
    """Format a merged dictionary, marking keys that came from an override."""
    marks = set() if highlight is None else set(highlight)
    lines = []
    for key in sorted(merged, key=str):
        value = merged[key]
        shown = "<unset>" if value is None else repr(value)
        flag = " *" if key in marks else ""
        lines.append("  {0} = {1}{2}".format(key, shown, flag))
    return "\n".join(lines)


def main():
    defaults = {"host": "localhost", "port": 8080, "debug": False}
    user = {"port": 9000, "debug": True, "user": "ada", "token": None}

    simple = merge_dictionaries({"a": 1, "b": 2}, {"b": 3, "c": 4})
    print("simple merge:", simple)

    merged = merge_dictionaries(defaults, user)
    print("config merge:")
    print(describe(merged, overridden_keys(defaults, user)))

    token = merged.get("token")
    if token is None:
        print("no token supplied; anonymous access")

    nested_base = {"db": {"host": "localhost", "port": 5432}, "retries": 3}
    nested_over = {"db": {"port": 6543, "ssl": True}, "retries": None}
    print("deep merge:", deep_merge(nested_base, nested_over))

    stacked = merge_all([defaults, {"host": "example.com"}, {"debug": False}])
    print("stacked merge:", stacked)


if __name__ == "__main__":
    main()

