def normalize_shift(shift):
    """Return shift reduced to 0..25, or None if it is not a usable integer."""
    if shift is None:
        return None
    try:
        value = int(shift)
    except (TypeError, ValueError):
        return None
    return value % 26


def caesar_cipher_encrypt(text, shift):
    """Encrypt text with a Caesar cipher, preserving case and non-letters."""
    if text is None:
        raise ValueError("text must be a string, not None")
    amount = normalize_shift(shift)
    if amount is None:
        raise ValueError("shift must be an integer")
    out = []
    for ch in text:
        if 'a' <= ch <= 'z':
            base = ord('a')
        elif 'A' <= ch <= 'Z':
            base = ord('A')
        else:
            out.append(ch)
            continue
        out.append(chr(base + (ord(ch) - base + amount) % 26))
    return ''.join(out)


def caesar_cipher_decrypt(text, shift):
    """Undo caesar_cipher_encrypt for the same shift."""
    amount = normalize_shift(shift)
    if amount is None:
        raise ValueError("shift must be an integer")
    return caesar_cipher_encrypt(text, -amount)


def find_shift(ciphertext, crib):
    """Return the shift that makes crib appear in ciphertext, or None."""
    needle = crib.lower()
    for candidate in range(26):
        if needle in caesar_cipher_decrypt(ciphertext, candidate).lower():
            return candidate
    return None


def parse_shift(raw):
    """Read a shift written by a user; None means the text was unusable."""
    if raw is None:
        return None
    stripped = raw.strip()
    if not stripped:
        return None
    return normalize_shift(stripped)


def describe(text, raw_shift):
    """Format one report line for text encrypted with a user-supplied shift."""
    shift = parse_shift(raw_shift)
    if shift is None:
        return "{0!r}: bad shift {1!r}".format(text, raw_shift)
    cipher = caesar_cipher_encrypt(text, shift)
    return "{0!r} + {1} -> {2!r}".format(text, shift, cipher)


def main():
    for text, raw_shift in [('abc', '1'), ('xyz', '3'),
