import random


def guess_number(secret_number, guess):
    if guess > secret_number:
        return 'Too high'
    if guess < secret_number:
        return 'Too low'
    return 'Correct!'


def parse_guess(text):
    try:
        return int(text.strip())
    except ValueError:
        return None


def new_secret(low, high, secret=None):
    if secret is None:
        return random.randint(low, high)
    if not low <= secret <= high:
        raise ValueError("secret outside the allowed range")
    return secret


def narrow_range(low, high, guess, verdict):
    if verdict == 'Too high':
        return low, guess - 1
    if verdict == 'Too low':
        return guess + 1, high
    return guess, guess


def format_report(history, winner, bounds):
    lines = []
    for attempt, (value, verdict) in enumerate(history, start=1):
        lines.append("Attempt {}: {} -> {}".format(attempt, value, verdict))
    if winner is None:
        lines.append("No winning guess; remaining range is {}-{}".format(*bounds))
    else:
        lines.append("Found {} in {} attempt(s)".format(winner, len(history)))
    return "\n".join(lines)


def play_round(secret, guesses, low=1, high=100, max_attempts=None):
    history = []
    winner = None
    for raw in guesses:
        guess = parse_guess(raw)
        if guess is None:
            history.append((raw, 'Not a number'))
            continue
        verdict = guess_number(secret, guess)
        history.append((guess, verdict))
        low, high = narrow_range(low, high, guess, verdict)
        if verdict == 'Correct!':
            winner = guess
            break
        if max_attempts is not None and len(history) >= max_attempts:
            break
    return history, winner, (low, high)


def solve_by_bisection(secret, low=1, high=100, limit=None):
    attempts = []
    while low <= high:
        guess = (low + high) // 2
        verdict = guess_number(secret, guess)
        attempts.append(guess)
        if verdict == 'Correct!':
            return attempts
        if limit is not None and len(attempts) >= limit:
            return None
        low, high = narrow_range(low, high, guess, verdict)
    return None


def main():
    secret = new_secret(1, 100, 10)
    guesses = ["50", "twelve", "12", "", "9", "10", "11"]
    history, winner, bounds = play_round(secret, guesses, max_attempts=8)
    print(format_report(history, winner, bounds))

    secret = new_secret(1, 100)
    attempts = solve_by_bisection(secret, limit=4)
    if attempts is None:
        print("Binary search gave up on {} after 4 attempts".format(secret))
    else:
        print("Binary search solved {} using {}".format(secret, attempts))


if __name__ == '__main__':
    main()

