def parse_operation(entry):
    """Normalize one operation tuple into a (name, payload) pair."""
    if entry is None:
        raise ValueError("operation entry must not be None")
    if not isinstance(entry, tuple) or len(entry) != 2:
        raise ValueError("each operation must be a 2-tuple (name, payload)")
    name, payload = entry
    if name is None:
        raise ValueError("operation name must not be None")
    name = str(name).strip().lower()
    if name not in ("enqueue", "dequeue"):
        raise ValueError("unknown operation: %r" % (name,))
    if name == "enqueue" and payload is None:
        raise ValueError("enqueue requires a non-None item")
    return name, payload


def simulate_queue(operations):
    """Simulate a FIFO queue with a list and return its final contents."""
    if operations is None:
        return []
    queue = []
    for entry in operations:
        name, payload = parse_operation(entry)
        if name == "enqueue":
            queue.append(payload)
        else:
            if queue:
                queue.pop(0)
    return queue


def trace_queue(operations):
    """Run the operations, returning (final_queue, list_of_dequeued_items)."""
    queue = []
    removed = []
    for entry in operations or []:
        name, payload = parse_operation(entry)
        if name == "enqueue":
            queue.append(payload)
            continue
        item = queue.pop(0) if queue else None
        if item is None:
            removed.append("<empty>")
        else:
            removed.append(item)
    return queue, removed


def format_report(operations, label=None):
    """Build a human readable summary of one simulation run."""
    title = label if label is not None else "run"
    final, removed = trace_queue(operations)
    lines = ["%s: %d operation(s)" % (title, len(operations or []))]
    lines.append("  final queue: %r" % (final,))
    lines.append("  dequeued:    %s" % (", ".join(repr(x) for x in removed) or "none"))
    return "\n".join(lines)


def main():
    runs = [
        ([('enqueue', 1), ('enqueue', 2), ('dequeue', None)], "two in, one out"),
        ([('dequeue', None)], "underflow"),
        ([('enqueue', 'a'), ('dequeue', None), ('enqueue', 'b')], None),
    ]
    for ops, label in runs:
        print(format_report(ops, label))
        print("  simulate_queue -> %r" % (simulate_queue(ops),))
    try:
        simulate_queue([('enqueue', None)])
    except ValueError as exc:
        print("rejected bad input: %s" % exc)


if __name__ == "__main__":
    main()

