from collections import Counter

HASHTAG_RE = re.compile(r"#(\w+)")

_ALIASES = {
    "py": "python",
    "js": "javascript",
    "ml": "machinelearning",
}


def extract_hashtags(text):
    """Return the hashtags found in text, without the leading '#'."""
    if text is None:
        return []
    if not isinstance(text, str):
        raise TypeError("text must be a string or None")
    return HASHTAG_RE.findall(text)


def canonical(tag, aliases=None):
    """Map a tag to its canonical spelling, using aliases when supplied."""
    lowered = tag.lower()
    if aliases is None:
        aliases = _ALIASES
    expanded = aliases.get(lowered)
    if expanded is not None:
        return expanded
    return lowered


def normalize_hashtags(text, aliases=None, limit=None):
    """Extract hashtags, canonicalize them and drop duplicates."""
    seen = []
    for tag in extract_hashtags(text):
        name = canonical(tag, aliases)
        if name not in seen:
            seen.append(name)
        if limit is not None and len(seen) == limit:
            break
    return seen


def count_hashtags(texts, aliases=None):
    """Count canonical hashtags across an iterable of strings."""
    tally = Counter()
    for text in texts:
        tally.update(normalize_hashtags(text, aliases))
    return tally


def most_common_hashtag(texts, aliases=None):
    """Return the most frequent hashtag, or None when there is none."""
    tally = count_hashtags(texts, aliases)
    if not tally:
        return None
    return tally.most_common(1)[0][0]


def format_report(texts, aliases=None):
    """Build a per-message listing plus a summary line."""
    lines = []
    for index, text in enumerate(texts, start=1):
        tags = normalize_hashtags(text, aliases)
        joined = ", ".join(tags) if tags else "(none)"
        lines.append("message {0}: {1}".format(index, joined))
    top = most_common_hashtag(texts, aliases)
    if top is None:
        lines.append("top hashtag: none found")
    else:
        lines.append("top hashtag: {0}".format(top))
    return "\n".join(lines)


