import math


def distance_2d(x1, y1, x2, y2):
    """Euclidean distance between (x1, y1) and (x2, y2)."""
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def parse_point(text):
    """Turn "3,4" into (3.0, 4.0); return None if the text is not a point."""
    parts = text.replace(";", ",").split(",")
    if len(parts) != 2:
        return None
    try:
        return (float(parts[0]), float(parts[1]))
    except ValueError:
        return None


def read_points(lines):
    """Parse every line, skipping blanks; raise on the first malformed line."""
    points = []
    for number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped:
            continue
        point = parse_point(stripped)
        if point is None:
            raise ValueError("line %d is not a point: %r" % (number, stripped))
        points.append(point)
    return points


def path_length(points):
    """Total travelled distance along a polyline given as a list of points."""
    total = 0.0
    previous = None
    for x, y in points:
        if previous is not None:
            total += distance_2d(previous[0], previous[1], x, y)
        previous = (x, y)
    return total


def nearest_point(points, target):
    """Closest point to target, or None when there is nothing to compare."""
    best = None
    best_distance = None
    for x, y in points:
        d = distance_2d(x, y, target[0], target[1])
        if best_distance is None or d < best_distance:
            best = (x, y)
            best_distance = d
    return best


def describe(points, target=None):
    """Build a short report about a polyline and, optionally, a target point."""
    lines = ["points: %d" % len(points)]
    lines.append("path length: %.3f" % path_length(points))
    if target is not None:
        closest = nearest_point(points, target)
        if closest is None:
            lines.append("nearest to (%g, %g): none" % target)
        else:
            gap = distance_2d(closest[0], closest[1], target[0], target[1])
            lines.append("nearest to (%g, %g): (%g, %g) at %.3f"
                         % (target[0], target[1], closest[0], closest[1], gap))
    return "\n".join(lines)


def main():
    raw = ["0,0", "3,4", "", "3,4", "9,4"]
    points = read_points(raw)
    target = parse_point("8;0")
    if target is None:
        print("target could not be parsed")
    else:
        print(describe(points, target))
    print("distance_2d(0, 0, 3, 4) =", distance_2d(0, 0, 3, 4))
    print("distance_2d(1, 1, 1, 1) =", distance_2d(1, 1, 1, 1))


if __name__ == "__main__":
    main()

