GRADE_BANDS = (
    (90, 'A'),
    (80, 'B'),
    (70, 'C'),
    (60, 'D'),
)


def calculate_grade(score):
    """Return the letter grade for a numeric score between 0 and 100."""
    if score is None:
        raise ValueError("score must be a number, not None")
    if not isinstance(score, (int, float)) or isinstance(score, bool):
        raise TypeError("score must be numeric")
    if score < 0 or score > 100:
        raise ValueError("score must be between 0 and 100")
    for threshold, letter in GRADE_BANDS:
        if score >= threshold:
            return letter
    return 'F'


def parse_score(text):
    """Convert raw text to a score, or None when it is not a usable number."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        value = float(stripped)
    except ValueError:
        return None
    if value < 0 or value > 100:
        return None
    return value


def grade_line(name, raw_score):
    """Format one gradebook row; unusable scores are reported as missing."""
    score = parse_score(raw_score)
    if score is None:
        return "{:<8} {:>7} {}".format(name, "--", "(no valid score)")
    return "{:<8} {:>7.1f} {}".format(name, score, calculate_grade(score))


def average(scores):
    usable = [s for s in scores if s is not None]
    if not usable:
        return None
    return sum(usable) / len(usable)


def build_report(entries):
    lines = [grade_line(name, raw) for name, raw in entries]
    mean = average([parse_score(raw) for _, raw in entries])
    if mean is None:
        lines.append("No scores available for an average.")
    else:
        lines.append("Average  {:>7.1f} {}".format(mean, calculate_grade(mean)))
    return "\n".join(lines)


