def parse_csv_line(line):
    """Split a CSV line into its comma-separated values."""
    if line is None:
        return []
    stripped = line.rstrip("\r\n")
    if stripped == "":
        return []
    return [field.strip() for field in stripped.split(",")]


def parse_header(line):
    """Return the column names of a CSV header line, or None if unusable."""
    fields = parse_csv_line(line)
    if not fields or any(name == "" for name in fields):
        return None
    return fields


def row_to_dict(header, line):
    """Pair a data line with the header names; None if the widths disagree."""
    if header is None:
        return None
    values = parse_csv_line(line)
    if len(values) != len(header):
        return None
    return dict(zip(header, values))


def coerce(value):
    """Convert a raw field to int or float when possible, else keep the text."""
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        return value


def read_table(text):
    """Parse a multi-line CSV document into a list of typed record dicts."""
    lines = text.splitlines()
    header = None
    records = []
    for line in lines:
        if not line.strip():
            continue
        if header is None:
            header = parse_header(line)
            if header is None:
                raise ValueError("first non-empty line is not a valid header")
            continue
        record = row_to_dict(header, line)
        if record is None:
            continue
        records.append({key: coerce(val) for key, val in record.items()})
    return records


def column_total(records, name):
    """Sum a numeric column, returning None if no numeric value is present."""
    total = None
    for record in records:
        value = record.get(name)
        if isinstance(value, (int, float)):
            total = value if total is None else total + value
    return total


def main():
    document = "fruit,crates,price\napple,3,1.25\nbanana,7,0.5\nbroken,row\ncherry,2,4.0"
    records = read_table(document)
    for record in records:
        print("{fruit}: {crates} crates at {price}".format(**record))
    for column in ("crates", "price", "fruit"):
        total = column_total(records, column)
        if total is None:
            print("column %s has no numeric data" % column)
        else:
            print("total %s = %s" % (column, total))
    print(parse_csv_line("apple,banana,cherry"), parse_csv_line("1,2,3"))


if __name__ == "__main__":
    main()

