def first_duplicate(s):
    """Return the first character that repeats in s, or None if all are unique."""
    seen = set()
    for ch in s:
        if ch in seen:
            return ch
        seen.add(ch)
    return None


def has_unique_chars(s):
    """Return True if every character in s occurs exactly once."""
    if s is None:
        raise TypeError("has_unique_chars() requires a string, not None")
    return first_duplicate(s) is None


def normalize(s, ignore_case=False, ignore_spaces=False):
    """Prepare a string for comparison according to the given options."""
    text = s
    if ignore_case:
        text = text.lower()
    if ignore_spaces:
        text = "".join(text.split())
    return text


def duplicate_positions(s, char=None):
    """Map each repeated character to the indexes where it occurs.

    If char is given, only that character is reported.
    """
    positions = {}
    for index, ch in enumerate(s):
        if char is not None and ch != char:
            continue
        positions.setdefault(ch, []).append(index)
    return {ch: idx for ch, idx in positions.items() if len(idx) > 1}


def describe(s, ignore_case=False, ignore_spaces=False):
    """Build a human readable verdict for the string s."""
    text = normalize(s, ignore_case=ignore_case, ignore_spaces=ignore_spaces)
    offender = first_duplicate(text)
    if offender is None:
        return "%r -> unique (%d characters)" % (s, len(text))
    spots = duplicate_positions(text, offender)[offender]
    places = ", ".join(str(i) for i in spots)
    return "%r -> not unique: %r appears at %s" % (s, offender, places)


def report(samples, ignore_case=False, ignore_spaces=False):
    """Describe every sample, skipping entries that are None."""
    lines = []
    for sample in samples:
        if sample is None:
            continue
        lines.append(describe(sample, ignore_case, ignore_spaces))
    return lines


def main(argv=None):
    samples = argv
    if samples is None or not samples:
        samples = ["abc", "abca", "", "Aa", "the quick brown fox", None]
    for line in report(samples):
        print(line)
    print("-- case insensitive, spaces ignored --")
    for line in report(samples, ignore_case=True, ignore_spaces=True):
        print(line)


if __name__ == "__main__":
    import sys

    main(sys.argv[1:])

