def is_leap_year(year):
    """Return True if `year` is a leap year in the proleptic Gregorian calendar."""
    if year is None:
        raise ValueError("year must not be None")
    year = int(year)
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def parse_year(text):
    """Convert a string to an int year, or return None if it is not a valid year."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        return None


def days_in_month(year, month):
    """Number of days in `month` (1-12) of `year`."""
    lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if not 1 <= month <= 12:
        raise ValueError("month must be between 1 and 12")
    if month == 2 and is_leap_year(year):
        return 29
    return lengths[month - 1]


def count_leap_years(start, end):
    """Count leap years in the inclusive range [start, end]."""
    if start > end:
        start, end = end, start
    return sum(1 for year in range(start, end + 1) if is_leap_year(year))


def next_leap_year(year, limit=None):
    """Return the first leap year strictly after `year`, or None if past `limit`."""
    candidate = year + 1
    while limit is None or candidate <= limit:
        if is_leap_year(candidate):
            return candidate
        candidate += 1
    return None


def describe(text):
    """Build a human readable report line for a user-supplied year string."""
    year = parse_year(text)
    if year is None:
        return "{!r}: not a valid year".format(text)
    verdict = "is a leap year" if is_leap_year(year) else "is not a leap year"
    following = next_leap_year(year, limit=year + 3)
    if following is not None:
        tail = "next leap year within three years: {}".format(following)
    else:
        tail = "no leap year in the next three years"
    return "{} {} ({} days in February); {}".format(
        year, verdict, days_in_month(year, 2), tail)


def main():
    samples = ["2000", "1900", "2024", "2023", "", "nineteen", "1600", "2096"]
    for sample in samples:
        print(describe(sample))
    print("Leap years from 1900 to 2000:", count_leap_years(1900, 2000))


