def parse_seconds(text):
    """Parse a plain integer number of seconds, returning None if invalid."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped.isdigit():
        return None
    return int(stripped)


def seconds_to_hms(seconds):
    """Convert a total number of seconds into an 'HH:MM:SS' string."""
    if seconds is None:
        raise ValueError("seconds must not be None")
    if isinstance(seconds, bool) or not isinstance(seconds, int):
        raise TypeError("seconds must be an integer")
    if seconds < 0:
        raise ValueError("seconds must not be negative")
    hours, remainder = divmod(seconds, 3600)
    minutes, secs = divmod(remainder, 60)
    return "{:02d}:{:02d}:{:02d}".format(hours, minutes, secs)


def hms_to_seconds(clock):
    """Convert an 'HH:MM:SS' string back to seconds, or None if malformed."""
    parts = clock.split(":")
    if len(parts) != 3:
        return None
    total = 0
    for index, part in enumerate(parts):
        value = parse_seconds(part)
        if value is None:
            return None
        if index > 0 and value >= 60:
            return None
        total = total * 60 + value
    return total


def describe(text):
    """Turn one raw input line into a human readable result line."""
    seconds = parse_seconds(text)
    if seconds is None:
        roundtrip = hms_to_seconds(text)
        if roundtrip is None:
            return "{!r}: not a duration".format(text)
        return "{} -> {} seconds".format(text, roundtrip)
    return "{} seconds -> {}".format(seconds, seconds_to_hms(seconds))


def total_duration(lines):
    """Sum every recognisable duration in lines; None if none were valid."""
    total = None
    for line in lines:
        value = parse_seconds(line)
        if value is None:
            value = hms_to_seconds(line)
        if value is None:
            continue
        total = value if total is None else total + value
    return total


def main():
    samples = ["3661", "90", "0", "86399", "01:01:01", "12:60:00", "abc"]
    for sample in samples:
        print(describe(sample))
    grand_total = total_duration(samples)
    if grand_total is None:
        print("no valid durations found")
    else:
        print("total: {} ({})".format(seconds_to_hms(grand_total), grand_total))


if __name__ == "__main__":
    main()

