def parse_matrix(text):
    """Parse a matrix written as rows of numbers separated by ';'. Returns None if invalid."""
    rows = []
    width = None
    for chunk in text.split(";"):
        chunk = chunk.strip()
        if not chunk:
            continue
        try:
            row = [float(token) for token in chunk.split()]
        except ValueError:
            return None
        if width is None:
            width = len(row)
        elif len(row) != width:
            return None
        rows.append(row)
    if width is None:
        return None
    return rows


def dimensions(matrix):
    if matrix is None:
        return None
    if len(matrix) == 0:
        return None
    return (len(matrix), len(matrix[0]))


def matrix_add(matrix1, matrix2):
    """Add two matrices of identical dimensions element-wise."""
    dim1 = dimensions(matrix1)
    if dim1 is None:
        raise ValueError("matrix1 must be a non-empty list of lists")
    dim2 = dimensions(matrix2)
    if dim2 is None:
        raise ValueError("matrix2 must be a non-empty list of lists")
    if dim1 != dim2:
        raise ValueError("matrices must have the same dimensions")
    return [[a + b for a, b in zip(row1, row2)]
            for row1, row2 in zip(matrix1, matrix2)]


def format_number(value):
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_matrix(matrix, width=None):
    cells = [[format_number(value) for value in row] for row in matrix]
    if width is None:
        width = max((len(cell) for row in cells for cell in row), default=1)
    return "\n".join(" ".join(cell.rjust(width) for cell in row) for row in cells)


def add_from_text(text1, text2):
    """Parse two textual matrices and return their sum, or None if parsing fails."""
    left = parse_matrix(text1)
    if left is None:
        return None
    right = parse_matrix(text2)
    if right is None:
        return None
    return matrix_add(left, right)


