def portfolio_value(stocks, prices):
    """Total market value of a portfolio; tickers with no known price are skipped."""
    if stocks is None:
        raise ValueError("stocks must be provided")
    if prices is None:
        raise ValueError("prices must be provided")
    total = 0
    for ticker, quantity in stocks.items():
        price = prices.get(ticker)
        if price is None:
            continue
        total += quantity * price
    return total


def missing_prices(stocks, prices):
    """Tickers held in the portfolio for which no price is available."""
    absent = []
    for ticker in stocks:
        if prices.get(ticker) is None:
            absent.append(ticker)
    return sorted(absent)


def position_values(stocks, prices):
    """Map each priced holding to its value, largest first."""
    values = {}
    for ticker, quantity in stocks.items():
        price = prices.get(ticker)
        if price is not None:
            values[ticker] = quantity * price
    return dict(sorted(values.items(), key=lambda kv: (-kv[1], kv[0])))


def largest_position(stocks, prices):
    """Ticker with the greatest value, or None for an empty/unpriced portfolio."""
    values = position_values(stocks, prices)
    if not values:
        return None
    return next(iter(values))


def weight(stocks, prices, ticker):
    """Fraction of total value held in one ticker, or None if it cannot be computed."""
    total = portfolio_value(stocks, prices)
    if total == 0:
        return None
    value = position_values(stocks, prices).get(ticker)
    if value is None:
        return None
    return value / total


def format_report(stocks, prices):
    """Render one line per priced holding, plus unpriced tickers and the total."""
    lines = []
    total = portfolio_value(stocks, prices)
    for ticker, value in position_values(stocks, prices).items():
        share = weight(stocks, prices, ticker)
        share_text = "n/a" if share is None else "{:.1%}".format(share)
        lines.append("{:<6} {:>10.2f} {:>7}".format(ticker, value, share_text))
    skipped = missing_prices(stocks, prices)
    if skipped:
        lines.append("unpriced: " + ", ".join(skipped))
    top = largest_position(stocks, prices)
    if top is not None:
        lines.append("largest position: " + top)
    lines.append("TOTAL  {:>10.2f}".format(total))
    return "\n".join(lines)


def main():
    stocks = {'AAPL': 10, 'GOOG': 5, 'TSLA': 3}
    prices = {'AAPL': 150, 'GOOG': 1000, 'MSFT': 400}
    print(format_report(stocks, prices))
    print()
    print(portfolio_value({'AAPL': 10, 'GOOG': 5}, {'AAPL': 150, 'GOOG': 1000}))
    print(portfolio_value({}, {}))
    print(format_report({}, {}))


if __name__ == '__main__':
    main()

