def find_second_largest(numbers):
    """Return the second largest value in numbers, counting duplicates."""
    largest = None
    second = None
    for value in numbers:
        if largest is None or value > largest:
            second = largest
            largest = value
        elif second is None or value > second:
            second = value
    if second is None:
        raise ValueError("need at least two elements to find a second largest")
    return second


def parse_numbers(text):
    """Parse a line of whitespace or comma separated integers."""
    cleaned = text.replace(",", " ").split()
    numbers = []
    for token in cleaned:
        try:
            numbers.append(int(token))
        except ValueError:
            return None
    if len(numbers) < 2:
        return None
    return numbers


def describe(numbers):
    """Build a one line report about the largest and second largest values."""
    parsed = numbers if isinstance(numbers, list) else parse_numbers(numbers)
    if parsed is None:
        return "invalid input: need at least two integers"
    second = find_second_largest(parsed)
    largest = max(parsed)
    joined = ", ".join(str(n) for n in parsed)
    if second == largest:
        return "[%s] -> largest %d appears more than once, second largest %d" % (
            joined,
            largest,
            second,
        )
    return "[%s] -> largest %d, second largest %d" % (joined, largest, second)


def rank_gap(numbers):
    """Return the difference between the largest and second largest, or None."""
    if not numbers:
        return None
    parsed = parse_numbers(numbers) if isinstance(numbers, str) else list(numbers)
    if parsed is None:
        return None
    return max(parsed) - find_second_largest(parsed)


def main():
    samples = [
        [10, 5, 20, 8],
        [1, 1, 5, 5],
        "7 3 9 9 2",
        "4, 4",
        "oops 1 2",
        "42",
    ]
    for sample in samples:
        print(describe(sample))
        gap = rank_gap(sample)
        if gap is not None:
            print("    gap between the top two values: %d" % gap)
        else:
            print("    gap unavailable")


if __name__ == "__main__":
    main()

