import re
import sys

TOKEN = re.compile(r"(.)(\d+)")


def run_length_encode(s):
    """Return the run-length encoding of s, e.g. 'AAABBC' -> 'A3B2C1'."""
    if s is None:
        raise TypeError("run_length_encode() requires a string, not None")
    chunks = []
    previous = None
    count = 0
    for ch in s:
        if previous is not None and ch == previous:
            count += 1
            continue
        if previous is not None:
            chunks.append(previous + str(count))
        previous = ch
        count = 1
    if previous is not None:
        chunks.append(previous + str(count))
    return "".join(chunks)


def run_length_decode(encoded):
    """Expand an encoding produced by run_length_encode back to the original."""
    parts = []
    position = 0
    while position < len(encoded):
        match = TOKEN.match(encoded, position)
        if match is None:
            raise ValueError("malformed encoding at offset %d" % position)
        parts.append(match.group(1) * int(match.group(2)))
        position = match.end()
    return "".join(parts)


def compression_ratio(s, encoded=None):
    """Length of the encoding divided by the length of the original."""
    if encoded is None:
        encoded = run_length_encode(s)
    if not s:
        return 1.0
    return len(encoded) / len(s)


def longest_run(s):
    """Return (character, length) of the longest run, or None for an empty string."""
    best = None
    for match in TOKEN.finditer(run_length_encode(s)):
        length = int(match.group(2))
        if best is None or length > best[1]:
            best = (match.group(1), length)
    return best


def describe(s, label=None):
    """Build a one-line report about encoding s."""
    if label is None:
        label = repr(s)
    encoded = run_length_encode(s)
    verdict = "round-trip ok" if run_length_decode(encoded) == s else "ROUND-TRIP FAILED"
    run = longest_run(s)
    if run is None:
        peak = "no runs"
    else:
        peak = "longest run %s x%d" % (run[0], run[1])
    ratio = compression_ratio(s, encoded)
    return "%s -> %r [ratio %.2f, %s, %s]" % (label, encoded, ratio, peak, verdict)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    samples = argv if argv else ["AAABBC", "A", "", "WWWWWWWWWWWWBWWWWWWWWWWWWBBB"]
    for index, sample in enumerate(samples, start=1):
        print(describe(sample, label="sample %d" % index))
    return 0


if __name__ == "__main__":
    sys.exit(main())

