    verdict = "round-trip ok" if run_length_decode(encoded) == s else "ROUND-TRIP FAILED"
    run = longest_run(s)
    if run == None:
        peak = "no runs"
    else:
        peak = "longest run %s x%d" % (run[0], run[1])
    ratio = compression_ratio(s, encoded)
    return "%s -> %r [ratio %.2f, %s, %s]" % (label, encoded, ratio, peak, verdict)


def main(argv=None):
    if argv == None:
        argv = sys.argv[1:]
    samples = argv if argv else ["AAABBC", "A", "", "WWWWWWWWWWWWBWWWWWWWWWWWWBBB"]
    for index, sample in enumerate(samples, start=1):
        print(describe(sample, label="sample %d" % index))
    return 0


if __name__ == "__main__":
    sys.exit(main())

