STATUS_MESSAGES = {
    200: 'OK',
    404: 'Not Found',
    500: 'Internal Server Error',
}

STATUS_CLASSES = (
    (100, 'Informational'),
    (200, 'Success'),
    (300, 'Redirection'),
    (400, 'Client Error'),
    (500, 'Server Error'),
)


def check_http_status(status_code):
    message = STATUS_MESSAGES.get(status_code)
    if message is None:
        return 'Unknown Status'
    return message


def parse_status_code(text):
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        return None


def status_class(status_code):
    found = None
    for lower, name in STATUS_CLASSES:
        if lower <= status_code < lower + 100:
            found = name
    return found


def describe(text):
    code = parse_status_code(text)
    if code is None:
        return '%-8s -> invalid status code' % (text.strip() or '(empty)')
    family = status_class(code)
    description = check_http_status(code)
    if family is None:
        return '%-8d -> %s (outside any HTTP class)' % (code, description)
    return '%-8d -> %s [%s]' % (code, description, family)


def build_report(lines):
    report = []
    for line in lines:
        report.append(describe(line))
    return '\n'.join(report)


def main():
    raw_inputs = ['200', '404', '401', '500', '302', ' 100 ', '999', 'abc', '']
    print(build_report(raw_inputs))

    known = []
    for text in raw_inputs:
        code = parse_status_code(text)
        if code is None:
            continue
        if STATUS_MESSAGES.get(code) is not None:
            known.append(code)
    print('Known codes seen:', ', '.join(str(c) for c in sorted(known)))

    highest = None
    for code in known:
        if highest is None or code > highest:
            highest = code
    if highest is not None:
        print('Highest known code:', highest, '-', check_http_status(highest))


if __name__ == '__main__':
    main()

