    """Return a message explaining why `numbers` is unusable, or None if it is fine."""
    if numbers is None:
        return "no sequence was supplied"
    if not isinstance(numbers, (list, tuple)):
        return "expected a list or tuple of numbers"
    if len(numbers) == 0:
        return "the sequence is empty"
    expected_max = len(numbers) + 1
    seen = set()
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            return "all entries must be plain integers"
        if value < 1 or value > expected_max:
            return "values must lie between 1 and %d" % expected_max
        if value in seen:
            return "duplicate value %d found" % value
        seen.add(value)
    return None


def find_missing_number(numbers):
    """Return the single number missing from an unsorted list of 1..N."""
    error = validation_error(numbers)
    if error is not None:
        raise ValueError(error)
    total_count = len(numbers) + 1
    complete_sum = total_count * (total_count + 1) // 2
    return complete_sum - sum(numbers)


def parse_int(token):
    """Return the integer value of `token`, or None when it is not a plain integer."""
    try:
        return int(token)
    except ValueError:
        return None


def parse_sequence(text):
    """Turn a comma or space separated string into a list of ints, or None on failure."""
    values = []
    for token in text.replace(",", " ").split():
        value = parse_int(token)
        if value is None:
            return None
        values.append(value)
    return values


def split_label(line):
    """Split "set A: 1 2 4" into its label and numeric part; the label is None if absent."""
    if ":" in line:
        label, body = line.split(":", 1)
        return label.strip(), body
    return None, line


def format_report(line):
    """Describe the missing number for one line of user input."""
    label, body = split_label(line)
    heading = label if label is not None else body.strip()
    numbers = parse_sequence(body)
    if numbers is None:
        return "%-20s -> could not parse integers" % heading
    try:
        missing = find_missing_number(numbers)
    except ValueError as exc:
        return "%-20s -> invalid input (%s)" % (heading, exc)
    return "%-20s -> missing %d (range 1..%d)" % (heading, missing, len(numbers) + 1)


def read_sources(argv):
    """Gather sequences from the arguments or standard input, or None if none were given."""
    lines = [arg for arg in argv[1:] if arg.strip()]
    if not lines:
        lines = [line for line in sys.stdin.read().splitlines() if line.strip()]
    if lines:
        return lines
    return None


def main(argv):
    sources = read_sources(argv)
    if sources is None:
        print("usage: pass sequences as arguments or on standard input")
        return 1
    for source in sources:
        print(format_report(source))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

