def parse_event(line):
    """Parse a 'start-end' line; end may be blank or 'open' for open-ended."""
    text = line.split("#", 1)[0].strip()
    if not text:
        return None
    if "-" not in text:
        raise ValueError("event must look like 'start-end': %r" % line)
    head, tail = text.split("-", 1)
    start = int(head.strip())
    tail = tail.strip()
    end = None if tail in ("", "open") else int(tail)
    if end is not None and end <= start:
        raise ValueError("event ends before it starts: %r" % line)
    return (start, end)


def load_schedule(lines):
    schedule = []
    for line in lines:
        event = parse_event(line)
        if event is not None:
            schedule.append(event)
    schedule.sort(key=lambda ev: ev[0])
    return schedule


def _overlaps(a_start, a_end, b_start, b_end):
    if a_end is not None and b_start >= a_end:
        return False
    if b_end is not None and a_start >= b_end:
        return False
    return True


def has_conflict(schedule, new_event_start, new_event_end):
    """True if the new event overlaps any event already in the schedule."""
    if new_event_end is not None and new_event_end <= new_event_start:
        raise ValueError("new event ends before it starts")
    for start, end in schedule:
        if _overlaps(start, end, new_event_start, new_event_end):
            return True
    return False


def first_conflict(schedule, new_event_start, new_event_end):
    """Return the earliest conflicting event, or None when the slot is free."""
    for start, end in sorted(schedule, key=lambda ev: ev[0]):
        if _overlaps(start, end, new_event_start, new_event_end):
            return (start, end)
    return None


def earliest_free_slot(schedule, duration, horizon):
    """Smallest start time in [0, horizon] fitting duration, else None."""
    for candidate in range(0, horizon - duration + 1):
        if not has_conflict(schedule, candidate, candidate + duration):
            return candidate
    return None


def format_event(event):
    start, end = event
    if end is None:
        return "%d-open" % start
    return "%d-%d" % (start, end)


def main():
    raw = ["1-5", "10-15  # standup", "", "20-open"]
    schedule = load_schedule(raw)
    print("schedule:", ", ".join(format_event(ev) for ev in schedule))
    for start, end in [(3, 7), (6, 8), (16, 19), (22, 23), (18, None)]:
        clash = first_conflict(schedule, start, end)
        label = format_event((start, end))
        if clash is None:
            print("%s -> free" % label)
        else:
            print("%s -> conflicts with %s" % (label, format_event(clash)))
    slot = earliest_free_slot(schedule, 3, 20)
    if slot is None:
        print("no 3-unit slot before 20")
    else:
        print("earliest 3-unit slot starts at", slot)


if __name__ == "__main__":
    main()

