import sys


def count_uppercase(text):
    """Return the number of uppercase letters in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    count = 0
    for char in text:
        if char.isupper():
            count += 1
    return count


def first_uppercase_index(text):
    """Return the index of the first uppercase letter, or None if there is none."""
    for index, char in enumerate(text):
        if char.isupper():
            return index
    return None


def uppercase_ratio(text):
    """Return the share of uppercase letters among all letters, or None if no letters."""
    letters = [char for char in text if char.isalpha()]
    if not letters:
        return None
    return count_uppercase(text) / len(letters)


def describe(text, label=None):
    """Build a one-line human readable summary of the uppercase content of text."""
    if label is None:
        label = repr(text)
    total = count_uppercase(text)
    parts = ["{0}: {1} uppercase".format(label, total)]
    position = first_uppercase_index(text)
    if position is not None:
        parts.append("first at index {0}".format(position))
    ratio = uppercase_ratio(text)
    if ratio is not None:
        parts.append("{0:.0%} of letters".format(ratio))
    return ", ".join(parts)


def collect_inputs(argv):
    """Pick the strings to analyse: the given arguments, or the built-in examples."""
    if not argv:
        return ["Hello World", "python is fun"]
    return list(argv)


def loudest_input(texts):
    """Return the text with the most uppercase letters, or None if none has any."""
    best = None
    for text in texts:
        if count_uppercase(text) == 0:
            continue
        if best is None or count_uppercase(text) > count_uppercase(best):
            best = text
    return best


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    texts = collect_inputs(argv)
    grand_total = 0
    for text in texts:
        grand_total += count_uppercase(text)
        print(describe(text))
    print("total uppercase letters: {0}".format(grand_total))
    loudest = loudest_input(texts)
    if loudest is not None:
        print(describe(loudest, label="loudest input"))
    return 0


if __name__ == "__main__":
    sys.exit(main())

