import sys


def char_frequency(text):
    """Count characters in text, ignoring case."""
    if text is None:
        raise ValueError("text must be a string, not None")
    frequency_map = {}
    for char in text.lower():
        current = frequency_map.get(char)
        if current is None:
            frequency_map[char] = 1
        else:
            frequency_map[char] = current + 1
    return frequency_map


def frequency_of(frequency_map, char):
    """Return how often char occurs, case-insensitively."""
    count = frequency_map.get(char.lower())
    if count is None:
        return 0
    return count


def most_common(frequency_map, limit=None):
    """Return (char, count) pairs sorted by count desc, then character."""
    ordered = sorted(frequency_map.items(), key=lambda item: (-item[1], item[0]))
    if limit is None:
        return ordered
    return ordered[:limit]


def first_difference(left_map, right_map):
    """Return the first character (alphabetically) whose counts differ."""
    for char in sorted(set(left_map) | set(right_map)):
        if frequency_of(left_map, char) != frequency_of(right_map, char):
            return char
    return None


def format_report(text, frequency_map=None, limit=None):
    """Build a human readable frequency report for text."""
    if frequency_map is None:
        frequency_map = char_frequency(text)
    lines = ["text: %r" % text, "distinct characters: %d" % len(frequency_map)]
    for char, count in most_common(frequency_map, limit):
        label = repr(char) if char.isspace() else char
        lines.append("  %s -> %d" % (label, count))
    return "\n".join(lines)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    samples = argv if argv else ["hello", "Python", "Mississippi River"]
    previous_text = None
    previous_map = None
    for text in samples:
        frequency_map = char_frequency(text)
        print(format_report(text, frequency_map, limit=5))
        if previous_map is not None:
            char = first_difference(previous_map, frequency_map)
            if char is None:
                print("  same character profile as %r" % previous_text)
            else:
                print("  differs from %r first at %r (%d vs %d)" % (
                    previous_text, char,
                    frequency_of(previous_map, char),
                    frequency_of(frequency_map, char)))
        previous_text = text
        previous_map = frequency_map
    return 0


if __name__ == "__main__":
    sys.exit(main())

