    """Convert a single text token to an int or float, or None if it is not numeric."""
    text = token.strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return None


def parse_numbers(line):
    """Parse a comma/space separated line into a list of numbers, or None on bad input."""
    raw = line.replace(",", " ").split()
    values = []
    for token in raw:
        value = parse_number(token)
        if value is None:
            return None
        values.append(value)
    return values


def calculate_median(numbers):
    """Return the median of a list of int/float values, or None for an empty list."""
    if numbers is None:
        return None
    ordered = sorted(numbers)
    count = len(ordered)
    if count == 0:
        return None
    middle = count // 2
    if count % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2


def summarize(numbers):
    """Build a small statistics dictionary; the median entry may be None."""
    median_value = calculate_median(numbers)
    if median_value is None:
        return {"count": 0, "median": None, "spread": None}
    return {
        "count": len(numbers),
        "median": median_value,
        "spread": max(numbers) - min(numbers),
    }


def format_report(line, summary):
    if summary is None:
        return "%-22s -> could not parse numbers" % line
    if summary["median"] is None:
        return "%-22s -> no data" % line
    return "%-22s -> n=%d median=%s spread=%s" % (
        line,
        summary["count"],
        summary["median"],
        summary["spread"],
    )


def main():
    lines = [
        "1 2 3 4 5",
        "1, 2, 3, 4",
        "7.5 -2 0 3.25 10 4",
        "",
        "3 apples 5",
    ]
    for line in lines:
        numbers = parse_numbers(line)
        summary = summarize(numbers) if numbers is not None else None
        print(format_report(line if line else "<empty>", summary))


if __name__ == "__main__":
    main()

