def coerce_separator(separator):
    """Return a usable separator string; a missing separator means 'no glue'."""
    if separator is None:
        return ''
    if not isinstance(separator, str):
        raise TypeError('separator must be a string or None')
    return separator


def find_first_invalid(items):
    """Return the index of the first element that is not a string, else None."""
    for index, item in enumerate(items):
        if not isinstance(item, str):
            return index
    return None


def join_elements(items, separator):
    if items is None:
        raise TypeError('items must be a list of strings')
    items = list(items)
    glue = coerce_separator(separator)
    bad = find_first_invalid(items)
    if bad is not None:
        raise TypeError('items[%d] is not a string: %r' % (bad, items[bad]))
    return glue.join(items)


def parse_args(argv):
    """Split argv into a separator (None when unspecified) and the items."""
    separator = None
    items = []
    position = 0
    while position < len(argv):
        token = argv[position]
        if token == '--sep':
            if position + 1 >= len(argv):
                raise SystemExit('--sep requires a value')
            separator = argv[position + 1]
            position += 2
        else:
            items.append(token)
            position += 1
    return separator, items


def describe(separator):
    if separator is None:
        return 'default separator ", "'
    return 'separator %r' % separator


def format_report(items, separator):
    effective = separator
    if effective is None:
        effective = ', '
    joined = join_elements(items, effective)
    return '%d element(s) with %s -> %s' % (len(items), describe(separator), joined)


def main(argv=None):
    if argv is None:
        argv = ['apple', 'banana', 'cherry']
    separator, items = parse_args(argv)
    if not items:
        print('no elements given')
        return
    print(format_report(items, separator))
    print(join_elements(items, '-'))


if __name__ == '__main__':
    import sys
    main(sys.argv[1:] or None)

