import sys
import os

_LINE_COUNT_CACHE = {}


def count_file_lines(filepath):
    """Return the number of lines in the text file at *filepath*."""
    cached = _LINE_COUNT_CACHE.get(filepath)
    if cached is not None:
        return cached
    with open(filepath, "r", encoding="utf-8") as handle:
        line_count = sum(1 for _ in handle)
    _LINE_COUNT_CACHE[filepath] = line_count
    return line_count


def count_many_files(filepaths):
    """Map every path to its line count, skipping entries that are not files."""
    counts = {}
    for path in filepaths:
        if os.path.isfile(path):
            counts[path] = count_file_lines(path)
    return counts


def filter_counts(counts, min_lines=None):
    """Keep only files with at least *min_lines* lines; no limit means keep all."""
    if min_lines is None:
        return dict(counts)
    return {path: count for path, count in counts.items() if count >= min_lines}


def largest_file(counts):
    """Return the path with the most lines, or None when there is nothing."""
    winner = None
    for path, count in counts.items():
        if winner is None or count > counts[winner]:
            winner = path
    return winner


def average_lines(counts):
    """Return the mean line count, or None when no file was measured."""
    if not counts:
        return None
    return sum(counts.values()) / len(counts)


def format_row(path, count, width=None):
    if width is None:
        width = len(path)
    return "{0:<{1}}  {2:>7}".format(path, width, count)


def build_report(counts):
    mean = average_lines(counts)
    if mean is None:
        return "no matching files"
    width = max(len(path) for path in counts)
    rows = [format_row(path, counts[path], width) for path in sorted(counts)]
    rows.append(format_row("average", round(mean, 2), width))
    biggest = largest_file(counts)
    rows.append("longest: {0} ({1} lines)".format(biggest, counts[biggest]))
    return "\n".join(rows)


def parse_args(argv):
    """Split command line arguments into (paths, min_lines)."""
    paths = []
    min_lines = None
    pending_min = False
    for arg in argv:
        if pending_min:
            min_lines = int(arg)
            pending_min = False
        elif arg in ("-m", "--min"):
            pending_min = True
        else:
            paths.append(arg)
    if pending_min:
        raise ValueError("--min requires a value")
    return paths, min_lines


def main(argv):
    paths, min_lines = parse_args(argv[1:])
    if not paths:
        print("usage: {0} [--min N] FILE...".format(argv[0]))
        return 2
    print(build_report(filter_counts(count_many_files(paths), min_lines)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

