import sys

ALPHABET_SIZE = 26
COMMON_WORDS = frozenset(
    ["the", "there", "hello", "world", "and", "this", "that", "with", "secret", "message"]
)


def parse_shift(raw):
    """Turn a textual shift into an int, or None when it is absent/unusable."""
    if raw is None:
        return None
    raw = raw.strip()
    if not raw:
        return None
    try:
        return int(raw)
    except ValueError:
        return None


def parse_args(argv=None):
    """Build the list of (ciphertext, raw_shift) jobs to process."""
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        return [("khoor", "3"), ("wkhuh", "3"), ("khoor zruog", None)]
    return [(argv[0], argv[1] if len(argv) > 1 else None)]


def decrypt_caesar(text, shift=None):
    """Return text shifted back by `shift`; when shift is None, guess the key."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if shift is None:
        shift = crack_shift(text)
    shift %= ALPHABET_SIZE
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - ord("a") - shift) % ALPHABET_SIZE + ord("a")))
        else:
            out.append(ch)
    return "".join(out)


def score_plaintext(candidate):
    """Count how many whitespace-separated tokens look like known English words."""
    hits = 0
    for token in candidate.split():
        if token.strip(".,!?;:") in COMMON_WORDS:
            hits += 1
    return hits


def crack_shift(text):
    """Return the shift whose decryption yields the most recognisable words."""
    best_shift = None
    best_score = 0
    for candidate_shift in range(ALPHABET_SIZE):
        score = score_plaintext(decrypt_caesar(text, candidate_shift))
        if best_shift is None or score > best_score:
            best_score = score
            best_shift = candidate_shift
    return best_shift


def resolve_shift(text, raw_shift):
    """Return (shift, source) for a job, cracking the key when none was given."""
    shift = parse_shift(raw_shift)
    if shift is not None:
        return shift % ALPHABET_SIZE, "given"
    return crack_shift(text), "auto"


def report(text, raw_shift=None):
    """Format one decryption job as a single human-readable line."""
    shift, source = resolve_shift(text, raw_shift)
    return "%s -> %s [key=%d, %s]" % (text, decrypt_caesar(text, shift), shift, source)


def main():
    for cipher, raw in parse_args():
        print(report(cipher, raw))


if __name__ == "__main__":
    main()

