def parse_guess(text):
    """Convert raw user input to an int, or return None if it is not a number."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        return None


def simulate_guess(target, guess):
    """Return feedback for a single guess against the target number."""
    if guess > target:
        return 'Too high'
    if guess < target:
        return 'Too low'
    return 'Correct!'


def play_round(target, text, low=None, high=None):
    """Parse the raw input, validate its range, and produce feedback."""
    guess = parse_guess(text)
    if guess is None:
        return 'Please enter a whole number'
    if low is not None and guess < low:
        return 'Out of range'
    if high is not None and guess > high:
        return 'Out of range'
    return simulate_guess(target, guess)


def play_game(target, inputs, low=None, high=None):
    """Feed a sequence of raw inputs to the game, stopping once solved."""
    transcript = []
    winner = None
    for attempt, text in enumerate(inputs, start=1):
        feedback = play_round(target, text, low, high)
        transcript.append((attempt, text, feedback))
        if feedback == 'Correct!':
            winner = attempt
            break
    return transcript, winner


def format_report(transcript, winner, target):
    """Render the transcript and the outcome as readable lines of text."""
    lines = []
    for attempt, text, feedback in transcript:
        shown = 'blank' if parse_guess(text) is None else text.strip()
        lines.append("Attempt {0}: {1} -> {2}".format(attempt, shown, feedback))
    if winner is None:
        lines.append("Target {0} was never guessed.".format(target))
    else:
        lines.append("Guessed {0} in {1} attempt(s).".format(target, winner))
    return "\n".join(lines)


def main():
    secret = 7
    attempts = ['5', ' 9 ', 'nine', '99', '7', '3']
    transcript, winner = play_game(secret, attempts, low=1, high=50)
    print(format_report(transcript, winner, secret))

    stubborn = 42
    tries = ['1', '100', '41']
    transcript, winner = play_game(stubborn, tries, low=1, high=99)
    print(format_report(transcript, winner, stubborn))


if __name__ == '__main__':
    main()

