def count_words(text):
    """Count words in `text`, where words are separated by runs of spaces."""
    if text is None:
        raise ValueError("text must be a string, not None")
    word_count = 0
    in_word = False
    for char in text:
        if char.isspace():
            in_word = False
        elif not in_word:
            in_word = True
            word_count += 1
    return word_count


def longest_word(text, minimum_length=None):
    """Return the longest word in `text`, ignoring words shorter than a bound."""
    best = None
    for word in text.split():
        if minimum_length is not None and len(word) < minimum_length:
            continue
        if best is None or len(word) > len(best):
            best = word
    return best


def average_word_length(text):
    """Mean length of the words in `text`, or None when there are no words."""
    total = count_words(text)
    if total == 0:
        return None
    characters = sum(len(word) for word in text.split())
    return characters / total


def summarize(text, label=None):
    """Build a dictionary describing the word statistics of `text`."""
    if label is None:
        label = text.strip()[:20] or "(empty)"
    return {
        "label": label,
        "words": count_words(text),
        "longest": longest_word(text),
        "average": average_word_length(text),
    }


def format_summary(summary):
    """Render a summary dictionary as a single human-readable line."""
    parts = ["{0}: {1} word(s)".format(summary["label"], summary["words"])]
    longest = summary["longest"]
    if longest is not None:
        parts.append("longest={0!r}".format(longest))
    average = summary["average"]
    if average is None:
        parts.append("average=n/a")
    else:
        parts.append("average={0:.2f}".format(average))
    return ", ".join(parts)


