def simulate_stack(stack, operation, item=None):
    """Perform a single stack operation and return its result."""
    if stack is None:
        raise ValueError("stack must be a list, not None")
    if operation == 'push':
        if item is None:
            raise ValueError("'push' requires an item")
        stack.append(item)
        return stack
    if operation == 'pop':
        if not stack:
            return None
        return stack.pop()
    raise ValueError("unknown operation: %r" % (operation,))


def parse_command(line):
    """Turn a text command like 'push 7' into (operation, item) or None."""
    text = line.strip()
    if not text or text.startswith('#'):
        return None
    parts = text.split(None, 1)
    operation = parts[0].lower()
    raw = parts[1].strip() if len(parts) > 1 else None
    if raw is None:
        return operation, None
    return operation, convert_item(raw)


def convert_item(raw):
    """Interpret a textual item as an int when possible, else keep the text."""
    try:
        return int(raw)
    except ValueError:
        return raw


def describe(operation, result):
    """Build a human readable line for the outcome of one operation."""
    if operation == 'pop' and result is None:
        return "pop     -> empty stack"
    if operation == 'pop':
        return "pop     -> %r" % (result,)
    return "push    -> %r" % (result,)


def run_script(stack, lines):
    """Apply every command in lines to stack, collecting report lines."""
    report = []
    for line in lines:
        command = parse_command(line)
        if command is None:
            continue
        operation, item = command
        result = simulate_stack(stack, operation, item)
        report.append(describe(operation, result))
    return report


def main():
    script = [
        "push 1",
        "push 2",
        "push 3",
        "# now drain it",
        "pop",
        "pop",
        "push hello",
        "pop",
        "pop",
        "pop",
    ]
    stack = []
    for line in run_script(stack, script):
        print(line)
    print("final stack: %r" % (stack,))


if __name__ == '__main__':
    main()

