def parse_point(text):
    """Parse a string like '1, 2' or '(1 2)' into a tuple of floats, or None."""
    cleaned = text.strip().strip("()[]")
    if not cleaned:
        return None
    parts = cleaned.replace(",", " ").split()
    if len(parts) != 2:
        return None
    try:
        return (float(parts[0]), float(parts[1]))
    except ValueError:
        return None


def manhattan_distance(p1, p2):
    """Return the Manhattan distance between two 2D points."""
    if p1 is None:
        raise ValueError("first point is required")
    if p2 is None:
        raise ValueError("second point is required")
    if len(p1) != 2 or len(p2) != 2:
        raise ValueError("points must have exactly two coordinates")
    return float(abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]))


def closest_point(origin, candidates):
    """Return the candidate closest to origin, or None if there are none."""
    best = None
    best_distance = None
    for point in candidates:
        distance = manhattan_distance(origin, point)
        if best_distance is None or distance < best_distance:
            best = point
            best_distance = distance
    return best


def format_point(point):
    return "({0:g}, {1:g})".format(point[0], point[1])


def distance_report(pairs):
    """Build readable lines for pairs of raw point strings."""
    lines = []
    for raw1, raw2 in pairs:
        p1 = parse_point(raw1)
        p2 = parse_point(raw2)
        if p1 is None:
            lines.append("skipped: cannot parse {0!r}".format(raw1))
            continue
        if p2 is None:
            lines.append("skipped: cannot parse {0!r}".format(raw2))
            continue
        d = manhattan_distance(p1, p2)
        lines.append("{0} -> {1} = {2:.1f}".format(format_point(p1), format_point(p2), d))
    return lines


def main():
    pairs = [
        ("1, 1", "4, 5"),
        ("(0 0)", "(-2, -3)"),
        ("2.5, -1", "bad input"),
    ]
    for line in distance_report(pairs):
        print(line)

    origin = parse_point("0, 0")
    candidates = [parse_point(t) for t in ("3, 4", "-1, 1", "oops", "5, -5")]
    usable = [c for c in candidates if c is not None]
    nearest = closest_point(origin, usable)
    if nearest is None:
        print("no candidates available")
    else:
        print("nearest to {0}: {1} at {2:.1f}".format(
            format_point(origin), format_point(nearest),
            manhattan_distance(origin, nearest)))


if __name__ == "__main__":
    main()

