import sys


def cubes_up_to(limit):
    """Return the cubes of every integer from 0 to limit inclusive."""
    if limit is None:
        raise ValueError("limit must be an integer, not None")
    if limit < 0:
        raise ValueError("limit must be non-negative")
    cubes_list = [n ** 3 for n in range(limit + 1)]
    return cubes_list


def parse_limit(text):
    """Convert a command-line argument to an int, or None if it is unusable."""
    if text is None:
        return None
    stripped = text.strip()
    try:
        value = int(stripped)
    except ValueError:
        return None
    if value < 0:
        return None
    return value


def cube_root_index(value, cubes):
    """Return the integer whose cube is value, or None when value is not a cube."""
    for index, cube in enumerate(cubes):
        if cube == value:
