import random
import sys

DEFAULT_LENGTH = 4
MAX_ATTEMPTS = 50


def validate_length(length):
    if length is None:
        raise ValueError("length must be provided")
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    return length


def generate_pin(length, rng=None):
    validate_length(length)
    if rng is None:
        rng = random.SystemRandom()
    return "".join(str(rng.randrange(10)) for _ in range(length))


def weakness_of(pin):
    if len(set(pin)) == 1:
        return "all digits identical"
    digits = [int(c) for c in pin]
    steps = {b - a for a, b in zip(digits, digits[1:])}
    if steps == {1}:
        return "ascending run"
    if steps == {-1}:
        return "descending run"
    return None


def generate_strong_pin(length, rng=None, attempts=MAX_ATTEMPTS):
    validate_length(length)
    fallback = None
    for _ in range(attempts):
        pin = generate_pin(length, rng)
        if weakness_of(pin) is None:
            return pin
        if fallback is None:
            fallback = pin
    return fallback


def parse_length(argv):
    if len(argv) < 2:
        return None
    try:
        return int(argv[1])
    except ValueError:
        return None


def format_report(pin, weakness):
    if weakness is None:
        return "PIN %s (%d digits) looks fine" % (pin, len(pin))
    return "PIN %s (%d digits) is weak: %s" % (pin, len(pin), weakness)


def main(argv):
    requested = parse_length(argv)
    if requested is None:
        length = DEFAULT_LENGTH
    else:
        length = requested
    try:
        validate_length(length)
    except (TypeError, ValueError) as exc:
        print("error: %s" % exc)
        return 1
    plain = generate_pin(length)
    print(format_report(plain, weakness_of(plain)))
    strong = generate_strong_pin(length, rng=random.SystemRandom())
    if strong is None:
        print("error: could not generate a PIN")
        return 1
    print(format_report(strong, weakness_of(strong)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

