def first_duplicate(text):
    """Return (character, index) for the first repeated character, or None."""
    seen = {}
    for index, char in enumerate(text):
        if char in seen:
            return char, index
        seen[char] = index
    return None


def has_unique_chars(text):
    """Return True if every character of text occurs exactly once."""
    if text is None:
        raise ValueError("text must be a string, not None")
    return first_duplicate(text) is None


def describe(text):
    """Build a one-line verdict for a single candidate string."""
    duplicate = first_duplicate(text)
    if duplicate is None:
        return "{!r:<14} unique".format(text)
    char, index = duplicate
    return "{!r:<14} repeats {!r} at index {}".format(text, char, index)


def longest_unique_prefix(text):
    """Return the longest starting slice of text without a repeated character."""
    duplicate = first_duplicate(text)
    if duplicate is None:
        return text
    return text[:duplicate[1]]


def parse_line(line):
    """Turn a raw input line into a candidate, or None for blanks and comments."""
    stripped = line.strip()
    if not stripped or stripped.startswith("#"):
        return None
    if len(stripped) >= 2 and stripped.startswith('"') and stripped.endswith('"'):
        return stripped[1:-1]
    return stripped


def read_candidates(lines):
    """Collect every usable candidate string from raw input lines."""
    candidates = []
    for line in lines:
        candidate = parse_line(line)
        if candidate is not None:
            candidates.append(candidate)
    return candidates


def first_repeating(candidates):
    """Return the first candidate containing a repeat, or None if all are unique."""
    for candidate in candidates:
        if not has_unique_chars(candidate):
            return candidate
    return None


def main():
    raw_lines = [
        "# candidate strings",
        "abcde",
        "hello",
        '"  spaced  "',
        "",
        "Aa",
        "programming",
    ]
    candidates = read_candidates(raw_lines)
    for candidate in candidates:
        print("{} -> {}".format(describe(candidate), has_unique_chars(candidate)))
    offender = first_repeating(candidates)
    if offender is None:
        print("all candidates have unique characters")
    else:
        print("first offender {!r}, unique prefix {!r}".format(
            offender, longest_unique_prefix(offender)))


if __name__ == "__main__":
    main()

