from typing import Iterable, List, Optional


def parse_number(text: str) -> Optional[int]:
    """Return the integer contained in *text*, or None if it is not an integer."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped, 10)
    except ValueError:
        return None


def is_divisible_by_3_and_5(number) -> bool:
    """Return True when *number* is divisible by both 3 and 5."""
    if number is None:
        raise TypeError("number must be an int, not None")
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    return number % 3 == 0 and number % 5 == 0


def describe(number: int) -> str:
    verdict = "is" if is_divisible_by_3_and_5(number) else "is not"
    return "{} {} divisible by both 3 and 5".format(number, verdict)


def describe_text(text: str) -> str:
    """Describe a raw textual input, reporting unparsable values gracefully."""
    number = parse_number(text)
    if number is None:
        return "{!r} is not a valid integer".format(text)
    return describe(number)


def filter_divisible(values: Iterable[Optional[int]]) -> List[int]:
    """Keep the values that are divisible by 3 and 5, skipping missing entries."""
    kept = []
    for value in values:
        if value is None:
            continue
        if is_divisible_by_3_and_5(value):
            kept.append(value)
    return kept


def first_divisible(values: Iterable[Optional[int]]) -> Optional[int]:
    """Return the first qualifying value, or None when there is none."""
    for value in values:
        if value is not None and is_divisible_by_3_and_5(value):
            return value
    return None


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = ["15", "10", "0", "-30", "seven", "45"]

    for token in argv:
        print(describe_text(token))

    parsed = [parse_number(token) for token in argv]
    print("divisible:", filter_divisible(parsed))

    winner = first_divisible(parsed)
    if winner is None:
        print("no value was divisible by both 3 and 5")
    else:
        print("first divisible value:", winner)
    return 0


if __name__ == "__main__":
    import sys

    args = sys.argv[1:] if len(sys.argv) > 1 else None
    raise SystemExit(main(args))

