def validate_input(dict_list, key):
    """Check the arguments and return the list of records to sort."""
    if dict_list is None:
        raise ValueError("dict_list must be a list, not None")
    if key is None:
        raise ValueError("key must be a string, not None")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    for index, record in enumerate(dict_list):
        if not isinstance(record, dict):
            raise TypeError("element %d is not a dictionary" % index)
    return list(dict_list)


def sort_rank(record, key):
    """Build a sort rank so that missing keys and None values go last."""
    if key not in record:
        return (2, 0, "")
    value = record[key]
    if value is None:
        return (1, 0, "")
    if isinstance(value, bool):
        return (0, int(value), "")
    if isinstance(value, (int, float)):
        return (0, value, "")
    return (0, 0, str(value))


def sort_dicts_by_key(dict_list, key):
    """Return a new list of the dictionaries ordered by dict[key]."""
    records = validate_input(dict_list, key)
    return sorted(records, key=lambda record: sort_rank(record, key))


def describe_value(record, key):
    """Render the value of key for a report line."""
    value = record.get(key)
    if key not in record:
        return "<missing>"
    if value is None:
        return "<none>"
    return repr(value)


def first_incomparable(dict_list, key):
    """Return the first record whose key is absent or None, else None."""
    for record in dict_list:
        if record.get(key) is None:
            return record
    return None


def report(dict_list, key):
    """Return a printable report of the sorted list."""
    sorted_list = sort_dicts_by_key(dict_list, key)
    lines = ["sorted by %r:" % key]
    for position, record in enumerate(sorted_list, start=1):
        lines.append("  %d. %s -> %s" % (position, record, describe_value(record, key)))
    odd = first_incomparable(sorted_list, key)
    if odd is not None:
        lines.append("  note: %s has no usable value for %r" % (odd, key))
    return "\n".join(lines)


