import sys


def parse_int(value):
    """Return the integer described by value, or None if it is not an integer."""
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    text = str(value).strip()
    if not text:
        return None
    try:
        return int(text, 10)
    except ValueError:
        return None


def generate_times_table(number, limit):
    """Return the times table of `number` up to `limit` as a list of strings."""
    base = parse_int(number)
    if base is None:
        raise TypeError("number must be an integer, got %r" % (number,))
    top = parse_int(limit)
    if top is None:
        raise TypeError("limit must be an integer, got %r" % (limit,))
    table_list = []
    for multiplier in range(1, top + 1):
        table_list.append("%d x %d = %d" % (base, multiplier, base * multiplier))
    return table_list


def format_table(number, limit, title=None):
    """Render a times table as a single printable block, with an optional title."""
    rows = generate_times_table(number, limit)
    heading = title
    if heading is None:
        heading = "Times table for %s" % parse_int(number)
    if not rows:
        return heading + "\n(no entries)"
    return heading + "\n" + "\n".join(rows)


def read_arguments(argv):
    """Turn command line words into (number, limit), or None when unusable."""
    if len(argv) != 2:
        return None
    number = parse_int(argv[0])
    if number is None:
        return None
    limit = parse_int(argv[1])
    if limit is None:
        return None
    return number, limit


def main(argv):
    pair = read_arguments(argv)
    if pair is None:
        print("usage: times_table.py NUMBER LIMIT")
        print(format_table(2, 3, title="Example: 2 up to 3"))
        print(format_table(5, 1))
        return 1
    number, limit = pair
    if limit < 1:
        print("limit must be at least 1")
        return 2
    print(format_table(number, limit))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

