def minutes_to_hh_mm(total_minutes):
    """Convert a total number of minutes into a 'HH:MM' string."""
    if total_minutes is None:
        raise ValueError("total_minutes must be an int, not None")
    if isinstance(total_minutes, bool) or not isinstance(total_minutes, int):
        raise TypeError("total_minutes must be an int")
    if total_minutes < 0:
        raise ValueError("total_minutes must not be negative")
    hours, minutes = divmod(total_minutes, 60)
    return "{:02d}:{:02d}".format(hours, minutes)


def parse_hh_mm(text):
    """Return the minute count for a 'HH:MM' string, or None if it is malformed."""
    if text is None:
        return None
    parts = text.strip().split(":")
    if len(parts) != 2:
        return None
    hours_text, minutes_text = parts
    if not hours_text.isdigit() or not minutes_text.isdigit():
        return None
    minutes = int(minutes_text)
    if minutes > 59:
        return None
    return int(hours_text) * 60 + minutes


def total_of(entries, cap=None):
    """Sum minute values, skipping unreadable entries; clamp to cap when given."""
    total = 0
    for entry in entries:
        if isinstance(entry, str):
            value = parse_hh_mm(entry)
        else:
            value = entry
        if value is None:
            continue
        total += value
    if cap is not None and total > cap:
        total = cap
    return total


def report(entries, cap=None):
    """Build report lines for the entries plus a total line."""
    lines = []
    for entry in entries:
        value = entry if not isinstance(entry, str) else parse_hh_mm(entry)
        if value is None:
            lines.append("{!r:>10} -> unreadable".format(entry))
        else:
            lines.append("{!r:>10} -> {}".format(entry, minutes_to_hh_mm(value)))
    total = total_of(entries, cap)
    lines.append("     total -> " + minutes_to_hh_mm(total))
    if cap is not None and total == cap:
        lines.append("     (capped at " + minutes_to_hh_mm(cap) + ")")
    return lines


def main():
    print(minutes_to_hh_mm(70))
    print(minutes_to_hh_mm(1440))
    timesheet = ["01:10", "00:45", "7:99", None, 125, "12:00"]
    for line in report(timesheet, cap=24 * 60):
        print(line)
    restored = parse_hh_mm(minutes_to_hh_mm(605))
    if restored is None:
        print("round trip failed")
    else:
        print("round trip minutes:", restored)


if __name__ == "__main__":
    main()

