def find_third_largest(numbers):
    """Return the third largest distinct value, or the largest if fewer than three exist."""
    if not numbers:
        raise ValueError("cannot pick a value from an empty list")
    first = None
    second = None
    third = None
    for value in numbers:
        if first is None or value > first:
            third = second
            second = first
            first = value
        elif value == first:
            continue
        elif second is None or value > second:
            third = second
            second = value
        elif value == second:
            continue
        elif third is None or value > third:
            third = value
    if third is None:
        return first
    return third


def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of ints, or None if malformed."""
    cleaned = text.replace(",", " ").split()
    if not cleaned:
        return None
    values = []
    for token in cleaned:
        try:
            values.append(int(token))
        except ValueError:
            return None
    return values


def describe(text):
    """Build a human readable line about the third largest value in a parsed input."""
    numbers = parse_numbers(text)
    if numbers is None:
        return "%r -> not a list of integers" % text
    distinct = len(set(numbers))
    answer = find_third_largest(numbers)
    if distinct < 3:
        return "%s -> %d (only %d distinct value(s), so the largest)" % (numbers, answer, distinct)
    return "%s -> %d (third largest distinct)" % (numbers, answer)


