HEX_DIGITS = "0123456789ABCDEF"
DIGIT_VALUES = {ch: i for i, ch in enumerate(HEX_DIGITS)}


def decimal_to_hex(decimal_num, width=None):
    """Return the uppercase hexadecimal representation of an integer."""
    if isinstance(decimal_num, bool) or not isinstance(decimal_num, int):
        raise TypeError("decimal_num must be an int")
    if width is not None and width < 1:
        raise ValueError("width must be positive")

    negative = decimal_num < 0
    value = -decimal_num if negative else decimal_num

    digits = []
    while value > 0:
        digits.append(HEX_DIGITS[value % 16])
        value //= 16
    if not digits:
        digits.append("0")

    hex_string = "".join(reversed(digits))
    if width is not None:
        hex_string = hex_string.rjust(width, "0")
    if negative:
        hex_string = "-" + hex_string
    return hex_string


def parse_decimal(text):
    """Parse a decimal literal, returning None when the text is not valid."""
    stripped = text.strip()
    body = stripped[1:] if stripped[:1] in ("+", "-") else stripped
    if not body.isdigit():
        return None
    return int(stripped)


def hex_to_decimal(hex_string):
    """Invert decimal_to_hex; return None if the string is not hexadecimal."""
    text = hex_string.strip().upper()
    sign = 1
    if text[:1] in ("+", "-"):
        sign = -1 if text[0] == "-" else 1
        text = text[1:]
    if not text:
        return None
    total = 0
    for ch in text:
        digit = DIGIT_VALUES.get(ch)
        if digit is None:
            return None
        total = total * 16 + digit
    return sign * total


def format_row(text, width=None):
    """Convert one token: decimals become hex, hex tokens become decimals."""
    number = parse_decimal(text)
    if number is not None:
        return "{} -> {}".format(number, decimal_to_hex(number, width))
    value = hex_to_decimal(text)
    if value is None:
        return "{!r} -> not a number".format(text)
    return "{} -> {}".format(text.strip().upper(), value)


def main():
    import sys

    tokens = sys.argv[1:] or ["255", "10", "0", "-4095", "  48879 ", "beef", "twelve"]
    for token in tokens:
        print(format_row(token, width=2))


