import sys


def default_key(word):
    """Canonical anagram key: letters sorted, case-insensitive."""
    return "".join(sorted(word.lower()))


def group_anagrams(words, key_func=None):
    """Group anagrams together, preserving first-appearance order."""
    if words is None:
        raise TypeError("words must be a list of strings, not None")
    if key_func is None:
        key_func = default_key
    buckets = {}
    order = []
    for word in words:
        key = key_func(word)
        bucket = buckets.get(key)
        if bucket is None:
            bucket = []
            buckets[key] = bucket
            order.append(key)
        bucket.append(word)
    return [buckets[key] for key in order]


def find_group(anagram_groups, word, key_func=None):
    """Return the group whose members are anagrams of word, or None."""
    if key_func is None:
        key_func = default_key
    wanted = key_func(word)
    for group in anagram_groups:
        if key_func(group[0]) == wanted:
            return group
    return None


def largest_group(anagram_groups):
    """Return the group with the most members, or None for no groups."""
    best = None
    for group in anagram_groups:
        if best is None or len(group) > len(best):
            best = group
    return best


def format_report(anagram_groups, title=None):
    lines = []
    if title is not None:
        lines.append(title)
        lines.append("-" * len(title))
    for index, group in enumerate(anagram_groups, start=1):
        lines.append("%d. %s" % (index, ", ".join(group)))
    return "\n".join(lines)


def parse_args(argv):
    """Split command line arguments into a word list and an optional query."""
    words = []
    query = None
    pending_query = False
    for arg in argv:
        if pending_query:
            query = arg
            pending_query = False
        elif arg == "--find":
            pending_query = True
        else:
            words.append(arg)
    if pending_query:
        raise ValueError("--find requires a word to look up")
    return words, query


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    words, query = parse_args(argv)
    if not words:
        words = ["eat", "tea", "tan", "ate", "nat", "bat"]
    anagram_groups = group_anagrams(words)
    print(format_report(anagram_groups, title="Anagram groups"))
    if query is not None:
        match = find_group(anagram_groups, query)
        if match is None:
            print("no anagrams of %r in the input" % query)
