def parse_interval(text):
    """Parse 'start-end' into a tuple of ints, or None if the text is malformed."""
    if text is None:
        return None
    parts = text.replace(" ", "").split("-")
    if len(parts) != 2:
        return None
    try:
        start, end = int(parts[0]), int(parts[1])
    except ValueError:
        return None
    if start > end:
        return None
    return (start, end)


def _check_interval(interval, label):
    if interval is None:
        raise ValueError("{} must not be None".format(label))
    if len(interval) != 2:
        raise ValueError("{} must have exactly two elements".format(label))
    start, end = interval
    if start is None:
        raise ValueError("{} has a missing start time".format(label))
    if end is None:
        raise ValueError("{} has a missing end time".format(label))
    if start > end:
        raise ValueError("{} ends before it starts".format(label))
    return start, end


def has_overlap(meeting1, meeting2):
    """Return True if the two half-open meeting intervals share any time."""
    start1, end1 = _check_interval(meeting1, "meeting1")
    start2, end2 = _check_interval(meeting2, "meeting2")
    return start1 < end2 and start2 < end1


def overlap_region(meeting1, meeting2):
    """Return the shared interval, or None when the meetings do not overlap."""
    if not has_overlap(meeting1, meeting2):
        return None
    start = max(meeting1[0], meeting2[0])
    end = min(meeting1[1], meeting2[1])
    return (start, end)


def find_conflicts(meetings):
    """List every pair of meetings that clash, together with the shared slot."""
    conflicts = []
    for i in range(len(meetings)):
        for j in range(i + 1, len(meetings)):
            region = overlap_region(meetings[i], meetings[j])
            if region is not None:
                conflicts.append((i, j, region))
    return conflicts


def describe(interval):
    if interval is None:
        return "none"
    return "{}-{}".format(interval[0], interval[1])


def main():
    raw = ["1-5", "3-7", "1-2", "3-4", "6 - 9", "10-8"]
    schedule = []
    for text in raw:
        interval = parse_interval(text)
        if interval is None:
            print("skipping unparsable entry: {!r}".format(text))
        else:
            schedule.append(interval)

    print("schedule:", ", ".join(describe(m) for m in schedule))
    print("(1,5) vs (3,7):", has_overlap((1, 5), (3, 7)))
    print("(1,2) vs (3,4):", has_overlap((1, 2), (3, 4)))

    conflicts = find_conflicts(schedule)
    if not conflicts:
        print("no conflicts found")
    for i, j, region in conflicts:
        print("conflict: {} and {} share {}".format(
            describe(schedule[i]), describe(schedule[j]), describe(region)))


if __name__ == "__main__":
    main()

