def validate_pixel(pixel):
    """Return an error message describing why `pixel` is invalid, or None if it is fine."""
    if pixel is None:
        return "pixel is missing"
    if not isinstance(pixel, (list, tuple)) or len(pixel) != 3:
        return "pixel must have exactly three channels"
    for value in pixel:
        if value is None:
            return "channel value is missing"
        if not isinstance(value, int) or isinstance(value, bool):
            return "channel value must be an int"
        if not 0 <= value <= 255:
            return "channel value out of range 0..255"
    return None


def validate_image(image_matrix):
    """Return an error message for the whole image, or None if the image is usable."""
    if image_matrix is None:
        return "image is missing"
    if not isinstance(image_matrix, list):
        return "image must be a list of rows"
    width = None
    for y, row in enumerate(image_matrix):
        if row is None:
            return "row %d is missing" % y
        if not isinstance(row, list):
            return "row %d must be a list" % y
        if width is None:
            width = len(row)
        elif len(row) != width:
            return "row %d has inconsistent width" % y
        for x, pixel in enumerate(row):
            problem = validate_pixel(pixel)
            if problem is not None:
                return "pixel (%d, %d): %s" % (x, y, problem)
    return None


def to_grayscale(image_matrix):
    problem = validate_image(image_matrix)
    if problem is not None:
        raise ValueError(problem)
    grayscale_image = []
    for row in image_matrix:
        grayscale_image.append([sum(pixel) // 3 for pixel in row])
    return grayscale_image


def brightest_pixel(grayscale_image):
    """Return (x, y, level) of the brightest pixel, or None for an empty image."""
    best = None
    for y, row in enumerate(grayscale_image):
        for x, level in enumerate(row):
            if best is None or level > best[2]:
                best = (x, y, level)
    return best


def render(grayscale_image):
    ramp = " .:-=+*#%@"
    lines = []
    for row in grayscale_image:
        lines.append("".join(ramp[level * (len(ramp) - 1) // 255] for level in row))
    return "\n".join(lines)


def main():
    samples = [
        [[[255, 0, 0], [0, 255, 0]]],
        [[[10, 20, 30]]],
        [[[0, 0, 0], [128, 128, 128], [255, 255, 255]],
         [[255, 128, 0], [30, 60, 90], [200, 200, 100]]],
    ]
    for image in samples:
        gray = to_grayscale(image)
        print(gray)
        print(render(gray))
        peak = brightest_pixel(gray)
        if peak is None:
            print("no pixels to analyse")
        else:
            print("brightest: (%d, %d) = %d" % peak)
        print("-" * 20)
    try:
        to_grayscale([[[0, 0, 0]], [[0, 0]]])
    except ValueError as exc:
        print("rejected:", exc)


if __name__ == "__main__":
    main()

