import re


def validate_inputs(text, keyword):
    """Check the arguments and return the keyword stripped of outer spaces."""
    if text is None:
        raise ValueError("text must be a string, not None")
    if keyword is None:
        raise ValueError("keyword must be a string, not None")
    if not isinstance(text, str) or not isinstance(keyword, str):
        raise TypeError("text and keyword must both be strings")
    trimmed = keyword.strip()
    if not trimmed:
        raise ValueError("keyword must contain at least one character")
    return trimmed


def build_pattern(keyword):
    """Compile a case-insensitive pattern, anchored on word boundaries when useful."""
    escaped = re.escape(keyword)
    if keyword[0].isalnum():
        escaped = r"\b" + escaped
    if keyword[-1].isalnum():
        escaped = escaped + r"\b"
    return re.compile(escaped, re.IGNORECASE)


def count_keyword_occurrences(text, keyword):
    """Return how many times keyword appears in text, ignoring case."""
    cleaned = validate_inputs(text, keyword)
    return len(build_pattern(cleaned).findall(text))


def find_keyword_positions(text, keyword, limit=None):
    """Return the start offsets of each match, at most limit of them."""
    cleaned = validate_inputs(text, keyword)
    positions = []
    for match in build_pattern(cleaned).finditer(text):
        positions.append(match.start())
        if limit is not None and len(positions) >= limit:
            break
    return positions


def extract_context(text, position, keyword, width=None):
    """Return a short snippet of text surrounding a match."""
    if width is None:
        width = 12
    start = max(0, position - width)
    end = min(len(text), position + len(keyword) + width)
    snippet = text[start:end].replace("\n", " ")
    prefix = "..." if start > 0 else ""
    suffix = "..." if end < len(text) else ""
    return prefix + snippet + suffix


def summarize(text, keywords, min_count=None):
    """Map each keyword to its occurrence count, dropping ones below min_count."""
    summary = {}
    for keyword in keywords:
        count = count_keyword_occurrences(text, keyword)
        if min_count is not None and count < min_count:
            continue
        summary[keyword] = count
    return summary


def format_report(text, keywords, min_count=None, title=None, width=None):
    """Build a human readable report of keyword counts and first contexts."""
    summary = summarize(text, keywords, min_count)
    lines = []
    if title is not None:
        lines.append(title)
    for keyword, count in sorted(summary.items()):
        lines.append("{0}: {1}".format(keyword, count))
        first = find_keyword_positions(text, keyword, limit=1)
        if first:
            lines.append("    first hit -> " + extract_context(text, first[0], keyword, width))
    if not summary:
        lines.append("no keyword reached the requested threshold")
    return "\n".join(lines)


def main():
    sample = "Hello world, hello Python! Python makes text processing fun."
    print(count_keyword_occurrences("Hello world, hello Python!", "hello"))
    print(count_keyword_occurrences("Python is fun", "java"))
    print(format_report(sample, ["hello", "python", "java", "fun"], title="all keywords"))
    print(format_report(sample, ["hello", "python"], min_count=2, width=20))


if __name__ == "__main__":
    main()

