import sys
from collections import Counter


def count_char(text, char_to_count):
    """Return how many times char_to_count occurs in text."""
    if text is None:
        raise ValueError("text must be a string, not None")
    if char_to_count is None:
        raise ValueError("char_to_count must be a string, not None")
    if len(char_to_count) != 1:
        raise ValueError("char_to_count must be exactly one character")
    total = 0
    for character in text:
        if character == char_to_count:
            total += 1
    return total


def count_char_in_lines(lines, char_to_count, limit=None):
    """Count occurrences across many lines, stopping early once limit is hit."""
    total = 0
    for line in lines:
        total += count_char(line, char_to_count)
        if limit is not None and total >= limit:
            return limit
    return total


def most_frequent_char(text):
    """Return the most common character, or None when there is nothing to count."""
    counts = Counter(text)
    if not counts:
        return None
    return counts.most_common(1)[0][0]


def format_report(text, char_to_count, label=None):
    """Build a one-line report; label falls back to a quoted snippet of the text."""
    if label is None:
        label = repr(text if len(text) <= 20 else text[:17] + "...")
    occurrences = count_char(text, char_to_count)
    return "{}: {!r} appears {} time(s)".format(label, char_to_count, occurrences)


def describe(text, char_to_count=None):
    """Report on char_to_count, or on the text's most frequent character."""
    if char_to_count is None:
        char_to_count = most_frequent_char(text)
        if char_to_count is None:
            return "empty text: nothing to count"
        return format_report(text, char_to_count, label="most frequent")
    return format_report(text, char_to_count)


def main(argv):
    text = argv[1] if len(argv) > 1 else None
    char_to_count = argv[2] if len(argv) > 2 else None
    if text is None:
        samples = [("banana", "a"), ("Mississippi", "s")]
        for sample_text, sample_char in samples:
            print(format_report(sample_text, sample_char))
        print(describe("Mississippi"))
        print("lines:", count_char_in_lines(["banana", "Mississippi"], "s", limit=3))
        return 0
    print(describe(text, char_to_count))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

