def _validate_mapping(name, value):
    """Return a shallow copy of a mapping argument, rejecting bad input."""
    if value is None:
        raise TypeError("%s must be a dict, not None" % name)
    if not isinstance(value, dict):
        raise TypeError("%s must be a dict, got %s" % (name, type(value).__name__))
    return dict(value)


def merge_dicts(dict1, dict2):
    """Merge two dicts into a new one; dict2 wins on shared keys."""
    merged = _validate_mapping("dict1", dict1)
    merged.update(_validate_mapping("dict2", dict2))
    return merged


def merge_all(dicts):
    """Fold merge_dicts over a sequence of dicts, left to right."""
    result = None
    for item in dicts:
        if result is None:
            result = _validate_mapping("dicts[0]", item)
        else:
            result = merge_dicts(result, item)
    if result is None:
        return {}
    return result


def overwritten_keys(dict1, dict2):
    """Keys present in both dicts whose value actually changes."""
    left = _validate_mapping("dict1", dict1)
    right = _validate_mapping("dict2", dict2)
    changed = []
    for key in left:
        replacement = right.get(key)
        if replacement is None and key not in right:
            continue
        if left[key] != replacement:
            changed.append(key)
    return sorted(changed, key=repr)


def describe_merge(dict1, dict2, label=None):
    """Build a human readable summary of a single merge operation."""
    merged = merge_dicts(dict1, dict2)
    if label is None:
        label = "merge"
    lines = ["%s -> %s" % (label, merged)]
    changed = overwritten_keys(dict1, dict2)
    if changed:
        for key in changed:
            lines.append("  %r: %r replaced by %r" % (key, dict1[key], merged[key]))
    else:
        lines.append("  no keys were overwritten")
    return "\n".join(lines)


def main():
    print(describe_merge({'a': 1, 'b': 2}, {'b': 3, 'c': 4}, label="example 1"))
    print(describe_merge({'x': 10}, {'y': 20}, label="example 2"))

    defaults = {'host': 'localhost', 'port': 8080, 'debug': False}
    overrides = {'port': 9000, 'debug': True}
    config = merge_all([defaults, overrides, {'host': '0.0.0.0'}])
    print("config -> %s" % config)

    timeout = config.get('timeout')
    if timeout is None:
        print("timeout not configured, using 30s")
    else:
        print("timeout configured as %ss" % timeout)

    try:
        merge_dicts(defaults, None)
    except TypeError as exc:
        print("rejected bad input: %s" % exc)


if __name__ == "__main__":
    main()

