from datetime import date


def parse_date(text):
    """Return a date object for 'YYYY-MM-DD' text, or None if it is malformed."""
    if text is None:
        return None
    parts = text.strip().split('-')
    if len(parts) != 3:
        return None
    try:
        year, month, day = (int(p) for p in parts)
    except ValueError:
        return None
    try:
        return date(year, month, day)
    except ValueError:
        return None


def days_between_dates(start_date_str, end_date_str):
    start = parse_date(start_date_str)
    if start is None:
        raise ValueError('invalid start date: %r' % (start_date_str,))
    end = parse_date(end_date_str)
    if end is None:
        raise ValueError('invalid end date: %r' % (end_date_str,))
    return (end - start).days


def describe_gap(start_date_str, end_date_str):
    """Human readable summary of the signed distance between two dates."""
    delta = days_between_dates(start_date_str, end_date_str)
    if delta == 0:
        return '%s and %s are the same day' % (start_date_str, end_date_str)
    direction = 'after' if delta > 0 else 'before'
    return '%s is %d day(s) %s %s' % (
        end_date_str, abs(delta), direction, start_date_str)


def longest_span(date_strings):
    """Return (earliest, latest, days) for the parseable dates, or None."""
    earliest = None
    latest = None
    for text in date_strings:
        current = parse_date(text)
        if current is None:
            continue
        if earliest is None or current < earliest:
            earliest = current
        if latest is None or current > latest:
            latest = current
    if earliest is None:
        return None
    span = (latest - earliest).days
    return earliest.isoformat(), latest.isoformat(), span


def main():
    pairs = [
        ('2023-01-01', '2023-01-05'),
        ('2023-01-01', '2022-12-25'),
        ('2020-02-28', '2020-03-01'),
        ('2024-06-10', '2024-06-10'),
    ]
    for start, end in pairs:
        print(describe_gap(start, end))

    samples = ['2021-07-04', 'not-a-date', '2019-12-31', '2022-02-30', '2023-11-11']
    result = longest_span(samples)
    if result is None:
        print('no valid dates in the sample list')
    else:
        first, last, span = result
        print('widest span: %s .. %s (%d days)' % (first, last, span))


if __name__ == '__main__':
    main()

