def normalize_rectangle(x1, y1, x2, y2):
    """Return the rectangle with corners ordered bottom-left / top-right."""
    return min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)


def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    lo_x, lo_y, hi_x, hi_y = normalize_rectangle(x1, y1, x2, y2)
    return lo_x <= px <= hi_x and lo_y <= py <= hi_y


def classify_point(px, py, x1, y1, x2, y2):
    """Return 'outside', 'edge' or 'interior' for the point."""
    if not is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return "outside"
    lo_x, lo_y, hi_x, hi_y = normalize_rectangle(x1, y1, x2, y2)
    if px in (lo_x, hi_x) or py in (lo_y, hi_y):
        return "edge"
    return "interior"


def parse_ints(text, count):
    """Parse exactly `count` whitespace/comma separated integers, or None."""
    parts = text.replace(",", " ").split()
    if len(parts) != count:
        return None
    values = []
    for part in parts:
        try:
            values.append(int(part))
        except ValueError:
            return None
    return values


def parse_query(text):
    """Turn 'px py x1 y1 x2 y2' into a 6-tuple, or None if malformed."""
    numbers = parse_ints(text, 6)
    if numbers is None:
        return None
    px, py, x1, y1, x2, y2 = numbers
    return (px, py) + normalize_rectangle(x1, y1, x2, y2)


def describe_query(text):
    """Build a human readable report line for one query."""
    query = parse_query(text)
    if query is None:
        return "%-24s -> malformed query (need 6 integers)" % text.strip()
    inside = is_point_in_rectangle(*query)
    where = classify_point(*query)
    return "%-24s -> %-5s (%s)" % (text.strip(), inside, where)


def index_of_containing(px, py, rectangles):
    """Return the index of the first rectangle containing the point, else None."""
    for index, rect in enumerate(rectangles):
        if is_point_in_rectangle(px, py, *rect):
            return index
    return None


def first_containing(px, py, rectangles):
    index = index_of_containing(px, py, rectangles)
    if index is None:
        return None
    return rectangles[index]


def summarize(queries):
    """Count inside / outside / malformed queries."""
    totals = {"inside": 0, "outside": 0, "malformed": 0}
    for text in queries:
        query = parse_query(text)
        if query is not None:
            key = "inside" if is_point_in_rectangle(*query) else "outside"
            totals[key] += 1
        else:
            totals["malformed"] += 1
    return totals


def main():
