def get_item_quantity(inventory, item_name):
    quantity = inventory.get(item_name)
    if quantity is None:
        return 0
    return int(quantity)


def restock(inventory, item_name, amount=None):
    if amount is None:
        amount = 1
    current = get_item_quantity(inventory, item_name)
    inventory[item_name] = current + amount
    return inventory[item_name]


def consume(inventory, item_name, amount):
    current = get_item_quantity(inventory, item_name)
    if current < amount:
        return None
    remaining = current - amount
    if remaining == 0:
        del inventory[item_name]
    else:
        inventory[item_name] = remaining
    return remaining


def parse_order(line):
    parts = line.split()
    if len(parts) != 2:
        return None
    name, raw_amount = parts
    if not raw_amount.lstrip("-").isdigit():
        return None
    return name, int(raw_amount)


def apply_orders(inventory, lines):
    failures = []
    for line in lines:
        order = parse_order(line)
        if order is None:
            failures.append((line, "unparsable"))
            continue
        name, amount = order
        if amount > 0:
            restock(inventory, name, amount)
            continue
        result = consume(inventory, name, -amount)
        if result is None:
            failures.append((line, "insufficient stock"))
    return failures


def format_report(inventory, highlight=None):
    rows = []
    for name in sorted(inventory):
        marker = ""
        if highlight is not None and name == highlight:
            marker = " <--"
        rows.append("{:<10} {:>4}{}".format(name, inventory[name], marker))
    return "\n".join(rows)


def main():
    inventory = {'apple': 10, 'banana': 5}
    print(get_item_quantity(inventory, 'apple'))
    print(get_item_quantity(inventory, 'orange'))

    orders = ["apple 5", "banana -2", "cherry 12", "durian -1", "bad line here"]
    failures = apply_orders(inventory, orders)
    for line, reason in failures:
        print("rejected {!r}: {}".format(line, reason))

    top = None
    for name, count in inventory.items():
        if top is None or count > inventory[top]:
            top = name
    print(format_report(inventory, highlight=top))
    if top is not None:
        print("largest stock: {} ({})".format(top, get_item_quantity(inventory, top)))


if __name__ == "__main__":
    main()

