def parse_hour(text):
    """Return the integer hour encoded in `text`, or None if it is not valid."""
    cleaned = text.strip()
    if not cleaned.isdigit():
        return None
    hour = int(cleaned)
    if hour < 0 or hour > 24:
        return None
    return hour


def parse_interval(text):
    """Parse 'start-end' into a (start, end) tuple, or None when malformed."""
    parts = text.split("-")
    if len(parts) != 2:
        return None
    start = parse_hour(parts[0])
    if start is None:
        return None
    end = parse_hour(parts[1])
    if end is None:
        return None
    if start >= end:
        return None
    return (start, end)


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    """True when the two half-open intervals share at least one hour."""
    return task1_start < task2_end and task2_start < task1_end


def overlap_hours(task1_start, task1_end, task2_start, task2_end):
    """Number of shared hours, or None if the tasks do not overlap at all."""
    if not has_overlap(task1_start, task1_end, task2_start, task2_end):
        return None
    return min(task1_end, task2_end) - max(task1_start, task2_start)


def find_first_conflict(intervals):
    """Return (i, j) for the earliest clashing pair, or None if all fit."""
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            a, b = intervals[i], intervals[j]
            if has_overlap(a[0], a[1], b[0], b[1]):
                return (i, j)
    return None


def describe(text1, text2):
    """Human readable verdict for two textual intervals."""
    first = parse_interval(text1)
    if first is None:
        return "invalid interval: %s" % text1
    second = parse_interval(text2)
    if second is None:
        return "invalid interval: %s" % text2
    shared = overlap_hours(first[0], first[1], second[0], second[1])
    if shared is None:
        return "%s and %s do not overlap" % (text1, text2)
    return "%s and %s overlap for %d hour(s)" % (text1, text2, shared)


