def parse_csv_line(csv_line):
    """Split a single line of unquoted CSV data into a list of field strings."""
    if csv_line is None:
        raise ValueError("csv_line must be a string, not None")
    line = csv_line.rstrip("\r\n")
    if line == "":
        return []
    return line.split(",")


def parse_rows(text, header=None):
    """Parse a block of CSV text; if header is None the first line supplies it."""
    rows = []
    for raw in text.splitlines():
        if raw.strip() == "":
            continue
        fields = parse_csv_line(raw)
        if header is None:
            header = fields
            continue
        rows.append(fields)
    return header, rows


def row_to_record(header, fields, missing=None):
    """Pair a header with a row, filling absent columns with `missing`."""
    record = {}
    for index, name in enumerate(header):
        if index < len(fields):
            record[name] = fields[index]
        else:
            record[name] = missing
