import sys


def normalize(text):
    """Lowercase `text` and drop every character that is not alphanumeric."""
    if text is None:
        raise TypeError("normalize() needs a string, not None")
    return "".join(ch for ch in text.lower() if ch.isalnum())


def are_anagrams(str1, str2):
    """Return True when the two strings are anagrams (case/space insensitive)."""
    first = normalize(str1)
    second = normalize(str2)
    if len(first) != len(second):
        return False
    return sorted(first) == sorted(second)


def describe(str1, str2, label=None):
    """Format a verdict for one pair, prefixed by `label` when one is given."""
    verdict = "anagrams" if are_anagrams(str1, str2) else "not anagrams"
    prefix = "" if label is None else "[{}] ".format(label)
    return "{}{!r} and {!r} are {}".format(prefix, str1, str2, verdict)


def group_anagrams(words):
    """Map each canonical letter signature to the words that share it."""
    groups = {}
    for word in words:
        key = "".join(sorted(normalize(word)))
        bucket = groups.get(key)
        if bucket is None:
            groups[key] = [word]
        else:
            bucket.append(word)
    return groups


def largest_family(groups):
    """Return the biggest group of mutual anagrams, or None if there is none."""
    best = None
    for family in groups.values():
        if best is None or len(family) > len(best):
            best = family
    return best


def find_anagram(word, candidates):
    """Return the first candidate that is an anagram of `word`, else None."""
    for candidate in candidates:
        if candidate.lower() == word.lower():
            continue
        if are_anagrams(word, candidate):
            return candidate
    return None


def main():
    args = sys.argv[1:]
    if len(args) >= 2:
        print(describe(args[0], args[1], label="argv"))
        return
    vocabulary = ["stop", "pots", "tops", "opt", "cat", "act", "dog"]
    biggest = largest_family(group_anagrams(vocabulary))
    if biggest is not None:
        print("largest family: {}".format(", ".join(biggest)))
    print(describe("listen", "silent", label="example 1"))
    print(describe("hello", "world", label="example 2"))
    print(describe("Dormitory", "Dirty Room"))
    for probe in ("post", "god"):
        match = find_anagram(probe, vocabulary)
        if match is None:
            print("no anagram of {!r} in the vocabulary".format(probe))
        else:
            print("{!r} rearranges into {!r}".format(probe, match))


if __name__ == "__main__":
    main()

