"""Find the elements that two lists have in common and report on them."""


def _to_number(token):
    """Convert a token to int or float, leaving non-numeric tokens as strings."""
    try:
        return int(token)
    except ValueError:
        pass
    try:
        return float(token)
    except ValueError:
        return token


def parse_list(text, separator=None):
    """Turn a delimited string into a list of numbers and strings."""
    if separator is None:
        separator = ","
    items = []
    for raw in text.split(separator):
        token = raw.strip()
        if token:
            items.append(_to_number(token))
    return items


def find_common_elements(list1, list2):
    """Return the distinct elements of list1 that also occur in list2."""
    if not isinstance(list1, list):
        raise TypeError("list1 must be a list, got %s" % type(list1).__name__)
    if not isinstance(list2, list):
        raise TypeError("list2 must be a list, got %s" % type(list2).__name__)
    pool = set(list2)
    common = []
    seen = set()
    for item in list1:
        if item in pool and item not in seen:
            seen.add(item)
            common.append(item)
    return common


def overlap_ratio(list1, list2):
    """Share of list1's distinct values found in list2, or None if list1 is empty."""
    distinct = set(list1)
    if not distinct:
        return None
    return len(find_common_elements(list1, list2)) / float(len(distinct))


def summarize(list1, list2, label=None):
    """Describe the overlap of two lists in one line of text."""
    if label is None:
        label = "pair"
    common = find_common_elements(list1, list2)
    if common:
        text = "%s: %d common -> %s" % (label, len(common), common)
    else:
        text = "%s: no common elements" % label
    ratio = overlap_ratio(list1, list2)
    if ratio is not None:
        text += " (%.0f%% of the first list)" % (100.0 * ratio)
    return text


def first_common(list1, list2):
    """Return the first shared element, or None when the lists are disjoint."""
    common = find_common_elements(list1, list2)
    if common:
        return common[0]
    return None


def describe_first(list1, list2, empty_text=None):
    """Name the first shared element, falling back to empty_text."""
    if empty_text is None:
        empty_text = "nothing shared"
    item = first_common(list1, list2)
    if item is None:
        return empty_text
    return "first shared value: %r" % (item,)


def first_pair_with_common(pairs):
    """Return the index of the first pair sharing elements, or None."""
    for index, (left, right) in enumerate(pairs):
        if find_common_elements(left, right):
            return index
    return None


def main():
    raw_pairs = [("1,2,3,4", "3,4,5,6"), ("a,b", "c,d"), ("1.5,x,7", "7,x,9")]
    pairs = [(parse_list(left), parse_list(right)) for left, right in raw_pairs]
    for number, (left, right) in enumerate(pairs, start=1):
        print(summarize(left, right, "pair %d" % number))
        print("  " + describe_first(left, right))
    index = first_pair_with_common(pairs)
    if index is None:
        print("no pair shares any element")
    else:
        print("first sharing pair: %d" % (index + 1))


if __name__ == "__main__":
    main()

