class Queue:
    """A simple FIFO queue backed by a Python list."""

    def __init__(self, items=None):
        if items is None:
            self._items = []
        else:
            self._items = list(items)

    def enqueue(self, item):
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            return None
        return self._items.pop(0)

    def peek(self):
        if not self._items:
            return None
        return self._items[0]

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return "Queue({!r})".format(self._items)


def drain(queue, limit=None):
    """Remove and return items from the queue, at most `limit` of them."""
    collected = []
    while True:
        if limit is not None and len(collected) >= limit:
            break
        item = queue.dequeue()
        if item is None:
            break
        collected.append(item)
    return collected


def run_commands(commands, queue=None):
    """Apply textual commands like 'enqueue 5', 'dequeue', 'peek' to a queue."""
    if queue is None:
        queue = Queue()
    log = []
    for command in commands:
        parts = command.split()
        if not parts:
            continue
        action = parts[0].lower()
        if action == "enqueue":
            if len(parts) < 2:
                raise ValueError("enqueue needs an argument: " + command)
            queue.enqueue(parts[1])
            log.append((command, None))
        elif action == "dequeue":
            log.append((command, queue.dequeue()))
        elif action == "peek":
            log.append((command, queue.peek()))
        else:
            raise ValueError("unknown command: " + action)
    return queue, log


def format_log(log):
    lines = []
    for command, result in log:
        if result is None:
            lines.append("{:<12} -> empty".format(command))
        else:
            lines.append("{:<12} -> {}".format(command, result))
    return "\n".join(lines)


def main():
    q = Queue()
    q.enqueue(1)
    print("first dequeue:", q.dequeue())
    print("empty dequeue:", q.dequeue())

    script = ["enqueue a", "enqueue b", "peek", "dequeue", "dequeue", "dequeue"]
    queue, log = run_commands(script)
    print(format_log(log))
    print("remaining:", len(queue))

    numbers = Queue(range(1, 6))
    print("drained two:", drain(numbers, limit=2))
    print("drained rest:", drain(numbers))


if __name__ == "__main__":
    main()

