import math
import sys


def parse_coordinate(token):
    """Convert a text token into a float, or None if it is not a number."""
    try:
        return float(token.strip())
    except ValueError:
        return None


def parse_point(text):
    """Parse 'x,y' into a (x, y) tuple, or None when the text is malformed."""
    parts = text.split(",")
    if len(parts) != 2:
        return None
    x = parse_coordinate(parts[0])
    if x is None:
        return None
    y = parse_coordinate(parts[1])
    if y is None:
        return None
    return (x, y)


def euclidean_distance_2d(x1, y1, x2, y2):
    """Return the Euclidean distance between (x1, y1) and (x2, y2)."""
    dx = float(x2) - float(x1)
    dy = float(y2) - float(y1)
    return math.hypot(dx, dy)


def format_report(first_text, second_text, precision=3):
    """Build a human readable line describing the distance of two points."""
    start = parse_point(first_text)
    if start is None:
        return "invalid first point: %r" % (first_text,)
    end = parse_point(second_text)
    if end is None:
        return "invalid second point: %r" % (second_text,)
    dist = euclidean_distance_2d(start[0], start[1], end[0], end[1])
    return "%s -> %s : %.*f" % (start, end, precision, dist)


def total_path_length(texts):
    """Sum the distances along a polyline given as 'x,y' strings.

    Returns None if any waypoint cannot be parsed.
    """
    total = 0.0
    previous = None
    for text in texts:
        point = parse_point(text)
        if point is None:
            return None
        if previous is not None:
            total += euclidean_distance_2d(previous[0], previous[1],
                                           point[0], point[1])
        previous = point
    return total


def main(argv):
    if len(argv) >= 2:
        print(format_report(argv[0], argv[1]))
        path = argv
    else:
        for first_text, second_text in [("0,0", "3,4"), ("1,1", "1,1"),
                                        ("2.5,-1", "bad")]:
            print(format_report(first_text, second_text))
        path = ["0,0", "3,4", "3,0"]
    length = total_path_length(path)
    if length is None:
        print("path contains an invalid waypoint")
        return 1
    print("path length: %.3f" % length)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

