import re
import sys
from collections import Counter

_TOKEN_RE = re.compile(r"[A-Za-z0-9']+")
# Numerals (digits or spelled out) are quantities, not words, and are skipped.
_NUMERALS = frozenset(
    "zero one two three four five six seven eight nine ten eleven twelve".split()
)


def normalize_word(raw, keep_case=False):
    """Strip punctuation from a raw token; return None if nothing countable is left."""
    match = _TOKEN_RE.search(raw)
    if match is None:
        return None
    word = match.group(0).strip("'")
    if not word or word.isdigit():
        return None
    if word.lower() in _NUMERALS:
        return None
    return word if keep_case else word.lower()


def tokenize(text, keep_case=False):
    """Split text on spaces and return the cleaned words."""
    if text is None:
        raise TypeError("text must be a string, not None")
    words = []
    for chunk in text.split():
        word = normalize_word(chunk, keep_case)
        if word is not None:
            words.append(word)
    return words


def count_words(text):
    """Count the words in text, ignoring punctuation."""
    return len(tokenize(text))


def word_frequencies(text, limit=None):
    """Return (word, count) pairs ordered by descending frequency."""
    counts = Counter(tokenize(text))
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    if limit is None:
        return ordered
    return ordered[:limit]


def longest_word(text):
    """Return the longest word of text, or None when there are none."""
    best = None
    for word in tokenize(text, keep_case=True):
        if best is None or len(word) > len(best):
            best = word
    return best


def describe(text, limit=None):
    """Build a short human readable report about the words in text."""
    lines = ["words: %d" % count_words(text)]
    best = longest_word(text)
    if best is not None:
        lines.append("longest: %s" % best)
    for word, count in word_frequencies(text, limit):
        lines.append("  %-12s %d" % (word, count))
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        text = " ".join(argv[1:])
    else:
        text = "Hello world, how are you? Hello again, world!"
    print(describe(text, limit=5))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

