def coerce_numeric(value):
    """Return value as a float, or None if it cannot be treated as a number."""
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        return None
    try:
        return float(value)
    except ValueError:
        return None


def filter_dict_by_value(input_dict, threshold):
    """Keep only pairs whose value is a number greater than threshold."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict")
    limit = coerce_numeric(threshold)
    if limit is None:
        raise TypeError("threshold must be a number")
    result = {}
    for key, value in input_dict.items():
        number = coerce_numeric(value)
        if number is not None and number > limit:
            result[key] = value
    return result


def parse_pairs(text):
    """Parse 'a=10,b=20' into a dictionary of floats."""
    pairs = {}
    for chunk in text.split(","):
        chunk = chunk.strip()
        if not chunk:
            continue
        key, sep, raw = chunk.partition("=")
        number = coerce_numeric(raw) if sep else None
        if number is None:
            raise ValueError("bad pair: %r" % chunk)
        pairs[key.strip()] = number
    return pairs


def largest_key(input_dict):
    """Key with the greatest numeric value, or None for an empty selection."""
    best_key = None
    best_value = None
    for key, value in input_dict.items():
        number = coerce_numeric(value)
        if number is None:
            continue
        if best_value is None or number > best_value:
            best_key, best_value = key, number
    return best_key


def format_report(kept, threshold):
    top = largest_key(kept)
    tail = "no entries kept" if top is None else "largest kept: %s" % top
    return "threshold=%r -> %s (%s)" % (threshold, kept, tail)


def main():
    print(format_report(filter_dict_by_value({'a': 10, 'b': 20, 'c': 5}, 15), 15))
    print(format_report(filter_dict_by_value({'x': 1, 'y': 2}, 5), 5))
