import re

EMAIL_PATTERN = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+")
ADDRESS_PATTERN = re.compile(r"([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,})")


def extract_emails(text):
    """Return every valid-looking email address found in text, in order."""
    if text is None:
        raise ValueError("text must be a string, not None")
    found = []
    for match in EMAIL_PATTERN.finditer(text):
        candidate = match.group(0).rstrip(".")
        if split_address(candidate) is not None:
            found.append(candidate)
    return found


def split_address(email):
    """Return (local, domain) for a well-formed address, else None."""
    match = ADDRESS_PATTERN.fullmatch(email)
    if match is None:
        return None
    return match.group(1), match.group(2)


def domain_of(email):
    """Return the lower-cased domain of an address, or None if unparsable."""
    parts = split_address(email)
    if parts is None:
        return None
    return parts[1].lower()


def group_by_domain(emails):
    """Map each domain to the sorted, unique addresses belonging to it."""
    groups = {}
    for email in emails:
        domain = domain_of(email)
        if domain is None:
            continue
        bucket = groups.get(domain)
        if bucket is None:
            bucket = set()
            groups[domain] = bucket
        bucket.add(email.lower())
    return {domain: sorted(bucket) for domain, bucket in groups.items()}


def format_report(text, title=None):
    """Build a human-readable summary of the addresses inside text."""
    if title is None:
        title = "Email report"
    emails = extract_emails(text)
    lines = ["%s (%d found)" % (title, len(emails))]
    if not emails:
        lines.append("  <none>")
        return "\n".join(lines)
    for domain, addresses in sorted(group_by_domain(emails).items()):
        lines.append("  %s:" % domain)
        for address in addresses:
            lines.append("    - %s" % address)
    return "\n".join(lines)


def main():
    samples = [
        ("Contact us at info@example.com or support@test.org.", "Contacts"),
        ("No emails here.", None),
        ("Bugs: dev@example.com, DEV@Example.com; ops@mail.example.com", "Team"),
    ]
    for text, title in samples:
        print(format_report(text, title))
        print()
    print(extract_emails("Contact us at info@example.com or support@test.org."))
    print(extract_emails("No emails here."))


if __name__ == "__main__":
    main()

