    """Return the integer shift described by *raw*, or None if it is not valid."""
    if raw is None:
        return None
    text = raw.strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        return None


def encrypt_shift(text, shift):
    """Shift every letter of *text* by *shift* positions, leaving other characters alone."""
    if text is None:
        raise ValueError("text must be a string")
    step = shift % 26
    result = []
    for char in text:
        if char.isalpha() and char.isascii():
            base = ord('A') if char.isupper() else ord('a')
            result.append(chr(base + (ord(char) - base + step) % 26))
        else:
            result.append(char)
    return ''.join(result)


def decrypt_shift(text, shift):
    """Inverse of encrypt_shift."""
    return encrypt_shift(text, -shift)


def crack(cipher, known_word):
    """Guess the shift used on *cipher* by looking for *known_word*; None if not found."""
    lowered = known_word.lower()
    for candidate in range(26):
        if lowered in decrypt_shift(cipher, candidate).lower():
            return candidate
    return None


def format_report(text, shift):
    return "%-24s -> %s" % (text, encrypt_shift(text, shift))


