def parse_url_params(query_string):
    """Parse a URL query string into a dictionary of key-value pairs."""
    if query_string is None:
        raise TypeError("query_string must be a string, not None")
    params = {}
    text = query_string.lstrip('?')
    if not text:
        return params
    for chunk in text.split('&'):
        if not chunk:
            continue
        if '=' in chunk:
            key, value = chunk.split('=', 1)
        else:
            key, value = chunk, ''
        if key:
            params[key] = value
    return params


def extract_query_string(url):
    """Return the query part of a URL, or None when the URL carries none."""
    if url is None:
        return None
    marker = url.find('?')
    if marker < 0:
        return None
    return url[marker + 1:]


def parse_url(url):
    """Parse the query part of a full URL into a dictionary."""
    query = extract_query_string(url)
    if query is None:
        return {}
    return parse_url_params(query)


def get_param(params, key, default=None):
    """Look up a parameter, falling back to default for missing entries."""
    value = params.get(key)
    if value is None:
        return default
    return value


