def _shortest(strings):
    """Return the shortest string in the list, or None if the list is empty."""
    best = None
    for item in strings:
        if best is None or len(item) < len(best):
            best = item
    return best


def first_mismatch(strings):
    """Index of the first position where the strings differ, or None if equal."""
    candidate = _shortest(strings)
    if candidate is None:
        return None
    for position, char in enumerate(candidate):
        for other in strings:
            if other[position] != char:
                return position
    for other in strings:
        if len(other) != len(candidate):
            return len(candidate)
    return None


def _validate(strings):
    """Raise TypeError unless `strings` is a list of str."""
    if strings is None:
        raise TypeError("strings must be a list, not None")
    if not isinstance(strings, list):
        raise TypeError("strings must be a list")
    for index, item in enumerate(strings):
        if not isinstance(item, str):
            raise TypeError("element %d is not a string" % index)


def longest_common_prefix(strings):
    """Return the longest common prefix of all strings in the list."""
    _validate(strings)
    shortest = _shortest(strings)
    if shortest is None:
        return ""
    mismatch = first_mismatch(strings)
    if mismatch is None:
        return shortest
    return shortest[:mismatch]


def group_by_prefix(strings, length=None):
    """Group the words by prefix, by default up to the first differing char."""
    if length is None:
        mismatch = first_mismatch(strings)
        length = 1 if mismatch is None else mismatch + 1
    groups = {}
    for word in strings:
        key = word[:length]
        bucket = groups.get(key)
        if bucket is None:
            bucket = []
            groups[key] = bucket
        bucket.append(word)
    return groups


def describe(strings):
    """Build a human readable report about the prefixes of `strings`."""
    prefix = longest_common_prefix(strings)
    lines = ["words: " + ", ".join(strings) if strings else "words: (none)"]
    if prefix:
        lines.append("common prefix: '%s' (%d chars)" % (prefix, len(prefix)))
    else:
        lines.append("common prefix: none")
    for key, bucket in sorted(group_by_prefix(strings).items()):
        lines.append("  %s -> %s" % (key or "(empty)", " ".join(bucket)))
    return "\n".join(lines)


def main():
    samples = [
        ["flower", "flow", "flight"],
        ["dog", "racecar", "car"],
        ["interspecies", "interstellar", "interstate"],
        ["throne", "throughout"],
        [],
    ]
    for sample in samples:
        print(describe(sample))
        print()


if __name__ == "__main__":
    main()

