def parse_number(token):
    """Convert a text token into a float, returning None when it is not numeric."""
    try:
        return float(token)
    except ValueError:
        return None


def parse_series(text):
    """Parse a comma or whitespace separated series; unreadable tokens become gaps."""
    return [parse_number(token) for token in text.replace(",", " ").split()]


def drop_gaps(series):
    """Return the series without its missing (None) observations."""
    values = []
    for value in series:
        if value is not None:
            values.append(value)
    return values


def calculate_sma(data, window_size):
    if not isinstance(window_size, int) or isinstance(window_size, bool):
        raise TypeError("window_size must be an integer")
    if window_size <= 0:
        raise ValueError("window_size must be positive")
    for value in data:
        if value is None:
            raise ValueError("data contains gaps; remove them before averaging")
    if window_size > len(data):
        return []
    running = float(sum(data[:window_size]))
    averages = [running / window_size]
    for index in range(window_size, len(data)):
        running += data[index] - data[index - window_size]
        averages.append(running / window_size)
    return averages


def peak_average(averages):
    """Offset of the largest moving average value."""
    best_offset = None
    for offset, average in enumerate(averages):
        if best_offset is None or average > averages[best_offset]:
            best_offset = offset
    return best_offset


def first_crossover(data, averages, window_size):
    """Index in `data` where the series first rises above its moving average."""
    for offset, average in enumerate(averages):
        index = offset + window_size - 1
        if data[index] > average:
            return index
    return None


def trend_direction(averages):
    """'rising', 'falling' or 'flat'; None when there is nothing to compare."""
    if len(averages) < 2:
        return None
    if averages[-1] > averages[0]:
        return "rising"
    if averages[-1] < averages[0]:
        return "falling"
    return "flat"


def format_report(data, window_size, averages):
    lines = ["window size: %d" % window_size]
    for offset, average in enumerate(averages):
        index = offset + window_size - 1
        lines.append("  x[%d]=%g  sma=%.4f" % (index, data[index], average))
    crossing = first_crossover(data, averages, window_size)
    if crossing is None:
        lines.append("  no point rises above its moving average")
    else:
        lines.append("  first crossover at index %d" % crossing)
    peak = peak_average(averages)
    lines.append("  highest sma %.4f at index %d" % (averages[peak], peak + window_size - 1))
    direction = trend_direction(averages)
    if direction is None:
        lines.append("  single average only, no trend")
    else:
        lines.append("  trend: %s" % direction)
    return "\n".join(lines)


def main():
    samples = [("1, 2, 3, 4, 5", 3), ("10 20 30 40", 2), ("5, oops, 4, 3, 2", 4), ("7 7 7", 5)]
    for text, window_size in samples:
        series = parse_series(text)
        gaps = [index for index, value in enumerate(series) if value is None]
        if gaps:
            print("dropping gaps at %r" % gaps)
            series = drop_gaps(series)
        averages = calculate_sma(series, window_size)
        print("input: %s -> %r" % (text, series))
        if averages:
            print(format_report(series, window_size, averages))
        else:
            print("  series too short for this window")


if __name__ == "__main__":
    main()

