ROMAN_VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

DESCENDING = (('M', 1000), ('CM', 900), ('D', 500), ('CD', 400), ('C', 100),
              ('XC', 90), ('L', 50), ('XL', 40), ('X', 10), ('IX', 9),
              ('V', 5), ('IV', 4), ('I', 1))


def value_at(text, index):
    """Return the value of the symbol at index, or None if absent or unknown."""
    if index >= len(text):
        return None
    return ROMAN_VALUES.get(text[index])


def find_invalid_char(text):
    """Return the first character that is not a Roman symbol, or None if all are valid."""
    for char in text:
        if char not in ROMAN_VALUES:
            return char
    return None


def int_to_roman(number):
    """Build the canonical numeral for a number, used to reject malformed input."""
    parts = []
    remaining = number
    for symbol, value in DESCENDING:
        while remaining >= value:
            parts.append(symbol)
            remaining -= value
    return ''.join(parts)


def roman_to_int(roman_numeral):
    if roman_numeral is None:
        raise ValueError('roman_numeral must be a string, not None')
    text = roman_numeral.strip().upper()
    total = 0
    index = 0
    while index < len(text):
        value = value_at(text, index)
        if value is None:
            raise ValueError('invalid Roman symbol: %r' % text[index])
        next_value = value_at(text, index + 1)
        if next_value is not None and next_value > value:
            total += next_value - value
            index += 2
        else:
            total += value
            index += 1
    if total < 1 or total > 3999:
        raise ValueError('value out of range 1..3999: %d' % total)
    if int_to_roman(total) != text:
        raise ValueError('%r is not a canonical Roman numeral' % text)
    return total


def safe_convert(roman_numeral):
    """Convert without raising: return the integer, or None when the input is invalid."""
    try:
        return roman_to_int(roman_numeral)
    except ValueError:
        return None


def describe(roman_numeral):
    if roman_numeral is None:
        return '%-10s -> rejected (missing input)' % 'None'
    number = safe_convert(roman_numeral)
    if number is not None:
        return '%-10s -> %d' % (roman_numeral, number)
    bad = find_invalid_char(roman_numeral.strip().upper())
    if bad is None:
        return '%-10s -> rejected (malformed or out of range)' % roman_numeral
    return '%-10s -> rejected (bad symbol %r)' % (roman_numeral, bad)


