def parse_number(text):
    """Return the float value of text, or None if it is not a valid number."""
    if text is None:
        return None
    stripped = text.strip().rstrip('%')
    try:
        return float(stripped)
    except ValueError:
        return None


def calculate_discount_price(original_price, discount_percentage):
    """Return the price left after applying discount_percentage to original_price."""
    if original_price is None:
        raise ValueError("original_price is required")
    if discount_percentage is None:
        raise ValueError("discount_percentage is required")
    price = float(original_price)
    percentage = float(discount_percentage)
    if price < 0:
        raise ValueError("original_price must not be negative")
    if not 0 <= percentage <= 100:
        raise ValueError("discount_percentage must be between 0 and 100")
    return round(price * (1 - percentage / 100.0), 2)


def parse_item_line(line):
    """Split 'name,price,discount' into a tuple, or return None if unusable."""
    parts = [field.strip() for field in line.split(',')]
    if len(parts) != 3:
        return None
    name, price_text, discount_text = parts
    price = parse_number(price_text)
    if price is None:
        return None
    discount = parse_number(discount_text)
    if discount is None:
        return None
    if not name:
        name = "unnamed item"
    return name, price, discount


def item_savings(item):
    """Return the money saved on a parsed item, or None if it cannot be priced."""
    if item is None:
        return None
    name, price, discount = item
    try:
        final = calculate_discount_price(price, discount)
    except ValueError:
        return None
    return round(price - final, 2)


def describe_item(line, item):
    """Build a human readable report line for one input record."""
    if item is None:
        return "skipped: %r is not 'name,price,discount'" % line
    name, price, discount = item
    try:
        final = calculate_discount_price(price, discount)
    except ValueError as error:
        return "skipped %s: %s" % (name, error)
    return "%-12s %8.2f -> %8.2f (saved %.2f)" % (name, price, final, price - final)


def main():
    records = [
        "Notebook,100,10",
        "Mug,50,20",
        "Lamp,29.99,15",
        "Broken,abc,10",
        "Overdone,80,150",
        ",12.5,5",
    ]
    total_saved = 0.0
    for line in records:
        item = parse_item_line(line)
        print(describe_item(line, item))
        saved = item_savings(item)
        if saved is not None:
            total_saved += saved
    print("total saved: %.2f" % total_saved)


if __name__ == "__main__":
