def has_all_unique_chars(s):
    """Return True if every character in s appears exactly once."""
    if s is None:
        raise TypeError("s must be a string, not None")
    seen = set()
    for ch in s:
        if ch in seen:
            return False
        seen.add(ch)
    return True


def first_duplicate(s):
    """Return the first character that repeats, or None if all are unique."""
    seen = set()
    for ch in s:
        if ch in seen:
            return ch
        seen.add(ch)
    return None


def normalize(s, fold_case=False, ignored=None):
    """Prepare a string for analysis, optionally folding case and dropping chars."""
    if fold_case:
        s = s.casefold()
    if ignored is None:
        return s
    return "".join(ch for ch in s if ch not in ignored)


def analyze(s, fold_case=False, ignored=None):
    """Build a small report dictionary describing the uniqueness of s."""
    text = normalize(s, fold_case=fold_case, ignored=ignored)
    duplicate = first_duplicate(text)
    return {
        "original": s,
        "examined": text,
        "unique": duplicate is None,
        "duplicate": duplicate,
        "position": text.index(duplicate) if duplicate is not None else None,
    }


def describe(report):
    """Turn a report from analyze() into a one-line human readable summary."""
    label = repr(report["original"])
    if report["unique"]:
        return "%s: all characters unique" % label
    return "%s: repeats %r at index %d" % (
        label, report["duplicate"], report["position"])


def main(argv=None):
    if argv is None:
