def parse_numbers(text):
    """Parse a whitespace- or comma-separated list of integers.

    Returns the list of integers, or None if the text is not well formed.
    """
    cleaned = text.replace(",", " ").strip()
    if not cleaned:
        return None
    values = []
    for token in cleaned.split():
        try:
            values.append(int(token))
        except ValueError:
            return None
    return values


def validate_numbers(numbers):
    """Return a description of the first problem found, or None if valid."""
    if len(numbers) < 4:
        return "at least four numbers are required"
    for value in numbers:
        if value <= 0:
            return "all numbers must be positive (got {})".format(value)
    return None


def find_two_smallest(numbers):
    """Return the two smallest values of a list holding at least two items."""
    smallest = None
    second = None
    for value in numbers:
        if smallest is None or value < smallest:
            second = smallest
            smallest = value
        elif second is None or value < second:
            second = value
    return (smallest, second)


def sum_two_smallest(numbers):
    """Return the sum of the two smallest positive numbers in the list."""
    problem = validate_numbers(numbers)
    if problem is not None:
        raise ValueError(problem)
    smallest, second = find_two_smallest(numbers)
    return smallest + second


