import sys
from datetime import date, timedelta


def make_date(year, month, day):
    """Build a date object, or return None if the components are not a real date."""
    try:
        return date(year, month, day)
    except (ValueError, TypeError):
        return None


def days_between(target, today):
    """Return the number of full days from target up to today."""
    if target is None:
        raise ValueError("not a valid calendar date")
    if target > today:
        raise ValueError("date %s is in the future" % target.isoformat())
    return (today - target).days


def days_since(year, month, day):
    """Return the number of full days between the given past date and today."""
    return days_between(make_date(year, month, day), date.today())


def parse_date(text):
    """Parse 'YYYY-MM-DD' into a date, or return None if the text is malformed."""
    parts = text.strip().split("-")
    if len(parts) != 3 or not all(part.isdigit() for part in parts):
        return None
    return make_date(int(parts[0]), int(parts[1]), int(parts[2]))


def split_args(args):
    """Split arguments into the reference date and the dates to report on."""
    today = None
    dates = []
    for arg in args:
        if arg.startswith("--today="):
            today = parse_date(arg[len("--today="):])
            if today is None:
                raise ValueError("bad --today value: %s" % arg)
        else:
            dates.append(arg)
    if today is None:
        today = date.today()
    return today, dates


def anniversary(target, today):
    """Return the next yearly anniversary of target, or None for 29 February."""
    candidate = make_date(today.year, target.month, target.day)
    if candidate is None:
        return None
    if candidate <= today:
        candidate = make_date(today.year + 1, target.month, target.day)
    return candidate


def describe(text, today):
    """Turn one 'YYYY-MM-DD' argument into a human readable report line."""
    target = parse_date(text)
    if target is None:
        return "%s: not a date of the form YYYY-MM-DD" % text
    elapsed = days_between(target, today)
    report = "%s: %d day(s) ago" % (text, elapsed)
    upcoming = anniversary(target, today)
    if upcoming is not None:
        report += "; next anniversary %s in %d day(s)" % (upcoming.isoformat(),
                                                          (upcoming - today).days)
    return report


def main(argv):
    try:
        today, dates = split_args(argv[1:])
        if not dates:
            dates = [(today - timedelta(days=1)).isoformat()]
        for text in dates:
            print(describe(text, today))
    except ValueError as exc:
        print(exc, file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

