class BankAccount:
    """A simple bank account with deposits, withdrawals and a transaction log."""

    def __init__(self, initial_balance=None, owner=None):
        if initial_balance is None:
            initial_balance = 0
        if not isinstance(initial_balance, (int, float)) or initial_balance < 0:
            raise ValueError("initial balance must be a non-negative number")
        self.owner = "unnamed" if owner is None else str(owner)
        self.balance = initial_balance
        self.history = []

    @staticmethod
    def _clean(amount):
        """Return amount as a positive number, or None if it is not usable."""
        if amount is None:
            return None
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            return None
        if amount <= 0:
            return None
        return amount

    def deposit(self, amount):
        value = self._clean(amount)
        if value is None:
            return False
        self.balance += value
        self.history.append(("deposit", value, self.balance))
        return True

    def withdraw(self, amount):
        value = self._clean(amount)
        if value is None:
            return False
        if value > self.balance:
            return False
        self.balance -= value
        self.history.append(("withdraw", value, self.balance))
        return True

    def last_transaction(self):
        """Most recent (kind, amount, balance) triple, or None if there is none."""
        if not self.history:
            return None
        return self.history[-1]

    def statement(self):
        lines = ["Statement for %s" % self.owner]
        for kind, value, balance in self.history:
            lines.append("  %-8s %10.2f -> %10.2f" % (kind, value, balance))
        last = self.last_transaction()
        if last is None:
            lines.append("  (no transactions)")
        lines.append("Final balance: %.2f" % self.balance)
        return "\n".join(lines)


def parse_command(text):
    """Turn 'deposit 50' into ('deposit', 50.0); return None for bad input."""
    parts = text.split()
    if len(parts) != 2:
        return None
    action, raw = parts[0].lower(), parts[1]
    if action not in ("deposit", "withdraw"):
        return None
    try:
        return action, float(raw)
    except ValueError:
        return None


def run_commands(account, commands):
    """Apply each command, reporting the outcome of every line."""
    for text in commands:
        parsed = parse_command(text)
        if parsed is None:
            print("%-14s ignored (cannot parse)" % text)
            continue
        action, amount = parsed
        method = account.deposit if action == "deposit" else account.withdraw
        ok = method(amount)
        print("%-14s %s (balance %.2f)" % (text, "OK" if ok else "REFUSED", account.balance))


def main():
    acc = BankAccount(100, owner="Ada")
    run_commands(acc, ["deposit 50", "withdraw 200", "withdraw 20", "transfer 5", "deposit -3"])
    print(acc.statement())

    empty = BankAccount()
    if empty.last_transaction() is None:
        print("New account for %s starts with a clean history." % empty.owner)


if __name__ == "__main__":
    main()

