def parse_time(text):
    """Convert 'HH:MM' into minutes from midnight, or None if malformed."""
    parts = text.strip().split(":")
    if len(parts) != 2:
        return None
    hours, minutes = parts
    if not (hours.isdigit() and minutes.isdigit()):
        return None
    total = int(hours) * 60 + int(minutes)
    if total > 24 * 60:
        return None
    return total


def parse_end(text, start):
    """Parse an end time, either 'HH:MM' or '+<minutes>' after start."""
    if text.startswith("+"):
        offset = text[1:]
        if not offset.isdigit():
            return None
        return start + int(offset)
    return parse_time(text)


def parse_event(line):
    """Parse 'name,HH:MM,HH:MM' or 'name,HH:MM,+30' into (name, (start, end))."""
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 3:
        return None
    name, raw_start, raw_end = fields
    if not name:
        return None
    start = parse_time(raw_start)
    if start is None:
        return None
    end = parse_end(raw_end, start)
    if end is None:
        return None
    if end < start:
        return None
    return name, (start, end)


def check_event_overlap(event1, event2):
    start1, end1 = event1
    start2, end2 = event2
    return start1 < end2 and start2 < end1


def find_conflict(event, schedule):
    """Return the first (name, times) in schedule overlapping event, else None."""
    for name, times in schedule:
        if check_event_overlap(event, times):
            return name, times
    return None


def format_time(minutes):
    return "{:02d}:{:02d}".format(minutes // 60, minutes % 60)


def format_event(name, times):
    start, end = times
    return "{} ({}-{})".format(name, format_time(start), format_time(end))


def build_schedule(lines, day_end=None):
    """Accept lines one by one, reporting conflicts and rejected entries."""
    schedule = []
    report = []
    for line in lines:
        parsed = parse_event(line)
        if parsed is None:
            report.append("skipped unreadable entry: " + line.strip())
            continue
        name, times = parsed
        if day_end is not None and times[1] > day_end:
            report.append(name + " ends after the working day")
            continue
        clash = find_conflict(times, schedule)
        if clash is None:
            schedule.append((name, times))
            report.append("added " + format_event(name, times))
        else:
            report.append("{} clashes with {}".format(name, format_event(*clash)))
    return schedule, report


def find_gap(schedule, duration, day_end):
    """Return the start of the first free slot of `duration` minutes, else None."""
    cursor = 0
    for entry in sorted(schedule, key=lambda item: item[1]):
        start, end = entry[1]
        if start - cursor >= duration:
            return cursor
        cursor = max(cursor, end)
    if day_end - cursor >= duration:
        return cursor
    return None


def main():
    lines = [
        "standup,09:00,+15",
        "design review,10:00,11:00",
        "lunch,11:30,12:30",
        "budget talk,10:30,11:15",
        "retro,15:00",
        "gym,18:00,19:00",
    ]
    closing = 20 * 60
    schedule, report = build_schedule(lines, day_end=closing)
    for message in report:
        print(message)
    print("--- final schedule ---")
    for name, times in sorted(schedule, key=lambda item: item[1]):
        print(format_event(name, times))
    slot = find_gap(schedule, 60, closing)
    if slot is None:
        print("no free hour before " + format_time(closing))
    else:
        print("next free hour starts at " + format_time(slot))


if __name__ == "__main__":
    main()

