import random

LOW = 1
HIGH = 100


def validate_target(target):
    """Return the target as an int, or None if it is not a usable value."""
    if isinstance(target, bool) or not isinstance(target, int):
        return None
    if target < LOW or target > HIGH:
        return None
    return target


def play_guessing_game(target, max_guesses):
    """Guess randomly in [1, 100]; return guesses used, or -1 on failure."""
    checked = validate_target(target)
    if checked is None:
        raise ValueError("target must be an integer between 1 and 100")
    if max_guesses is None or max_guesses < 1:
        return -1
    for attempt in range(1, max_guesses + 1):
        if random.randint(LOW, HIGH) == checked:
            return attempt
    return -1


def run_trials(target, max_guesses, trials, seed=None):
    """Play the game several times and collect the successful guess counts."""
    if seed is not None:
        random.seed(seed)
    results = []
    for _ in range(trials):
        results.append(play_guessing_game(target, max_guesses))
    return results


def summarize(results):
    """Build a summary dict; average is None when nothing ever succeeded."""
    wins = [r for r in results if r != -1]
    average = sum(wins) / len(wins) if wins else None
    best = min(wins) if wins else None
    return {
        "trials": len(results),
        "wins": len(wins),
        "average_guesses": average,
        "best": best,
    }


def format_summary(target, summary):
    lines = ["target %d over %d trials" % (target, summary["trials"]),
             "  successes: %d" % summary["wins"]]
    average = summary["average_guesses"]
    if average is None:
        lines.append("  average guesses: n/a")
    else:
        lines.append("  average guesses: %.2f" % average)
    best = summary["best"]
    if best is not None:
        lines.append("  best run: %d guesses" % best)
    return "\n".join(lines)


def main():
    scenarios = [(50, 10, 200, 1), (99, 1, 200, 2), (7, 100, 200, 3)]
    for target, max_guesses, trials, seed in scenarios:
        results = run_trials(target, max_guesses, trials, seed)
        print(format_summary(target, summarize(results)))
        first_win = next((r for r in results if r != -1), None)
        if first_win is None:
            print("  no trial found the target")
        else:
            print("  first winning trial used %d guesses" % first_win)


if __name__ == "__main__":
    main()

