        "average_guesses": average,
        "best": best,
    }


def format_summary(target, summary):
    lines = ["target %d over %d trials" % (target, summary["trials"]),
             "  successes: %d" % summary["wins"]]
    average = summary["average_guesses"]
    if average == None:
        lines.append("  average guesses: n/a")
    else:
        lines.append("  average guesses: %.2f" % average)
    best = summary["best"]
    if best != None:
        lines.append("  best run: %d guesses" % best)
    return "\n".join(lines)


def main():
    scenarios = [(50, 10, 200, 1), (99, 1, 200, 2), (7, 100, 200, 3)]
    for target, max_guesses, trials, seed in scenarios:
