    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(number) or number <= 0.0:
        return None
    return number


def normalize_sides(a, b, c):
    """Return the three sides as positive floats, or None if any is invalid."""
    sides = []
    for value in (a, b, c):
        side = parse_side(value)
        if side is None:
            return None
        sides.append(side)
    return tuple(sides)


def parse_triangle(line):
    """Parse three side lengths from a text line, or None if unusable."""
    tokens = line.replace(",", " ").split()
    if len(tokens) != 3:
        return None
    return normalize_sides(*tokens)


def triangle_area(a, b, c):
    """Heron's formula area, or 0.0 when the sides form no triangle."""
    sides = normalize_sides(a, b, c)
    if sides is None:
        return 0.0
    x, y, z = sides
    if x + y <= z or x + z <= y or y + z <= x:
        return 0.0
    s = (x + y + z) / 2.0
    return math.sqrt(s * (s - x) * (s - y) * (s - z))


def classify(a, b, c):
