class Task:
    def __init__(self, name, due=None):
        self.name = name
        self.due = due
        self.completed = False

    def describe(self):
        status = "done" if self.completed else "pending"
        if self.due is None:
            return "%s [%s]" % (self.name, status)
        return "%s (due %s) [%s]" % (self.name, self.due, status)


def parse_due(text):
    if text is None:
        return None
    text = text.strip()
    if not text:
        return None
    parts = text.split("-")
    if len(parts) != 3:
        raise ValueError("due date must look like YYYY-MM-DD: %r" % text)
    year, month, day = parts
    return "%04d-%02d-%02d" % (int(year), int(month), int(day))


class ToDoList:
    def __init__(self):
        self._tasks = []

    def _find(self, task_name):
        for task in self._tasks:
            if task.name == task_name:
                return task
        return None

    def add_task(self, task_name, due=None):
        if task_name is None:
            raise ValueError("task name is required")
        task_name = task_name.strip()
        if not task_name:
            raise ValueError("task name must not be empty")
        if self._find(task_name) is not None:
            return False
        self._tasks.append(Task(task_name, parse_due(due)))
        return True

    def mark_completed(self, task_name):
        task = self._find(task_name)
        if task is None:
            return False
        task.completed = True
        return True

    def get_pending_tasks(self):
        return [task.name for task in self._tasks if not task.completed]

    def next_due(self):
        soonest = None
        for task in self._tasks:
            if task.completed or task.due is None:
                continue
            if soonest is None or task.due < soonest.due:
                soonest = task
        return soonest

    def report(self):
        lines = [task.describe() for task in self._tasks]
        upcoming = self.next_due()
        if upcoming is not None:
            lines.append("next up: %s on %s" % (upcoming.name, upcoming.due))
        return "\n".join(lines)


def main():
    todo = ToDoList()
    todo.add_task("Buy milk")
    todo.add_task("Walk dog", due="2026-10-02")
    todo.add_task("Pay rent", due="2026-10-01")
    todo.mark_completed("Buy milk")
    if not todo.mark_completed("Call plumber"):
        print("cannot complete an unknown task: Call plumber")
    print(todo.get_pending_tasks())
    print(todo.report())


if __name__ == "__main__":
    main()

