def levenshtein_distance(s1, s2):
    """Minimum number of insertions, deletions or substitutions turning s1 into s2."""
    if s1 is None:
        raise ValueError("s1 must be a string")
    if s2 is None:
        raise ValueError("s2 must be a string")
    if len(s1) < len(s2):
        s1, s2 = s2, s1

    previous = list(range(len(s2) + 1))
    for i, ch1 in enumerate(s1, start=1):
        current = [i]
        for j, ch2 in enumerate(s2, start=1):
            insertion = current[j - 1] + 1
            deletion = previous[j] + 1
            substitution = previous[j - 1] + (ch1 != ch2)
            current.append(min(insertion, deletion, substitution))
        previous = current
    return previous[-1]


def normalize(word, casefold=True, strip_chars=None):
    """Prepare a word for comparison; strip_chars defaults to surrounding whitespace."""
    cleaned = word.strip() if strip_chars is None else word.strip(strip_chars)
    return cleaned.casefold() if casefold else cleaned


def similarity(s1, s2):
    """1.0 for identical strings, 0.0 when every character differs."""
    longest = max(len(s1), len(s2))
    if longest == 0:
        return 1.0
    return 1.0 - levenshtein_distance(s1, s2) / longest


def closest_word(word, candidates, max_distance=None):
    """Return (candidate, distance) for the nearest candidate, or None if none qualifies."""
    target = normalize(word)
    best = None
    best_distance = None
    for candidate in candidates:
        distance = levenshtein_distance(target, normalize(candidate))
        if max_distance is not None and distance > max_distance:
            continue
        if best_distance is None or distance < best_distance:
            best, best_distance = candidate, distance
    if best is None:
        return None
    return best, best_distance


def spell_report(words, dictionary, max_distance=2):
    """Describe, for each word, whether it is known or which entry is nearest."""
    lines = []
    for word in words:
        match = closest_word(word, dictionary, max_distance)
        if match is None:
            lines.append("{0}: no suggestion".format(word))
        elif match[1] == 0:
            lines.append("{0}: correct".format(word))
        else:
            lines.append("{0}: did you mean {1}? (distance {2}, similarity {3:.2f})".format(
                word, match[0], match[1], similarity(normalize(word), normalize(match[0]))))
    return "\n".join(lines)


def main():
    pairs = [("kitten", "sitting"), ("flaw", "lawn"), ("", "abc"), ("same", "same")]
    for left, right in pairs:
        print("d({0!r}, {1!r}) = {2}".format(left, right, levenshtein_distance(left, right)))

    dictionary = ["kitten", "sitting", "flaw", "lawn", "python", "distance"]
    print(spell_report(["  Kitten ", "pythn", "lawm", "zzzzzzzz"], dictionary))

    nearest = closest_word("distanse", dictionary)
    print("nearest to 'distanse':", nearest[0], "at distance", nearest[1])


if __name__ == "__main__":
    main()

