def normalize(word):
    """Return the lower-cased word, or None if it carries no letters or digits."""
    if word is None:
        return None
    cleaned = word.strip().lower()
    if not cleaned:
        return None
    if not any(ch.isalnum() for ch in cleaned):
        return None
    return cleaned


def word_frequency(words):
    """Count words case-insensitively and return {word: frequency}."""
    counts = {}
    for raw in words:
        key = normalize(raw)
        if key is None:
            continue
        counts[key] = counts.get(key, 0) + 1
    return counts


def most_common(counts, limit=None):
    """Return (word, count) pairs sorted by descending count, then alphabetically."""
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    if limit is None:
        return ordered
    return ordered[:limit]


def dominant_word(counts):
    """Return the single word with the highest count, or None if there is a tie or no data."""
    ranked = most_common(counts, limit=2)
    if not ranked:
        return None
    if len(ranked) == 2 and ranked[0][1] == ranked[1][1]:
        return None
    return ranked[0][0]


def format_report(counts, title=None, limit=None):
    lines = []
    if title is not None:
        lines.append(title)
    if not counts:
        lines.append("  (no words)")
        return "\n".join(lines)
    width = max(len(word) for word, _ in counts.items())
    for word, count in most_common(counts, limit):
        lines.append("  {0:<{1}}  {2}".format(word, width, count))
    top = dominant_word(counts)
    if top is None:
        lines.append("  no single most frequent word")
    else:
        lines.append("  most frequent: " + top)
    return "\n".join(lines)


