def normalize_key(key_char):
    """Return the key as a single character, or None if it cannot be used."""
    if key_char == None:
        return None
    if isinstance(key_char, int):
        if 0 <= key_char <= 0x10FFFF:
            return chr(key_char)
        return None
    if isinstance(key_char, str) and len(key_char) == 1:
        return key_char
    return None


def xor_cipher(text, key_char):
    """XOR every character of text with key_char; applying it twice restores text."""
    if text == None:
        raise TypeError("text must be a string, not None")
    key = normalize_key(key_char)
    if key == None:
        raise ValueError("key_char must be one character or a code point")
    code = ord(key)
    return ''.join(chr(ord(ch) ^ code) for ch in text)


def to_escapes(s):
    """Render a (possibly unprintable) cipher string using \\xNN escapes."""
    pieces = []
    for ch in s:
        if ch.isprintable() and ch != '\\':
            pieces.append(ch)
        else:
            pieces.append('\\x%02x' % ord(ch))
    return ''.join(pieces)


def parse_escapes(s):
    """Inverse of to_escapes; returns None when the input is malformed."""
    if s == None:
        return None
    out = []
    i = 0
    while i < len(s):
        if s[i] == '\\':
            if i + 3 >= len(s) or s[i + 1] != 'x':
                return None
            try:
                out.append(chr(int(s[i + 2:i + 4], 16)))
            except ValueError:
                return None
            i += 4
        else:
            out.append(s[i])
            i += 1
    return ''.join(out)


def recover_key(cipher, plain):
    """Deduce the key that maps cipher to plain, or None if there is none."""
    if cipher == None:
        return None
    if not cipher or len(cipher) != len(plain):
        return None
    candidate = ord(cipher[0]) ^ ord(plain[0])
    if candidate > 0x10FFFF:
        return None
    key = chr(candidate)
    if xor_cipher(cipher, key) != plain:
        return None
    return key


def main():
    for text, key in [('Hello', 'A'), ('Test', 'B'), ('secret message', 65)]:
        cipher = xor_cipher(text, key)
        shown = to_escapes(cipher)
        print('%-16r -> %s' % (text, shown))
        round_trip = xor_cipher(cipher, key)
        print('   round trip: %r (%s)' % (round_trip,
                                          'ok' if round_trip == text else 'FAILED'))
        restored = parse_escapes(shown)
        if restored == None:
            print('   escape form could not be parsed back')
        elif restored != cipher:
            print('   escape form does not match the cipher text')
        found = recover_key(cipher, text)
        if found != None:
            print('   recovered key: %r' % found)
        else:
            print('   key could not be recovered')


if __name__ == '__main__':
    main()

