def coerce_to_list(value):
    """Return value as a list, or None if it cannot be treated as a sequence."""
    if value is None:
        return None
    if isinstance(value, (str, bytes)):
        return None
    try:
        return list(value)
    except TypeError:
        return None


def cartesian_product(list1, list2):
    """Return all ordered pairs (x, y) with x from list1 and y from list2."""
    left = coerce_to_list(list1)
    if left is None:
        raise TypeError("list1 must be a non-string iterable of items")
    right = coerce_to_list(list2)
    if right is None:
        raise TypeError("list2 must be a non-string iterable of items")
    pairs = []
    for x in left:
        for y in right:
            pairs.append((x, y))
    return pairs


def find_pair(pairs, first, second):
    """Return the first pair matching both components, or None if absent."""
    for pair in pairs:
        if pair[0] == first and pair[1] == second:
            return pair
    return None


def group_by_first(pairs):
    """Map each first component to the list of its partners."""
    groups = {}
    for first, second in pairs:
        partners = groups.get(first)
        if partners is None:
            partners = []
            groups[first] = partners
        partners.append(second)
    return groups


def format_pairs(pairs, per_line=None):
    """Render pairs as text, wrapping after per_line entries (default: all)."""
    if per_line is None:
        per_line = len(pairs) or 1
    rendered = ["({!r}, {!r})".format(a, b) for a, b in pairs]
    lines = []
    for start in range(0, len(rendered), per_line):
        lines.append(", ".join(rendered[start:start + per_line]))
    if not lines:
        return "[]"
    return "\n".join(lines)


def report(list1, list2, title=None):
    """Print the product of two lists together with a small summary."""
    if title is None:
        title = "product of {} x {} items".format(len(list1), len(list2))
    pairs = cartesian_product(list1, list2)
    print(title)
    print(format_pairs(pairs, per_line=len(list2) if list2 else None))
    for first, partners in group_by_first(pairs).items():
        print("  {!r} -> {}".format(first, partners))
    return pairs


def main():
    pairs = report([1, 2], ["a", "b"], title="digits and letters")
    hit = find_pair(pairs, 2, "a")
    if hit is not None:
        print("found", hit)
    miss = find_pair(pairs, 3, "a")
    if miss is None:
        print("no pair starting with 3")
    print(report([1], [], title="empty right side"))
    try:
        cartesian_product([1, 2], None)
    except TypeError as exc:
        print("rejected:", exc)


if __name__ == "__main__":
    main()

