def _first_index(password, predicate):
    """Return the index of the first character satisfying predicate, else None."""
    for index, char in enumerate(password):
        if predicate(char):
            return index
    return None


def analyze(password):
    """Map each character class to the index where it first appears (or None)."""
    return {
        'uppercase': _first_index(password, str.isupper),
        'lowercase': _first_index(password, str.islower),
        'digit': _first_index(password, str.isdigit),
    }


def count_criteria(password):
    """Count the satisfied criteria: length >= 8 plus each character class present."""
    analysis = analyze(password)
    met = sum(1 for position in analysis.values() if position is not None)
    if len(password) >= 8:
        met += 1
    return met


def check_password_strength(password):
    if password is None:
        raise ValueError('password must be a string, not None')

    analysis = analyze(password)
    classes = sum(1 for position in analysis.values() if position is not None)

    if len(password) >= 8 and classes == 3:
        return 'Strong'
    if len(password) >= 6 and count_criteria(password) >= 2:
        return 'Medium'
    return 'Weak'


def suggest_improvement(password):
    """Return the most useful single hint, or None when nothing is missing."""
    analysis = analyze(password)
    if len(password) < 8:
        return 'use at least 8 characters'
    for name in ('uppercase', 'lowercase', 'digit'):
        if analysis[name] is None:
            return 'add a %s character' % name
    return None


def describe_first_digit(password):
    position = analyze(password)['digit']
    if position is None:
        return 'no digit'
    return 'first digit at position %d' % position


def format_report(password, label, hint):
    line = '%-14s %-6s %s' % (repr(password), label, describe_first_digit(password))
    if hint is not None:
        line += ' | hint: ' + hint
    return line


def main():
    samples = ['P@ssw0rd', 'password', 'abc', 'Passw0', 'LONGPASSWORD1', '12345678']
    for sample in samples:
        label = check_password_strength(sample)
        hint = suggest_improvement(sample)
        print(format_report(sample, label, hint))


if __name__ == '__main__':
    main()

