import sys

_PRIME_CACHE = {}


def is_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("is_prime() requires an integer")
    cached = _PRIME_CACHE.get(n)
    if cached is not None:
        return cached
    if n < 2:
        result = False
    elif n < 4:
        result = True
    elif n % 2 == 0:
        result = False
    else:
        result = True
        divisor = 3
        while divisor * divisor <= n:
            if n % divisor == 0:
                result = False
                break
            divisor += 2
    _PRIME_CACHE[n] = result
    return result


def parse_int(text):
    """Return the integer described by text, or None if it is not an integer."""
    try:
        return int(text.strip())
    except (ValueError, AttributeError):
        return None


def primes_up_to(limit):
    """Return the list of primes p with p <= limit."""
    return [n for n in range(2, limit + 1) if is_prime(n)]


def format_prime_list(text):
    """Return a report of the primes up to the limit written in text."""
    limit = parse_int(text)
    if limit is None:
        return "%r is not a valid limit" % (text,)
    return "primes up to %d: %s" % (limit, primes_up_to(limit))


def describe(value):
    """Return a one-line human readable verdict for value."""
    number = parse_int(value) if isinstance(value, str) else value
    if number is None:
        return "%r is not an integer" % (value,)
    if is_prime(number):
        return "%d is prime" % number
    follower = next_prime(number, upper=number + 1000)
    if follower is None:
        return "%d is not prime (no prime found nearby)" % number
    return "%d is not prime; the next prime is %d" % (number, follower)


def next_prime(n, upper=None):
    """Return the smallest prime strictly greater than n, or None if the
    search passes the optional inclusive bound upper."""
    candidate = n + 1 if n >= 2 else 2
    while True:
        if upper is not None and candidate > upper:
            return None
        if is_prime(candidate):
            return candidate
        candidate += 1


