def _peek(values, index):
    """Return values[index], or None when the index is past the end."""
    if index < len(values):
        return values[index]
    return None


def _validate(values, name):
    if values is None:
        raise ValueError(name + " must be a list, not None")
    for item in values:
        if item is None:
            raise ValueError(name + " must not contain None")
    return list(values)


def merge_sorted_lists(list1, list2):
    """Merge two sorted lists of numbers into a new sorted list."""
    left = _validate(list1, "list1")
    right = _validate(list2, "list2")
    merged = []
    i = j = 0
    while i < len(left) or j < len(right):
        a = _peek(left, i)
        b = _peek(right, j)
        if a is None:
            merged.append(b)
            j += 1
        elif b is None:
            merged.append(a)
            i += 1
        elif a <= b:
            merged.append(a)
            i += 1
        else:
            merged.append(b)
            j += 1
    return merged


def merge_many(lists):
    """Merge any number of sorted lists by folding merge_sorted_lists."""
    result = None
    for current in lists:
        if result is None:
            result = _validate(current, "list")
        else:
            result = merge_sorted_lists(result, current)
    if result is None:
        return []
    return result


def median(values):
    """Median of an already sorted list, or None if it is empty."""
    size = len(values)
    if size == 0:
        return None
    middle = size // 2
    if size % 2 == 1:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2


def format_report(merged, label=None):
    head = "merged" if label is None else label
    mid = median(merged)
    if mid is None:
        summary = "empty"
    else:
        summary = "n=%d median=%s" % (len(merged), mid)
    return "%s: %s (%s)" % (head, merged, summary)


def main():
    print(format_report(merge_sorted_lists([1, 3, 5], [2, 4, 6])))
    print(format_report(merge_sorted_lists([10], []), label="single"))
    print(format_report(merge_sorted_lists([], [])))
    print(format_report(merge_many([[1, 9], [2, 3], [], [0, 4, 11]]), "folded"))
    try:
        merge_sorted_lists([1, 2], None)
    except ValueError as exc:
        print("rejected:", exc)


if __name__ == "__main__":
    main()

