import re

_SIMULATED_FILES = {
    'report.txt': 'The quarterly revenue grew; extraordinary results were recorded in 2024.',
    'inventory.txt': 'bolt42 washer nut screwdriver',
    'empty.txt': '',
}


def read_file_text(filepath):
    """Return the text of filepath, falling back to the simulated store.

    Returns None when the path is unusable or the file cannot be located.
    """
    if filepath is None:
        return None
    try:
        with open(filepath, 'r', encoding='utf-8') as handle:
            return handle.read()
    except OSError:
        return _SIMULATED_FILES.get(filepath)


def extract_words(text):
    """Split text into alphanumeric sequences."""
    if text is None:
        return []
    return re.findall(r'[A-Za-z0-9]+', text)


def longest_word(words):
    """Return the first of the longest words, or None when there are none."""
    best = None
    for word in words:
        if best is None or len(word) > len(best):
            best = word
    return best


def find_longest_word_in_file(filepath):
    contents = read_file_text(filepath)
    if contents is None:
        return ''
    winner = longest_word(extract_words(contents))
    if winner is None:
        return ''
    return winner


def describe_file(filepath):
    """Build a one-line human readable summary for a file."""
    contents = read_file_text(filepath)
    if contents is None:
        return '{}: not found'.format(filepath)
    words = extract_words(contents)
    winner = longest_word(words)
    if winner is None:
        return '{}: no words found'.format(filepath)
    return '{}: {} words, longest = {!r} ({} chars)'.format(
        filepath, len(words), winner, len(winner))


def main():
    targets = ['report.txt', 'inventory.txt', 'empty.txt', 'ledger.txt']
    for name in targets:
        print(describe_file(name))

    overall = None
    for name in targets:
        word = find_longest_word_in_file(name)
        if word and (overall is None or len(word) > len(overall)):
            overall = word
    if overall is not None:
        print('Longest word across all files: {}'.format(overall))
    else:
        print('No words in any file.')


if __name__ == '__main__':
    main()

