_FACTORIAL_CACHE = {0: 1, 1: 1}


def calculate_factorial(n):
    """Return n! for a non-negative integer n, using an iterative loop."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    cached = _FACTORIAL_CACHE.get(n)
    if cached is not None:
        return cached
    start = n
    while _FACTORIAL_CACHE.get(start) is None:
        start -= 1
    result = _FACTORIAL_CACHE[start]
    for k in range(start + 1, n + 1):
        result *= k
        _FACTORIAL_CACHE[k] = result
    return result


def parse_non_negative_int(text):
    """Convert a string to a non-negative int, or None if it is not one."""
    stripped = text.strip()
    if not stripped.isdigit():
        return None
    return int(stripped)


def format_factorial(text, max_digits=None):
    """Describe the factorial of the number written in `text` as a string."""
    value = parse_non_negative_int(text)
    if value is None:
        return "%s: not a non-negative integer" % text.strip()
    digits = calculate_factorial(value)
    rendered = str(digits)
    if max_digits is not None and len(rendered) > max_digits:
        rendered = rendered[:max_digits] + "... (%d digits)" % len(rendered)
    return "%d! = %s" % (value, rendered)


def factorial_table(start, stop):
    """Return a list of (n, n!) pairs for n in [start, stop]."""
    rows = []
    for n in range(start, stop + 1):
        rows.append((n, calculate_factorial(n)))
    return rows


def main(argv=None):
    import sys

    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        for n, value in factorial_table(0, 10):
            print("%2d! = %d" % (n, value))
        return 0
    exit_code = 0
    for arg in argv:
        line = format_factorial(arg, max_digits=40)
        print(line)
        if parse_non_negative_int(arg) is None:
            exit_code = 1
    return exit_code


if __name__ == "__main__":
    raise SystemExit(main())

