def group_by_type(items):
    """Group items by their type name, preserving input order within each group."""
    if items is None:
        raise ValueError("items must be a list, not None")
    groups = {}
    for item in items:
        name = type(item).__name__
        bucket = groups.get(name)
        if bucket is None:
            bucket = []
            groups[name] = bucket
        bucket.append(item)
    return groups


def group_sizes(groups):
    """Map each type name to the number of items collected under it."""
    return {name: len(members) for name, members in groups.items()}


def largest_group(groups):
    """Return (name, members) of the biggest group, or None for an empty mapping."""
    best = None
    for name, members in groups.items():
        if best is None or len(members) > len(best[1]):
            best = (name, members)
    return best


def format_group(name, members, limit=None):
    """Render one group as a single line, optionally truncating the member list."""
    if limit is not None and len(members) > limit:
        shown = members[:limit]
        suffix = " ... (+%d more)" % (len(members) - limit)
    else:
        shown = members
        suffix = ""
    rendered = ", ".join(repr(m) for m in shown)
    return "%-10s %2d  [%s]%s" % (name, len(members), rendered, suffix)


def report(items, limit=None):
    """Build a human readable report of the type grouping of items."""
    groups = group_by_type(items)
    lines = []
    for name in sorted(groups):
        lines.append(format_group(name, groups[name], limit))
    top = largest_group(groups)
    if top is None:
        lines.append("no items to group")
    else:
        lines.append("most common type: %s (%d items)" % (top[0], len(top[1])))
