def parse_pair(text):
    """Parse a 'key=value' line into a [key, value] pair, or None if it is blank."""
    stripped = text.strip()
    if not stripped or stripped.startswith("#"):
        return None
    if "=" not in stripped:
        raise ValueError("malformed line: %r" % text)
    key, _, raw = stripped.partition("=")
    raw = raw.strip()
    try:
        value = int(raw)
    except ValueError:
        value = raw
    return [key.strip(), value]


def parse_pairs(lines):
    """Turn an iterable of configuration lines into a list of [key, value] pairs."""
    pairs = []
    for line in lines:
        pair = parse_pair(line)
        if pair is not None:
            pairs.append(pair)
    return pairs


def list_to_dict(key_value_list):
    """Build a dict from [key, value] pairs; later duplicates win."""
    if key_value_list is None:
        raise ValueError("key_value_list must be a list of pairs, not None")
    result = {}
    for pair in key_value_list:
        if pair is None or len(pair) != 2:
            raise ValueError("each entry must be a [key, value] pair: %r" % (pair,))
        key, value = pair
        result[key] = value
    return result


def overridden_keys(key_value_list):
    """Report keys whose value was replaced, as {key: number_of_discarded_values}."""
    counts = {}
    discarded = {}
    for pair in key_value_list:
        key = pair[0]
        previous = counts.get(key)
        if previous is not None:
            discarded[key] = previous
        counts[key] = (previous or 0) + 1
    return discarded


def lookup(mapping, key, default=None):
    """Fetch a key, falling back to default when it is absent."""
    value = mapping.get(key)
    if value is None:
        return default
    return value


def format_report(mapping, discarded):
    lines = []
    for key in sorted(mapping, key=str):
        extra = discarded.get(key)
        if extra is None:
            lines.append("%s = %r" % (key, mapping[key]))
        else:
            lines.append("%s = %r (%d earlier value(s) dropped)" % (key, mapping[key], extra))
    return "\n".join(lines)


def main():
    print(list_to_dict([['a', 1], ['b', 2]]))
    print(list_to_dict([['x', 10], ['y', 20], ['x', 30]]))

    config_text = """
    # server settings
    host = localhost
    port = 8080

    port = 9090
    retries = 3
    """
    pairs = parse_pairs(config_text.splitlines())
    settings = list_to_dict(pairs)
    print(format_report(settings, overridden_keys(pairs)))
    print("timeout:", lookup(settings, "timeout", 30))


if __name__ == "__main__":
