def parse_range(text):
    """Parse 'start:end' into a numeric tuple, or None when it is malformed."""
    parts = text.split(":")
    if len(parts) != 2:
        return None
    try:
        return (parse_number(parts[0]), parse_number(parts[1]))
    except ValueError:
        return None


def parse_pair(text1, text2):
    """Parse two range strings, returning None if either one is unreadable."""
    first = parse_range(text1)
