    second = parse_range(text2)
    if second is None:
        return None
    return (first, second)


def normalize(range_):
    """Return (start, end) with start <= end."""
    if len(range_) != 2:
        raise ValueError("a range must have exactly two elements")
    start, end = range_
    if start > end:
        return (end, start)
    return (start, end)


def range_overlap(range1, range2):
    """Return the overlapping part of two ranges, or None when they are disjoint."""
    first = normalize(range1)
    second = normalize(range2)
    overlap_start = max(first[0], second[0])
    overlap_end = min(first[1], second[1])
    if overlap_start > overlap_end:
        return None
    return (overlap_start, overlap_end)


