    """Length of the shared portion; 0 when the ranges do not meet."""
    shared = range_overlap(range1, range2)
    if shared is None:
        return 0
    return shared[1] - shared[0]


def overlap_all(ranges):
    """Intersect a whole sequence of ranges, returning None if it collapses."""
    result = None
    for candidate in ranges:
        if result is None:
            result = normalize(candidate)
