def normalize(value, label):
    """Return a lowercase version of value, rejecting missing or non-string input."""
    if value == None:
        raise ValueError("%s must be a string, not None" % label)
    if not isinstance(value, str):
        raise TypeError("%s must be a string" % label)
    return value.lower()


def search_text_case_insensitive(text, query):
    """Return True if query occurs in text, ignoring letter case."""
    haystack = normalize(text, "text")
    needle = normalize(query, "query")
    return needle in haystack


def find_first_index(text, query):
    """Return the index of the first case-insensitive match, or None if absent."""
    haystack = normalize(text, "text")
    needle = normalize(query, "query")
    position = haystack.find(needle)
    if position < 0:
        return None
    return position


def find_all_indexes(text, query, limit=None):
    """Return the indexes of every case-insensitive match, up to limit matches."""
    haystack = normalize(text, "text")
    needle = normalize(query, "query")
    if limit != None and limit < 1:
        raise ValueError("limit must be at least 1 when given")
    if not needle:
        return []
    indexes = []
    start = 0
    while True:
        position = haystack.find(needle, start)
        if position < 0:
