MULTI_PART_SUFFIXES = {"co.uk", "org.uk", "ac.uk", "com.au", "co.jp", "co.nz", "com.br", "co.za"}
ALLOWED_SCHEMES = frozenset({"http", "https", "ftp", "ftps"})

def extract_domain(url):
    """Return the main label of the URL's host, without 'www.' or the TLD."""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    host = _host_from_url(url)
    if host is None:
        raise ValueError("URL contains no host: %r" % url)
    name = _registrable_name(host)
    if name is None:
        raise ValueError("host has no top-level domain: %r" % host)
    return name.lower()

def safe_extract_domain(url):
    """Like extract_domain, but returns None for URLs that cannot be parsed."""
    try:
        return extract_domain(url)
    except (TypeError, ValueError):
        return None

def format_report(urls):
    lines = []
    for url in urls:
        domain = safe_extract_domain(url)
        if domain is None:
            lines.append("%-42s -> <unrecognised>" % url)
        else:
            lines.append("%-42s -> %s" % (url, domain))
    return "\n".join(lines)

def _host_from_url(url):
    """Return the host part of a URL, or None when no usable host is present."""
    rest = url.strip()
    scheme = None
    marker = rest.find("://")
    if marker != -1:
        scheme = rest[:marker].lower()
        rest = rest[marker + 3:]
    if scheme is not None and scheme not in ALLOWED_SCHEMES:
        return None
    for separator in ("/", "?", "#"):
        cut = rest.find(separator)
        if cut != -1:
            rest = rest[:cut]
    if "@" in rest:
        rest = rest.split("@", 1)[1]
    if ":" in rest:
        rest = rest.split(":", 1)[0]
    if rest.lower().startswith("www.") and rest.count(".") > 1:
        rest = rest[4:]
    return rest or None

def _registrable_name(host):
    """Return the main label of a host, or None if the host carries no TLD."""
    labels = [label for label in host.split(".") if label]
    if len(labels) < 2:
        return None
    if _matching_suffix(labels) is None:
        return labels[-2]
    return labels[-3]

def _matching_suffix(labels):
    if len(labels) < 3:
        return None
    candidate = ".".join(labels[-2:]).lower()
    if candidate in MULTI_PART_SUFFIXES:
        return candidate
    return None

def main():
    samples = ["http://www.google.com/search", "https://blog.openai.org/post",
               "ftp://user:pass@files.example.co.uk:21/dir", "www.CodeWars.com",
               "http://localhost:8000/app", "icann.org"]
    print(format_report(samples))

if __name__ == "__main__":
    main()

