import math


def parse_number(text):
    """Convert a text token into a float, or None if it is not a number."""
    try:
        return float(text.strip())
    except ValueError:
        return None


def parse_point(tokens):
    """Parse two tokens into an (x, y) pair, or None if either is not a number."""
    if len(tokens) != 2:
        return None
    coords = []
    for token in tokens:
        value = parse_number(token)
        if value is None:
            return None
        coords.append(value)
    return coords[0], coords[1]


def parse_circle(tokens):
    """Parse three tokens into (cx, cy, radius), or None if the spec is invalid."""
    if len(tokens) != 3:
        return None
    center = parse_point(tokens[:2])
    if center is None:
        return None
    radius = parse_number(tokens[2])
    if radius is None or radius < 0:
        return None
    return center[0], center[1], radius


def parse_query(line):
    """Parse 'px,py,cx,cy,r' into five floats, or None if the line is malformed."""
    parts = line.split(",")
    if len(parts) != 5:
        return None
    point = parse_point(parts[:2])
    if point is None:
        return None
    circle = parse_circle(parts[2:])
    if circle is None:
        return None
    return point + circle


def is_point_in_circle(px, py, cx, cy, radius):
    """True if (px, py) lies inside or on the circle centred at (cx, cy)."""
    dx = px - cx
    dy = py - cy
    return dx * dx + dy * dy <= radius * radius


def classify_point(px, py, cx, cy, radius, tolerance=1e-9):
    """Return 'inside', 'boundary' or 'outside' for the point/circle pair."""
    distance = math.hypot(px - cx, py - cy)
    if abs(distance - radius) <= tolerance:
        return "boundary"
    if distance < radius:
        return "inside"
    return "outside"


def describe(line):
    """Build a human readable result line for a query string."""
    query = parse_query(line)
    if query is None:
        return "%-24s -> invalid query" % line
    px, py, cx, cy, radius = query
    contained = is_point_in_circle(px, py, cx, cy, radius)
    return "%-24s -> %-5s (%s)" % (line, contained, classify_point(*query))


def load_circles(specs):
    """Parse circle specifications, dropping the ones that do not parse."""
    circles = []
    for spec in specs:
        circle = parse_circle(spec.split(","))
        if circle is None:
            print("skipping bad circle spec: %s" % spec)
            continue
        circles.append(circle)
    return circles


def first_containing_circle(px, py, circles):
    """Index of the first circle containing the point, or None if there is none."""
    for index, (cx, cy, radius) in enumerate(circles):
        if is_point_in_circle(px, py, cx, cy, radius):
            return index
    return None


def main():
    for line in ["1,1,0,0,2", "3,3,0,0,2", "2,0,0,0,2",
                 "-1.5,-1.5,-1,-1,1", "1,1,0,0", "a,1,0,0,2", "0,0,0,0,-3"]:
        print(describe(line))
    circles = load_circles(["0,0,2", "5,5,1", "5,5,oops"])
    for px, py in [(1, 1), (5, 5), (9, 9)]:
        index = first_containing_circle(px, py, circles)
        if index is None:
            print("(%g, %g) is outside every circle" % (px, py))
        else:
            print("(%g, %g) is in circle %d %s" % (px, py, index, circles[index]))


if __name__ == "__main__":
    main()

