from __future__ import annotations

import sys
from datetime import date, timedelta

MONTH_NAMES = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
]

HOLIDAYS = {
    2023: frozenset({date(2023, 1, 2), date(2023, 12, 25), date(2023, 12, 26)}),
    2024: frozenset({date(2024, 1, 1), date(2024, 12, 25), date(2024, 12, 26)}),
}

_CACHE: dict[tuple, int] = {}


def count_business_days(year: int, month: int, holidays=None) -> int:
    if not 1 <= month <= 12:
        raise ValueError("month must be between 1 and 12")
    frozen = None if holidays is None else frozenset(holidays)
    cached = _CACHE.get((year, month, frozen))
    if cached is not None:
        return cached
    day = date(year, month, 1)
    end = date(year + 1, 1, 1) if month == 12 else date(year, month + 1, 1)
    total = 0
    while day < end:
        if day.weekday() < 5 and (frozen is None or day not in frozen):
            total += 1
        day += timedelta(days=1)
    _CACHE[(year, month, frozen)] = total
    return total


def parse_month(token: str) -> int:
    text = token.strip().lower()
    if text.isdigit():
        return int(text)
    match = next((i + 1 for i, n in enumerate(MONTH_NAMES) if n.lower().startswith(text)), None)
    if match is None:
        raise ValueError("unrecognised month: %r" % token)
    return match


def month_report(year: int, month: int, holidays=None) -> str:
    total = count_business_days(year, month, holidays)
    line = "%-10s %d: %2d business days" % (MONTH_NAMES[month - 1], year, total)
    if holidays is not None:
        skipped = sum(1 for d in holidays
                      if d.year == year and d.month == month and d.weekday() < 5)
        if skipped:
            line += " (%d holiday(s) excluded)" % skipped
    return line


def year_summary(year: int, holidays=None) -> str:
    lines = [month_report(year, m, holidays) for m in range(1, 13)]
    total = sum(count_business_days(year, m, holidays) for m in range(1, 13))
    lines.append("%-10s %d: %3d business days" % ("TOTAL", year, total))
    return "\n".join(lines)


def main(argv=None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print("usage: business_days.py YEAR [MONTH]", file=sys.stderr)
        return 1
    try:
        year = int(argv[0])
        month = parse_month(argv[1]) if len(argv) > 1 else None
    except ValueError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 2
    holidays = HOLIDAYS.get(year)
    if month is None:
        print(year_summary(year, holidays))
    else:
        print(month_report(year, month, holidays))
    return 0


if __name__ == "__main__":
    sys.exit(main())

