def is_positive_integer(value):
    """Return True if value is an integer strictly greater than zero."""
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return value > 0
    return False


def parse_int(text):
    """Convert a string to an int, or return None when it is not numeric."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        return None


def coerce_positive_integer(value, default=None):
    """Return value as a positive int, falling back to default when invalid."""
    candidate = value
    if isinstance(candidate, str):
        candidate = parse_int(candidate)
        if candidate is None:
            return default
    if is_positive_integer(candidate):
        return candidate
    return default


def in_positive_range(value, minimum=None, maximum=None):
    """Return True if value is a positive integer inside the optional bounds."""
    if not is_positive_integer(value):
        return False
    if minimum is not None and value < minimum:
        return False
    if maximum is not None and value > maximum:
        return False
    return True


def read_limit(raw, fallback=100):
    """Interpret a configuration value as a positive limit."""
    limit = coerce_positive_integer(raw)
    if limit is None:
        return fallback
    return limit


def describe(value):
    """Build a human readable verdict for a single input."""
    label = repr(value)
    if is_positive_integer(value):
        return "{0}: positive integer".format(label)
    recovered = coerce_positive_integer(value)
    if recovered is not None:
        return "{0}: not an int, but reads as {1}".format(label, recovered)
    return "{0}: not a positive integer".format(label)


def first_positive(values):
    """Return the first positive integer in values, or None if there is none."""
    for value in values:
        if is_positive_integer(value):
            return value
    return None


def main():
    samples = [10, -5, 'abc', 0, '42', 3.0, True, None, ' 7 ']
    for sample in samples:
        print(describe(sample))

    found = first_positive(['x', -1, '9', 12])
    if found is None:
        print("no positive integer found")
    else:
        print("first positive integer: {0}".format(found))

    for raw in ['250', 'many', 0]:
        print("limit for {0!r} -> {1}".format(raw, read_limit(raw)))

    for size in [5, 500, '20', 'huge']:
        accepted = in_positive_range(coerce_positive_integer(size), maximum=100)
        print("page size {0!r} accepted: {1}".format(size, accepted))


if __name__ == '__main__':
    main()

