import datetime
from datetime import date

REFERENCE_DATE = date(2023, 10, 26)


def calculate_age(birthdate, today=None):
    """Return the age in whole years of a person born on `birthdate`."""
    if today is None:
        today = REFERENCE_DATE
    if birthdate > today:
        raise ValueError("birthdate lies in the future: %s" % birthdate.isoformat())
    age = today.year - birthdate.year
    if (today.month, today.day) < (birthdate.month, birthdate.day):
        age -= 1
    return age


def parse_birthdate(text):
    """Parse an ISO date string, returning None when it is not a valid date."""
    try:
        return datetime.datetime.strptime(text.strip(), "%Y-%m-%d").date()
    except (ValueError, AttributeError):
        return None


def next_birthday(birthdate, today=None):
    """Return the date of the next birthday on or after `today`."""
    if today is None:
        today = REFERENCE_DATE
    year = today.year
    while True:
        try:
            candidate = birthdate.replace(year=year)
        except ValueError:
            candidate = date(year, 3, 1)
        if candidate >= today:
            return candidate
        year += 1


def describe(text, today=None, label=None):
    """Build a one-line description for a birthdate given as a string."""
    birthdate = parse_birthdate(text)
    if birthdate is None:
        return "%s: unparsable date" % text
    if label is None:
        label = birthdate.isoformat()
    try:
        age = calculate_age(birthdate, today)
    except ValueError as exc:
        return "%s: %s" % (label, exc)
    upcoming = next_birthday(birthdate, today)
    days = (upcoming - (today if today is not None else REFERENCE_DATE)).days
    return "%s: age %d, turns %d in %d day(s)" % (label, age, age + 1, days)


def main():
    records = [
