import math

def calculate_dot_product(vec1, vec2):
    """Return the dot product of two 2D vectors given as (x, y) tuples."""
    return vec1[0] * vec2[0] + vec1[1] * vec2[1]

def parse_number(text):
    try:
        return float(text)
    except ValueError:
        return None

def parse_vector(text):
    """Parse "1, 2" or "(1 2)" into an (x, y) tuple, or None if malformed."""
    parts = text.strip().strip("()[]").replace(",", " ").split()
    if len(parts) != 2:
        return None
    values = []
    for part in parts:
        value = parse_number(part)
        if value is None:
            return None
        values.append(value)
    return (values[0], values[1])

def parse_pair(line):
    """Parse "1, 2 | 3, 4" into a pair of vectors, or None if malformed."""
    halves = line.split("|")
    if len(halves) != 2:
        return None
    first = parse_vector(halves[0])
    if first is None:
        return None
    second = parse_vector(halves[1])
    if second is None:
        return None
    return (first, second)

def angle_between(vec1, vec2):
    """Angle in degrees between the vectors, or None if one has zero length."""
    norms = calculate_dot_product(vec1, vec1) * calculate_dot_product(vec2, vec2)
    if norms == 0:
        return None
    cosine = calculate_dot_product(vec1, vec2) / math.sqrt(norms)
    return math.degrees(math.acos(max(-1.0, min(1.0, cosine))))

def relationship(vec1, vec2):
    if calculate_dot_product(vec1, vec2) == 0:
        return "perpendicular"
    if vec1[0] * vec2[1] - vec1[1] * vec2[0] == 0:
        return "parallel"
    return None

def describe(vec1, vec2):
    product = calculate_dot_product(vec1, vec2)
    lines = ["{0} . {1} = {2:g}".format(vec1, vec2, product)]
    angle = angle_between(vec1, vec2)
    if angle is None:
        lines.append("  angle: undefined (zero-length vector involved)")
    else:
        lines.append("  angle: {0:.4g} degrees".format(angle))
        relation = relationship(vec1, vec2)
        if relation is not None:
            lines.append("  the vectors are " + relation)
    return "\n".join(lines)

def report_line(line):
    pair = parse_pair(line)
    if pair is None:
        return "could not parse: {0!r}".format(line)
    return describe(pair[0], pair[1])

def main():
    print(describe((1, 2), (3, 4)))
    print(describe((0, 5), (10, 0)))
    for line in ["(-1.5, 4) | 2 2", "0 0 | 5 5", "3;4 | 1 1", "1 2"]:
        print(report_line(line))

if __name__ == "__main__":
    main()

