def enqueue(queue, item):
    """Append item to the end of queue."""
    queue.append(item)


def dequeue(queue):
    """Remove and return the first item, or None if the queue is empty."""
    if not queue:
        return None
    return queue.pop(0)


def peek(queue):
    """Return the first item without removing it, or None if empty."""
    if not queue:
        return None
    return queue[0]


def drain(queue):
    """Dequeue everything, returning the items in the order they left."""
    items = []
    item = dequeue(queue)
    while item is not None:
        items.append(item)
        item = dequeue(queue)
    return items


def parse_command(line):
    """Turn a text command into a (name, argument) pair, or None if unusable."""
    parts = line.split()
    if not parts:
        return None
    name = parts[0].lower()
    if name == "enqueue":
        if len(parts) != 2:
            return None
        return (name, parts[1])
    if name in ("dequeue", "peek", "drain"):
        return (name, None)
    return None


def run_commands(queue, lines):
    """Apply a sequence of text commands, collecting a report line for each."""
    report = []
    for line in lines:
        command = parse_command(line)
        if command is None:
            report.append("ignored: %s" % line.strip())
            continue
        name, argument = command
        if argument is not None:
            enqueue(queue, argument)
            report.append("enqueued %s" % argument)
        elif name == "dequeue":
            item = dequeue(queue)
            if item is None:
                report.append("dequeue from empty queue")
            else:
                report.append("dequeued %s" % item)
        elif name == "peek":
            front = peek(queue)
            report.append("front is %s" % ("nothing" if front is None else front))
        else:
            report.append("drained %s" % ", ".join(drain(queue)))
    return report


def main():
    script = [
        "enqueue apple",
        "enqueue pear",
        "peek",
        "dequeue",
        "enqueue plum",
        "wobble",
        "enqueue",
        "drain",
        "dequeue",
    ]
    queue = []
    for entry in run_commands(queue, script):
        print(entry)
    print("final queue: %r" % (queue,))


if __name__ == "__main__":
    main()

