import sys


def square_error(matrix):
    """Return a message describing why matrix is not square, or None if it is."""
    if not isinstance(matrix, list) or not matrix:
        return "matrix must be a non-empty list of rows"
    size = len(matrix)
    for row in matrix:
        if not isinstance(row, list) or len(row) != size:
            return "matrix must be square, got a row of length %d" % len(row)
    return None


def parse_int(token):
    """Return the integer value of token, or None when it is not an integer."""
    try:
        return int(token)
    except ValueError:
        return None


def parse_matrix(text):
    """Parse "1 2; 3 4" into [[1, 2], [3, 4]]; return None if the text is bad."""
    rows = []
    for chunk in text.split(";"):
        row = []
        for token in chunk.split():
            value = parse_int(token)
            if value == None:
                return None
            row.append(value)
        if not row:
            return None
        rows.append(row)
    if square_error(rows) != None:
        return None
    return rows


def rotate_matrix_90_clockwise(matrix):
    """Rotate a square matrix 90 degrees clockwise in place and return it."""
    problem = square_error(matrix)
    if problem != None:
        raise ValueError(problem)
    size = len(matrix)
    for layer in range(size // 2):
        last = size - 1 - layer
        for offset in range(layer, last):
            shift = offset - layer
            saved = matrix[layer][offset]
            matrix[layer][offset] = matrix[last - shift][layer]
            matrix[last - shift][layer] = matrix[last][last - shift]
            matrix[last][last - shift] = matrix[offset][last]
            matrix[offset][last] = saved
    return matrix


def format_matrix(matrix, width=None):
    """Render a matrix as aligned text rows joined by newlines."""
    if width == None:
        width = max(len(str(value)) for row in matrix for value in row)
    return "\n".join(" ".join(str(v).rjust(width) for v in row) for row in matrix)


def main(argv=None):
    if argv == None:
        argv = sys.argv[1:]
    sources = argv if argv else ["1 2; 3 4", "1 2 3; 4 5 6; 7 8 9"]
    status = 0
    for text in sources:
        matrix = parse_matrix(text)
        if matrix == None:
            print("skipping invalid matrix: %r" % text, file=sys.stderr)
            status = 1
            continue
        print("input:")
        print(format_matrix(matrix))
        print("rotated 90 degrees clockwise:")
        print(format_matrix(rotate_matrix_90_clockwise(matrix)))
        print()
    return status


if __name__ == "__main__":
    sys.exit(main())

