    return values


def resolve_exclusion(count, num_to_exclude):
    """Translate the request into a concrete trim; None means trim 10% from each end."""
    if num_to_exclude is None:
        return max(1, count // 10)
    return num_to_exclude


def trimmed_values(numbers, num_to_exclude):
    """Return the sorted values left after trimming both ends, or None if nothing remains."""
    trim = resolve_exclusion(len(numbers), num_to_exclude)
    if trim < 0:
        return None
    if len(numbers) - 2 * trim <= 0:
        return None
    ordered = sorted(numbers)
    if trim == 0:
        return ordered
    return ordered[trim:-trim]


def calculate_average_no_outliers(numbers, num_to_exclude):
    kept = trimmed_values(numbers, num_to_exclude)
    if kept is None:
        return 0.0
    return sum(kept) / len(kept)


def summarize(numbers, num_to_exclude):
    """Build a summary dict; 'low' and 'high' are None when everything was trimmed."""
    trim = resolve_exclusion(len(numbers), num_to_exclude)
    kept = trimmed_values(numbers, num_to_exclude)
    summary = {
        "mode": "auto" if num_to_exclude is None else "fixed",
        "count": len(numbers),
        "excluded": max(trim, 0) * 2,
        "average": calculate_average_no_outliers(numbers, num_to_exclude),
        "low": None,
        "high": None,
    }
    if kept is not None:
        summary["low"] = kept[0]
        summary["high"] = kept[-1]
    return summary


def format_report(label, summary):
    line = "%s [%s]: n=%d, trimmed=%d, mean=%.4f" % (
        label,
        summary["mode"],
        summary["count"],
        summary["excluded"],
        summary["average"],
    )
    low = summary["low"]
    if low is None:
        return line + ", range=empty"
    return line + ", range=[%g, %g]" % (low, summary["high"])


