def calculate_hamming_distance(s1, s2):
    """Number of positions at which the corresponding characters differ."""
    problem = validate_pair(s1, s2)
    if problem is not None:
        raise ValueError(problem)
    return sum(1 for a, b in zip(s1, s2) if a != b)


def validate_pair(s1, s2):
    """Return a description of the first problem found, or None if the pair is fine."""
    if s1 is None:
        return "first string must be provided"
    if s2 is None:
        return "second string must be provided"
    if not isinstance(s1, str) or not isinstance(s2, str):
        return "both inputs must be strings"
    if len(s1) != len(s2):
        return "strings must have equal length (%d != %d)" % (len(s1), len(s2))
    return None


def mismatch_positions(s1, s2):
    """Indices where the two strings differ, or None when they cannot be compared."""
    if validate_pair(s1, s2) is not None:
        return None
    return [i for i, (a, b) in enumerate(zip(s1, s2)) if a != b]


def parse_pair(line):
    """Parse 'word1,word2' into a tuple, or None when the line holds no pair."""
    stripped = line.strip()
    if not stripped or stripped.startswith("#"):
        return None
    parts = stripped.split(",")
    if len(parts) != 2:
        return None
    return parts[0].strip(), parts[1].strip()


def format_report(s1, s2):
    """One human readable line describing the comparison of two strings."""
    problem = validate_pair(s1, s2)
    if problem is not None:
        return "%r vs %r: skipped (%s)" % (s1, s2, problem)
    distance = calculate_hamming_distance(s1, s2)
    positions = mismatch_positions(s1, s2)
    if not positions:
        return "%s vs %s: distance 0 (identical)" % (s1, s2)
    listed = ", ".join(str(p) for p in positions)
    return "%s vs %s: distance %d at positions %s" % (s1, s2, distance, listed)


def report_lines(lines):
    """Turn raw input lines into report strings, ignoring blanks and comments."""
    reports = []
    for line in lines:
        pair = parse_pair(line)
        if pair is None:
            continue
        reports.append(format_report(pair[0], pair[1]))
    return reports


def main():
    data = [
        "karolin,kathrin",
        "python,python",
        "# malformed rows are ignored",
        "",
        "abc,abcd",
        "1011101,1001001",
    ]
    for report in report_lines(data):
        print(report)


if __name__ == "__main__":
    main()

