WHITESPACE = " \t\n\r"


def normalize(text, extra_ignored=None):
    """Lower-case `text` and drop spaces plus any extra ignored characters."""
    if not isinstance(text, str):
        raise TypeError("expected a string, got %r" % (type(text).__name__,))
    ignored = set(WHITESPACE)
    if extra_ignored is not None:
        ignored.update(extra_ignored)
    return "".join(ch for ch in text.lower() if ch not in ignored)


def signature(text, extra_ignored=None):
    """A canonical form: sorted letters of the normalized text."""
    return "".join(sorted(normalize(text, extra_ignored)))


def are_anagrams(s1, s2):
    """True when s1 and s2 use the same characters, ignoring case and spaces."""
    if s1 is None:
        return False
    if s2 is None:
        return False
    return signature(s1) == signature(s2)


def find_anagram_groups(words, extra_ignored=None):
    """Map each signature to the list of words sharing it."""
    groups = {}
    for word in words:
        if word is None:
            continue
        key = signature(word, extra_ignored)
        bucket = groups.get(key)
        if bucket is None:
            bucket = []
            groups[key] = bucket
        bucket.append(word)
    return groups


def first_anagram_of(word, candidates):
    """Return the first candidate that is an anagram of `word`, else None."""
    for candidate in candidates:
        if are_anagrams(word, candidate):
            return candidate
    return None


def describe_pair(s1, s2):
    verdict = "anagrams" if are_anagrams(s1, s2) else "not anagrams"
    return "%-18s %-18s %s" % (repr(s1), repr(s2), verdict)


