def convert_token(token):
    """Turn a single textual item into an int, a float, or a plain string."""
    text = token.strip()
    if text.startswith(("'", '"')) and text.endswith(("'", '"')) and len(text) >= 2:
        return text[1:-1]
    for converter in (int, float):
        try:
            return converter(text)
        except ValueError:
            continue
    return text


def parse_list(text):
    """Parse "[1, 2, 3]" into a Python list, or return None if it is malformed."""
    if text is None:
        return None
    body = text.strip()
    if body.startswith("[") and body.endswith("]"):
        body = body[1:-1]
    body = body.strip()
    if not body:
        return []
    items = []
    for token in body.split(","):
        if not token.strip():
            return None
        items.append(convert_token(token))
    return items


def find_common_elements(list1, list2):
    """Return the elements present in both lists, without duplicates."""
    if list1 is None:
        raise TypeError("find_common_elements() requires a first list")
    if list2 is None:
        raise TypeError("find_common_elements() requires a second list")
    others = set(list2)
    common = []
    added = set()
    for item in list1:
        if item in others and item not in added:
            added.add(item)
            common.append(item)
    return common


def describe(common, label=None):
    """Build a one-line report for a computed intersection."""
    name = "pair" if label is None else label
    if not common:
        return "%s: no common elements" % name
    rendered = ", ".join(repr(item) for item in common)
    return "%s: %d common element(s) -> [%s]" % (name, len(common), rendered)


def compare_text_lists(text1, text2, label=None):
    """Parse two textual lists and report their common elements."""
    first = parse_list(text1)
    if first is None:
        return "could not parse input: %r" % text1
    second = parse_list(text2)
    if second is None:
        return "could not parse input: %r" % text2
    return describe(find_common_elements(first, second), label)


