    if not isinstance(nested_list, (list, tuple)):
        raise TypeError("nested_list must be a list or tuple")
    flat = []
    for item in nested_list:
        if isinstance(item, (list, tuple)):
            flat.extend(flatten_list(item))
        else:
            flat.append(item)
    return flat


