    """Parse a literal like "[1, [2, 3]]" into a list, or None if invalid."""
    try:
        value = ast.literal_eval(text.strip())
    except (ValueError, SyntaxError):
        return None
    if isinstance(value, (list, tuple)):
        return value
    return None


def first_scalar(value):
    """Return the first non-list element, or None if there is none."""
    if not isinstance(value, (list, tuple)):
        return value
    for item in value:
        found = first_scalar(item)
        if found is not None:
            return found
    return None


def depth_of(value):
    """Return the nesting depth of a value (0 for a plain scalar)."""
    if not isinstance(value, (list, tuple)):
        return 0
    inner = 0
    for item in value:
