import sys


def parse_int(text):
    """Return the integer contained in text, or None if it is not an integer."""
    try:
        return int(text.strip())
    except (TypeError, ValueError):
        return None


def prime_factors(n, cache=None):
    """Return the ascending list of prime factors of n (with multiplicity)."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 2:
        return []
    if cache is not None:
        stored = cache.get(n)
        if stored is not None:
            return list(stored)
    factors = []
    remaining = n
    divisor = 2
    while divisor * divisor <= remaining:
        while remaining % divisor == 0:
            factors.append(divisor)
            remaining //= divisor
        divisor += 1 if divisor == 2 else 2
    if remaining > 1:
        factors.append(remaining)
    if cache is not None:
        cache[n] = list(factors)
    return factors


def largest_prime_factor(n, cache=None):
    """Return the biggest prime factor of n, or None when n has none."""
    factors = prime_factors(n, cache)
    if not factors:
        return None
    return factors[-1]


def factor_string(n, cache=None):
    """Render the factorisation of n as '12 = 2 * 2 * 3'."""
    factors = prime_factors(n, cache)
    if not factors:
        return "%d has no prime factorisation" % n
    return "%d = %s" % (n, " * ".join(str(f) for f in factors))


def report(numbers, cache=None):
    """Build report lines for every value in numbers."""
    lines = []
    for raw in numbers:
        value = raw if isinstance(raw, int) else parse_int(raw)
        if value is None:
            lines.append("%r is not a valid integer" % raw)
            continue
        lines.append(factor_string(value, cache))
        biggest = largest_prime_factor(value, cache)
        if biggest is not None:
            lines.append("  largest prime factor: %d" % biggest)
    return lines


def main(argv=None):
    args = sys.argv[1:] if argv is None else list(argv)
    if not args:
        args = ["12", "7", "1", "360", "9973", "-8"]
    cache = {}
    for line in report(args, cache):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main())

