from collections import deque


class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right


def build_tree(level_order):
    """Build a binary tree from a level-order list where None marks a missing child."""
    if not level_order:
        return None
    if level_order[0] is None:
        return None
    root = Node(level_order[0])
    pending = deque([root])
    index = 1
    while pending and index < len(level_order):
        current = pending.popleft()
        if index < len(level_order):
            value = level_order[index]
            index += 1
            if value is not None:
                current.left = Node(value)
                pending.append(current.left)
        if index < len(level_order):
            value = level_order[index]
            index += 1
            if value is not None:
                current.right = Node(value)
                pending.append(current.right)
    return root


def _are_mirrors(left, right):
    if left is None:
        return right is None
    if right is None:
        return False
    if left.value != right.value:
        return False
    return _are_mirrors(left.left, right.right) and _are_mirrors(left.right, right.left)


def is_symmetric(root):
    """Return True if the tree rooted at `root` is a mirror image of itself."""
    if root is None:
        return True
    return _are_mirrors(root.left, root.right)


def to_level_order(root):
    """Serialize a tree back to a level-order list, trimming trailing gaps."""
    values = []
    pending = deque([root])
    while pending:
        node = pending.popleft()
        if node is None:
            values.append(None)
            continue
        values.append(node.value)
        pending.append(node.left)
        pending.append(node.right)
    while values and values[-1] is None:
        values.pop()
    return values


def format_node(value):
    return "null" if value is None else str(value)


def describe(level_order):
    root = build_tree(level_order)
    if root is None:
        label = "empty"
    else:
        label = ",".join(format_node(v) for v in to_level_order(root))
    return "{0:<24} -> {1}".format(label, is_symmetric(root))


def main():
    cases = [
        [1, 2, 2, 3, 4, 4, 3],
        [1, 2, 2, None, 3, None, 3],
        [1, 2, 2],
        [],
        [1],
        [1, 2, 2, 3, None, None, 3],
    ]
    for case in cases:
        print(describe(case))


if __name__ == "__main__":
    main()

