import re
import sys

TOKEN_RE = re.compile(r"[a-z0-9']+")


def normalize(text):
    """Lowercase the text, drop punctuation and return the remaining words."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    words = []
    for raw in TOKEN_RE.findall(text.lower()):
        word = raw.strip("'")
        if word:
            words.append(word)
    return words


def word_counts(text):
    """Count occurrences of each word, ignoring case and punctuation."""
    counts = {}
    for word in normalize(text):
        current = counts.get(word)
        if current is None:
            counts[word] = 1
        else:
            counts[word] = current + 1
    return counts


def most_common(counts, limit=None):
    """Return (word, count) pairs by descending count, then alphabetically."""
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    if limit is not None:
        ordered = ordered[:limit]
    return ordered


def read_text(path=None):
    """Read text from a file, or from standard input when no path is given."""
    if path is None:
        return sys.stdin.read()
    with open(path, encoding="utf-8") as handle:
        return handle.read()


def parse_limit(argv):
    """Return the optional limit argument, or None when it was not supplied."""
    if len(argv) < 3:
        return None
    limit = int(argv[2])
    if limit <= 0:
        raise ValueError("limit must be positive")
    return limit


def main(argv):
    path = argv[1] if len(argv) > 1 else None
    label = "stdin" if path is None else path
    limit = parse_limit(argv)
    counts = word_counts(read_text(path))
    rows = most_common(counts, limit)
    if limit is not None:
        print("top {0} words in {1}:".format(limit, label))
    else:
        print("all {0} words in {1}:".format(len(rows), label))
    width = max((len(row[0]) for row in rows), default=0)
    for word, count in rows:
        print("{0:<{1}}  {2}".format(word, width, count))
    print("total {0} words, {1} distinct".format(sum(counts.values()), len(counts)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

