def normalize_interval(interval):
    """Return the interval as an ordered (low, high) tuple, or None if invalid."""
    if interval is None:
        return None
    if len(interval) != 2:
        return None
    low, high = interval
    if low is None:
        return None
    if high is None:
        return None
    if low > high:
        return (high, low)
    return (low, high)


def interval_intersection(interval1, interval2):
    """Intersect two closed intervals, returning (start, end) or None."""
    first = normalize_interval(interval1)
    if first is None:
        return None
    second = normalize_interval(interval2)
    if second is None:
        return None
    start = max(first[0], second[0])
    end = min(first[1], second[1])
    if start > end:
        return None
    return (start, end)


def intersect_all(intervals):
    """Intersect a sequence of closed intervals; None if they share no point."""
    result = None
    for index, interval in enumerate(intervals):
        if index == 0:
            result = normalize_interval(interval)
        else:
            result = interval_intersection(result, interval)
        if result is None:
            return None
    return result


def format_interval(interval):
    """Render an interval (or the empty result) for display."""
    if interval is None:
        return "empty"
    start, end = interval
    if start == end:
        return "[{0}]".format(start)
    return "[{0}, {1}]".format(start, end)


def measure(interval):
    """Length of a closed interval, or None when there is nothing to measure."""
    if interval is None:
        return None
    return interval[1] - interval[0]


def main():
    pairs = [
        ((1, 5), (3, 7)),
        ((1, 2), (3, 4)),
        ((0, 10), (10, 20)),
        ((8, 3), (4, 6)),
        ((1, 4), None),
    ]
    for left, right in pairs:
        overlap = interval_intersection(left, right)
        size = measure(overlap)
        line = "{0} & {1} -> {2}".format(left, right, format_interval(overlap))
        if size is not None:
            line += " (length {0})".format(size)
        print(line)

    chain = [(0, 100), (10, 60), (25, 40), (30, 35)]
    common = intersect_all(chain)
    print("common of {0}: {1}".format(chain, format_interval(common)))
    if common is not None:
        print("midpoint: {0}".format((common[0] + common[1]) / 2))


if __name__ == "__main__":
    main()

