INFINITY_LABEL = "-inf"


def validate_nums(nums):
    """Return the length of a usable list of numbers, or raise ValueError."""
    if nums is None:
        raise ValueError("nums must be a list, not None")
    if len(nums) == 0:
        raise ValueError("nums must contain at least one element")
    for index, value in enumerate(nums):
        if value is None:
            raise ValueError("nums[%d] is None; numbers are required" % index)
    return len(nums)


def find_peak_element(nums):
    """Binary search for an index whose value is greater than its neighbours."""
    size = validate_nums(nums)
    lo, hi = 0, size - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    return lo


def neighbours(nums, index):
    """Return the values around index, using None for the virtual -infinity ends."""
    left = nums[index - 1] if index > 0 else None
    right = nums[index + 1] if index + 1 < len(nums) else None
    return left, right


def is_peak(nums, index):
    left, right = neighbours(nums, index)
    if left is not None and left >= nums[index]:
        return False
    if right is not None and right >= nums[index]:
        return False
    return True


def all_peaks(nums):
    validate_nums(nums)
    return [i for i in range(len(nums)) if is_peak(nums, i)]


def describe_peak(nums, index):
    left, right = neighbours(nums, index)
    left_text = INFINITY_LABEL if left is None else str(left)
    right_text = INFINITY_LABEL if right is None else str(right)
    return "index %d: %s < %s > %s" % (index, left_text, nums[index], right_text)


def report(nums, label=None):
    heading = "nums" if label is None else label
    peak = find_peak_element(nums)
    lines = ["%s = %r" % (heading, nums), "  found %s" % describe_peak(nums, peak)]
    others = [i for i in all_peaks(nums) if i != peak]
    if others:
        lines.append("  other peaks: %s" % ", ".join(str(i) for i in others))
    return "\n".join(lines)


def main():
    samples = [
        ([1, 2, 3, 1], "example 1"),
        ([1, 2, 1, 3, 5, 6, 4], "example 2"),
        ([7], None),
        ([5, 4, 3, 2, 1], "strictly decreasing"),
    ]
    for nums, label in samples:
        print(report(nums, label))
    try:
        find_peak_element(None)
    except ValueError as error:
        print("rejected: %s" % error)


if __name__ == "__main__":
    main()

