import math
from typing import List, Optional, Sequence, Tuple


def parse_side(text: str) -> Optional[float]:
    """Convert a textual side length to a float, or None if unusable."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return float(stripped)
    except ValueError:
        return None


def parse_pair(line: str) -> Optional[Tuple[float, float]]:
    """Parse an 'a,b' or 'a b' line into a tuple of floats, or None."""
    parts = line.replace(",", " ").split()
    if len(parts) != 2:
        return None
    first = parse_side(parts[0])
    if first is None:
        return None
    second = parse_side(parts[1])
    if second is None:
        return None
    return first, second


def calculate_hypotenuse(side1: float, side2: float) -> float:
    """Return the hypotenuse of a right triangle with legs side1 and side2."""
    a = float(side1)
    b = float(side2)
    if a <= 0 or b <= 0:
        raise ValueError("side lengths must be positive")
    return math.hypot(a, b)


def describe(side1: float, side2: float, precision: Optional[int] = None) -> str:
    """Format a one-line report for a pair of legs."""
    if precision is None:
        precision = 4
    try:
        hyp = calculate_hypotenuse(side1, side2)
    except ValueError as exc:
        return "legs %g and %g rejected: %s" % (side1, side2, exc)
    label = "right isosceles" if math.isclose(side1, side2) else "scalene"
    return "legs %g and %g -> hypotenuse %.*f (%s)" % (
        side1, side2, precision, hyp, label)


def largest_hypotenuse(lines: Sequence[str]) -> Optional[float]:
    """Longest hypotenuse among the valid lines, or None if there is none."""
    largest = None
    for line in lines:
        pair = parse_pair(line)
        if pair is None:
            continue
        try:
            hyp = calculate_hypotenuse(pair[0], pair[1])
        except ValueError:
            continue
        if largest is None or hyp > largest:
            largest = hyp
    return largest


def report(lines: Sequence[str], precision: Optional[int] = None) -> List[str]:
    """Turn raw input lines into report strings, flagging unparsable ones."""
    out = []
    for line in lines:
        pair = parse_pair(line)
        if pair is None:
            out.append("could not read %r" % line.strip())
        else:
            out.append(describe(pair[0], pair[1], precision))
    biggest = largest_hypotenuse(lines)
    if biggest is not None:
        out.append("largest hypotenuse: %.4f" % biggest)
    return out


def main() -> None:
    samples = ["3 4", "5,12", "1 1", "8 15", "-2 7", "hello 4", "   "]
    for line in report(samples, precision=2):
        print(line)


if __name__ == "__main__":
    main()

