def count_uppercase(text: str) -> int:
    if text is None:
        raise TypeError("text must be a string, not None")
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    total = 0
    for char in text:
        if char.isupper():
            total += 1
    return total


def first_uppercase_index(text: str):
    """Return the index of the first uppercase letter, or None if there is none."""
    for index, char in enumerate(text):
        if char.isupper():
            return index
    return None


def uppercase_ratio(text: str):
    """Fraction of characters that are uppercase, or None for an empty string."""
    if not text:
        return None
    return count_uppercase(text) / len(text)


def describe(text: str) -> str:
    count = count_uppercase(text)
    position = first_uppercase_index(text)
    ratio = uppercase_ratio(text)
    parts = ["{!r}: {} uppercase letter(s)".format(text, count)]
    if position is not None:
        parts.append("first at index {}".format(position))
    if ratio is not None:
        parts.append("ratio {:.2f}".format(ratio))
    else:
        parts.append("empty input")
    return ", ".join(parts)


def load_lines(path):
    """Read sample lines from a file, or return None if the path is unusable."""
    if path is None:
        return None
    try:
        with open(path, encoding="utf-8") as handle:
            return [line.rstrip("\n") for line in handle]
    except OSError:
        return None


def main(argv=None):
    import sys

    args = sys.argv[1:] if argv is None else argv
    path = args[0] if args else None
    samples = load_lines(path)
    if samples is None:
        if path is not None:
            print("Could not read {!r}; using built-in samples.".format(path))
        samples = ["Hello World", "python", "ALL CAPS HERE", ""]

    grand_total = 0
    busiest = None
    for text in samples:
        print(describe(text))
        count = count_uppercase(text)
        grand_total += count
        if busiest is None or count > count_uppercase(busiest):
            busiest = text
    print("Total uppercase letters: {}".format(grand_total))
    if busiest is not None:
        print("Most uppercase in: {!r}".format(busiest))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

