        parts.append("ratio {:.2f}".format(ratio))
    else:
        parts.append("empty input")
    return ", ".join(parts)


def load_lines(path):
    """Read sample lines from a file, or return None if the path is unusable."""
    if path == None:
        return None
    try:
        with open(path, encoding="utf-8") as handle:
            return [line.rstrip("\n") for line in handle]
    except OSError:
        return None


def main(argv=None):
    import sys

    args = sys.argv[1:] if argv == None else argv
    path = args[0] if args else None
    samples = load_lines(path)
    if samples == None:
        if path != None:
            print("Could not read {!r}; using built-in samples.".format(path))
        samples = ["Hello World", "python", "ALL CAPS HERE", ""]

    grand_total = 0
    busiest = None
    for text in samples:
        print(describe(text))
        count = count_uppercase(text)
        grand_total += count
        if busiest == None or count > count_uppercase(busiest):
            busiest = text
    print("Total uppercase letters: {}".format(grand_total))
    if busiest != None:
        print("Most uppercase in: {!r}".format(busiest))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

