VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100}
ALLOWED_PAIRS = {'IV', 'IX', 'XL', 'XC'}


def symbol_value(symbol: str):
    """Return the integer value of a single Roman symbol, or None if unknown."""
    return VALUES.get(symbol)


def normalize(raw):
    """Strip and upper-case an input token; None for empty or non-string input."""
    if raw is None:
        return None
    if not isinstance(raw, str):
        return None
    cleaned = raw.strip().upper()
    if cleaned == '':
        return None
    return cleaned


def roman_to_int(roman_str: str) -> int:
    text = normalize(roman_str)
    if text is None:
        raise ValueError('roman numeral must be a non-empty string')
    total = 0
    index = 0
    while index < len(text):
        current = symbol_value(text[index])
        if current is None:
            raise ValueError('invalid Roman symbol: %r' % text[index])
        following = symbol_value(text[index + 1]) if index + 1 < len(text) else None
        if following is not None and following > current:
            pair = text[index:index + 2]
            if pair not in ALLOWED_PAIRS:
                raise ValueError('unsupported subtractive pair: %s' % pair)
            total += following - current
            index += 2
        else:
            total += current
            index += 1
    return total


def try_convert(raw):
    """Convert if possible, returning None when the token is not a valid numeral."""
    text = normalize(raw)
    if text is None:
        return None
    try:
        return roman_to_int(text)
    except ValueError:
        return None


def describe(raw):
    value = try_convert(raw)
    label = normalize(raw)
    if label is None:
        return '<empty>          -> rejected (no numeral given)'
    if value is None:
        return '%-16s -> rejected (not a supported numeral)' % label
    return '%-16s -> %d' % (label, value)


def main():
    samples = ['VI', 'IX', 'xxiv', ' LXXVIII ', 'XCIX', 'CCC', '', 'MM', 'IIX', None]
    report = [describe(sample) for sample in samples]
    for line in report:
        print(line)
    numbers = [try_convert(sample) for sample in samples]
    valid = [n for n in numbers if n is not None]
    print('converted %d of %d samples' % (len(valid), len(samples)))
    if valid:
        print('largest value: %d' % max(valid))


if __name__ == '__main__':
    main()

