            problems.append(f"line {number}: {name!r} was not in stock, set to 0")
        update_inventory(inventory, name, change)
    return problems


def format_report(inventory: dict[str, int], title: str | None = None) -> str:
    """Render the inventory as aligned rows, optionally under a title."""
    rows = []
    if title != None:
        rows.append(title)
    for key in sorted(inventory):
        rows.append(f"{key:<10} {inventory[key]:>4}")
    return "\n".join(rows)


