from typing import List, Optional, Tuple
import sys


def _isqrt(n: int) -> int:
    """Floor of the square root of a non-negative integer."""
    if n < 2:
        return n
    guess = 1 << ((n.bit_length() + 1) // 2)
    while True:
        nxt = (guess + n // guess) // 2
        if nxt >= guess:
            return guess
        guess = nxt


def parse_candidate(text: str) -> Optional[int]:
    """Convert user input to a non-negative integer, or None if unusable."""
    stripped = text.strip()
    try:
        value = int(stripped)
    except ValueError:
        return None
    if value < 0:
        return None
    return value


def parse_range(text: str) -> Optional[Tuple[int, int]]:
    """Parse "low..high" into a pair of bounds, or None if that fails."""
    parts = text.split("..")
    if len(parts) != 2:
        return None
    low = parse_candidate(parts[0])
    if low is None:
        return None
    high = parse_candidate(parts[1])
    if high is None:
        return None
    if high < low:
        return None
    return low, high


def is_perfect_square(n: int) -> bool:
    """Return True if the non-negative integer n is a perfect square."""
    if n < 0:
        raise ValueError("n must be non-negative")
    root = _isqrt(n)
    return root * root == n


def exact_root(n: int) -> Optional[int]:
    """Return the integer square root of n, or None if n is not a square."""
    if n < 0:
        return None
    root = _isqrt(n)
    if root * root != n:
        return None
    return root


def describe(n: int) -> str:
    root = exact_root(n)
    if root is not None:
        return "{0} is a perfect square ({1} * {1})".format(n, root)
    lower = _isqrt(n)
    return "{0} is not a perfect square (between {1}^2 and {2}^2)".format(
        n, lower, lower + 1
    )


def squares_between(low: int, high: int) -> List[int]:
    """All perfect squares in the inclusive range [low, high]."""
    start = _isqrt(low)
    if start * start < low:
        start += 1
    return [k * k for k in range(start, _isqrt(high) + 1)]


def report(inputs: List[str]) -> List[str]:
    lines = []
    for raw in inputs:
        bounds = parse_range(raw)
        if bounds is not None:
            low, high = bounds
            lines.append("squares in [{0}, {1}]: {2}".format(
                low, high, squares_between(low, high)))
            continue
        value = parse_candidate(raw)
        if value is None:
            lines.append("skipping {0!r}: not a non-negative integer".format(raw))
            continue
        lines.append(describe(value))
    return lines


def main(argv: List[str]) -> int:
    arguments = argv[1:]
    if not arguments:
        arguments = ["9", "10", "0", "144", "-3", "two", "10..200"]
    for line in report(arguments):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

