def parse_key_value_string(data_str: str) -> dict[str, str]:
    """Parse 'key1=value1;key2=value2' into a dictionary of strings."""
    if data_str is None:
        raise TypeError("data_str must be a string, not None")
    result: dict[str, str] = {}
    for chunk in data_str.split(';'):
        if not chunk.strip():
            continue
        key, sep, value = chunk.partition('=')
        if not sep:
            raise ValueError(f"missing '=' in segment: {chunk!r}")
        result[key.strip()] = value.strip()
    return result


def get_value(config: dict[str, str], key: str, default: str | None = None) -> str | None:
    """Look up a key, returning default (possibly None) when it is absent."""
    value = config.get(key)
    if value is None:
        return default
    return value


def get_int(config: dict[str, str], key: str) -> int | None:
    """Return the value of key as an int, or None if absent or not numeric."""
    raw = get_value(config, key)
    if raw is None:
        return None
    try:
        return int(raw)
    except ValueError:
        return None


def merge_settings(base: dict[str, str], override_str: str | None) -> dict[str, str]:
    """Overlay a second key/value string on top of an existing dictionary."""
    merged = dict(base)
    if override_str is not None:
        merged.update(parse_key_value_string(override_str))
    return merged


def format_config(config: dict[str, str], keys: list[str] | None = None) -> str:
    """Render a config back to 'k=v;k=v', optionally restricted to given keys."""
    if keys is None:
        keys = sorted(config)
    parts = []
    for key in keys:
        value = get_value(config, key)
        if value is not None:
            parts.append(f"{key}={value}")
    return ';'.join(parts)


def describe(config: dict[str, str]) -> str:
    """Build a human-readable summary of a parsed configuration."""
    name = get_value(config, 'name', 'unknown')
    age = get_int(config, 'age')
    city = get_value(config, 'city')
    lines = [f"name: {name}"]
    if age is None:
        lines.append("age: not provided")
    else:
        lines.append(f"age: {age} ({'adult' if age >= 18 else 'minor'})")
    if city is not None:
        lines.append(f"city: {city}")
    return '\n'.join(lines)


def main() -> None:
    samples = ['name=Alice;age=30', 'city=London', 'name=Bob;age=x;city=Paris']
    overrides = ['city=Berlin', None, 'age=17']
    for raw, override in zip(samples, overrides):
        config = parse_key_value_string(raw)
        print(f"input:  {raw}")
        print(f"parsed: {config}")
        final = merge_settings(config, override)
        print(f"final:  {format_config(final)}")
        print(describe(final))
        print('-' * 30)


if __name__ == '__main__':
    main()

