import sys

_CACHE: dict[str, str] = {}


def validate_sequence(letters: list[str]) -> None:
    """Reject inputs that cannot describe a gapped run of lowercase letters."""
    if letters is None:
        raise ValueError("no sequence given")
    if len(letters) < 2:
        raise ValueError("need at least two letters to detect a gap")
    for item in letters:
        if item is None:
            raise ValueError("sequence contains a missing entry")
        if len(item) != 1 or not ("a" <= item <= "z"):
            raise ValueError(f"not a lowercase letter: {item!r}")


def find_missing_letter(letters: list[str]) -> str:
    """Return the single letter absent from an otherwise consecutive run."""
    validate_sequence(letters)
    key = "".join(letters)
    cached = _CACHE.get(key)
    if cached is not None:
        return cached
    missing = None
    for left, right in zip(letters, letters[1:]):
        step = ord(right) - ord(left)
        if step == 2 and missing is None:
            missing = chr(ord(left) + 1)
        elif step != 1:
            raise ValueError(f"bad step between {left!r} and {right!r}")
    if missing is None:
        raise ValueError("no letter is missing from the sequence")
    _CACHE[key] = missing
    return missing


def parse_sequence(text: str | None) -> list[str]:
    """Turn 'a,b,d,e' or 'abde' into a list of single letters."""
    if text is None:
        raise ValueError("nothing to parse")
    cleaned = text.strip()
    if "," in cleaned:
        parts = [piece.strip() for piece in cleaned.split(",")]
    else:
        parts = list(cleaned.replace(" ", ""))
    return [part for part in parts if part]


def format_report(letters: list[str], missing: str | None = None) -> str:
    if missing is None:
        missing = find_missing_letter(letters)
    shown = "".join(letters)
    return f"{shown} -> missing {missing!r} (between {chr(ord(missing) - 1)!r} and {chr(ord(missing) + 1)!r})"


def main(argv: list[str]) -> int:
    inputs = argv[1:]
    if not inputs:
        inputs = ["a,b,d,e", "m,n,p,q"]
    status = 0
    for raw in inputs:
        try:
            letters = parse_sequence(raw)
            print(format_report(letters))
        except ValueError as exc:
            print(f"{raw}: error: {exc}", file=sys.stderr)
            status = 1
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv))

