def parse_index(text: str):
    """Parse a token into a non-negative int, or None if it is not one."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        value = int(stripped)
    except ValueError:
        return None
    if value < 0:
        return None
    return value


def parse_spec(text: str):
    """Parse 'n' or 'a-b' into the list of indices it names, or None if invalid."""
    stripped = text.strip()
    if "-" in stripped[1:]:
        left, right = stripped.split("-", 1)
        start = parse_index(left)
        if start is None:
            return None
        end = parse_index(right)
        if end is None:
            return None
        if end < start:
            return None
        return list(range(start, end + 1))
    single = parse_index(stripped)
    if single is None:
        return None
    return [single]


def triangular_number(n: int) -> int:
    """Return the nth triangular number, 1 + 2 + ... + n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    return n * (n + 1) // 2


def triangular_index(value: int):
    """Return n such that triangular_number(n) == value, or None if none exists."""
    if value < 0:
        return None
    discriminant = 8 * value + 1
    root = int(discriminant ** 0.5)
    for candidate in (root - 1, root, root + 1):
        if candidate >= 1 and candidate * candidate == discriminant:
            return (candidate - 1) // 2
    return None


def describe(value: int) -> str:
    """Describe a number's relationship to the triangular sequence."""
    index = triangular_index(value)
    if index is None:
        return "%d is not a triangular number" % value
    return "%d is triangular number #%d" % (value, index)


def main(argv=None) -> int:
    import sys

    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print("first ten:", [triangular_number(n) for n in range(1, 11)])
        print(describe(10))
        print(describe(11))
        return 0

    status = 0
    for token in argv:
        indices = parse_spec(token)
        if indices is None:
            print("skipping %r: not an index or index range" % token)
            status = 1
            continue
        for n in indices:
            print("T(%d) = %d" % (n, triangular_number(n)))
    return status


if __name__ == "__main__":
    raise SystemExit(main())

