    """Return n! computed recursively, optionally reusing a memo dictionary."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    if cache is None:
        cache = {0: 1, 1: 1}
    stored = cache.get(n)
    if stored is not None:
        return stored
    result = n * factorial_recursive(n - 1, cache)
    cache[n] = result
    return result


