def find_largest_number(numbers):
    """Return the largest value in numbers."""
    largest = None
    for value in numbers:
        if largest is None or value > largest:
            largest = value
    if largest is None:
        raise ValueError("cannot find the largest number of an empty list")
    return largest


def parse_int(token):
    """Return the integer held in token, or None when it is not an integer."""
    text = token.strip()
    if not text:
        return None
    body = text[1:] if text[0] in "+-" else text
    if not body.isdigit():
        return None
    return int(text)


def parse_numbers(line):
    """Split a comma/space separated line into ints, ignoring bad tokens."""
    numbers = []
    rejected = []
    for token in line.replace(",", " ").split():
        value = parse_int(token)
        if value is None:
            rejected.append(token)
        else:
            numbers.append(value)
    return numbers, rejected


def describe(numbers, label=None):
    """Build a one line report about the largest number in numbers."""
    if not numbers:
        return "no numbers given"
    largest = find_largest_number(numbers)
    position = numbers.index(largest) + 1
    prefix = "" if label is None else label + ": "
    return "{}largest of {} numbers is {} (item #{})".format(
        prefix, len(numbers), largest, position)


def best_of_lines(lines):
    """Return the largest number found anywhere in lines, or None."""
    best = None
    for line in lines:
        numbers, _rejected = parse_numbers(line)
        if numbers:
            candidate = find_largest_number(numbers)
            if best is None or candidate > best:
                best = candidate
    return best


def report_lines(lines):
    """Turn raw input lines into report strings."""
    reports = []
    for index, line in enumerate(lines, start=1):
        numbers, rejected = parse_numbers(line)
        report = describe(numbers, "line {}".format(index))
        if rejected:
            report += " [ignored: {}]".format(" ".join(rejected))
        reports.append(report)
    return reports


def main():
    print(find_largest_number([1, 5, 2, 8, 3]))
    print(find_largest_number([-10, -2, -5]))

    raw = [
        "1, 5, 2, 8, 3",
        "-10 -2 -5",
        "7 seven 12 -3",
        "   ",
    ]
    for report in report_lines(raw):
        print(report)

    overall = best_of_lines(raw)
    if overall is None:
        print("no usable numbers in the input")
    else:
        print("overall largest is {}".format(overall))


if __name__ == "__main__":
    main()

