def calculate_average(numbers):
    """Return the arithmetic mean of numbers, or 0.0 for an empty list."""
    if numbers is None:
        raise ValueError("numbers must be a list, not None")
    if not numbers:
        return 0.0
    total = 0.0
    for value in numbers:
        total += float(value)
    return total / len(numbers)


def parse_number(text):
    """Convert a text token to a float, returning None if it is not numeric."""
    try:
        return float(text)
    except ValueError:
        return None


def parse_series(line):
    """Split a comma/space separated line into numbers, skipping bad tokens."""
    tokens = line.replace(",", " ").split()
    numbers = []
    for token in tokens:
        value = parse_number(token)
        if value is not None:
            numbers.append(value)
    return numbers


def calculate_average_of_range(numbers, low=None, high=None):
    """Average only the values that fall inside the optional bounds."""
    selected = []
    for value in numbers:
        if low is not None and value < low:
            continue
        if high is not None and value > high:
            continue
        selected.append(value)
    return calculate_average(selected)


def describe_bounds(low, high):
    """Render the optional bounds, or an empty string when both are absent."""
    if low is None:
        if high is None:
            return ""
        return " [-inf, {0:g}]".format(high)
    if high is None:
        return " [{0:g}, +inf]".format(low)
    return " [{0:g}, {1:g}]".format(low, high)


def format_report(label, numbers, low=None, high=None):
    average = calculate_average_of_range(numbers, low, high)
    bounds = describe_bounds(low, high)
    return "{0}{1}: n={2} average={3:.4f}".format(label, bounds, len(numbers), average)


def main():
    raw_lines = [
        "1 2 3 4 5",
        "",
        "10, 20, thirty, 40",
        "-5 0 5 100",
    ]
    for index, line in enumerate(raw_lines, start=1):
        series = parse_series(line)
        print(format_report("series {0}".format(index), series))

    combined = []
    for line in raw_lines:
        combined.extend(parse_series(line))
    print(format_report("combined", combined, low=0.0))
    print(format_report("combined", combined, high=50.0))
    print("plain average:", calculate_average([1, 2, 3, 4, 5]))
    print("empty average:", calculate_average([]))


if __name__ == "__main__":
    main()

