import sys

_BINARY_CACHE = {}


def decimal_to_binary(decimal_num):
    """Convert a non-negative decimal integer to its binary string."""
    if not isinstance(decimal_num, int) or isinstance(decimal_num, bool):
        raise TypeError("decimal_num must be a plain int")
    if decimal_num < 0:
        raise ValueError("decimal_num must be non-negative")

    cached = _BINARY_CACHE.get(decimal_num)
    if cached is not None:
        return cached

    if decimal_num == 0:
        binary_string = "0"
    else:
        digits = []
        remaining = decimal_num
        while remaining > 0:
            digits.append(str(remaining & 1))
            remaining >>= 1
        binary_string = "".join(reversed(digits))

    _BINARY_CACHE[decimal_num] = binary_string
    return binary_string


def parse_decimal(text):
    """Return the integer described by text, or None if it is not a valid one."""
    stripped = text.strip()
    if not stripped.isdigit():
        return None
    return int(stripped)


def pad_left(binary_string, min_width):
    """Zero-pad a binary string on the left up to min_width characters."""
    if min_width is None:
        return binary_string
    return binary_string.rjust(min_width, "0")


def group_bits(binary_string, group_size):
    """Split a binary string into fixed-size groups, padding on the left."""
    if group_size is None:
        return binary_string
    padding = (-len(binary_string)) % group_size
    padded = binary_string.rjust(len(binary_string) + padding, "0")
    return " ".join(padded[i:i + group_size] for i in range(0, len(padded), group_size))


def parse_options(tokens):
    """Read leading --group=/--width= flags, or return None if one is invalid."""
    group_size = None
    min_width = None
    while tokens and tokens[0].startswith("--"):
        parts = tokens[0].split("=", 1)
        if len(parts) != 2:
            return None
        requested = parse_decimal(parts[1])
        if parts[0] == "--group":
            if requested is None or requested <= 0:
                return None
            group_size = requested
        elif parts[0] == "--width":
            if requested is None:
                return None
            min_width = requested
        else:
            return None
        tokens = tokens[1:]
    return group_size, min_width, tokens


def describe(text, group_size, min_width):
    """Format one conversion report line for the given user-supplied token."""
    value = parse_decimal(text)
    if value is None:
        return "%s -> not a non-negative decimal integer" % text.strip()
    binary_string = decimal_to_binary(value)
    padded = pad_left(binary_string, min_width)
    return "%d -> %s (%d bits)" % (value, group_bits(padded, group_size), len(padded))


def main(argv):
    options = parse_options(argv[1:])
    if options is None:
        print("usage: %s [--group=N] [--width=N] [number ...]" % argv[0])
        return 2
    group_size, min_width, tokens = options
    if not tokens:
        tokens = ["10", "0", "255", "1000"]
    for token in tokens:
        print(describe(token, group_size, min_width))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

