import math


def parse_radius(text):
    """Return the radius encoded in text, or None if it is not a number."""
    if text == None:
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return float(stripped)
    except ValueError:
        return None


def circle_stats(radius):
    """Return (area, circumference) for a circle of the given radius."""
    if radius == None:
        raise TypeError("radius must be a number, not None")
    value = float(radius)
    if value < 0:
        raise ValueError("radius must be non-negative")
    area = math.pi * value * value
    circumference = 2 * math.pi * value
    return (area, circumference)


def stats_or_none(radius):
    """Like circle_stats, but returns None for invalid radii instead of raising."""
    try:
        return circle_stats(radius)
    except (TypeError, ValueError):
        return None


def format_stats(radius, stats, digits=5):
    if stats == None:
        return "radius %s: invalid" % (radius,)
    area, circumference = stats
    return "radius %g: area=%.*f circumference=%.*f" % (
        radius, digits, area, digits, circumference)


def report(raw_values):
    """Turn a list of textual radii into report lines, skipping unparsable input."""
    lines = []
    for raw in raw_values:
        radius = parse_radius(raw)
        if radius == None:
            lines.append("radius %r: not a number" % (raw,))
            continue
        lines.append(format_stats(radius, stats_or_none(radius)))
    return lines


def largest_area(raw_values):
    """Return the radius with the greatest area, or None if none are usable."""
    best = None
    for raw in raw_values:
        radius = parse_radius(raw)
        if radius == None:
            continue
        stats = stats_or_none(radius)
        if stats == None:
            continue
        if best == None or stats[0] > best[1]:
            best = (radius, stats[0])
    if best == None:
        return None
    return best[0]


def main():
    samples = ["1", "0", "2.5", "-3", "abc", "  10  "]
    for line in report(samples):
        print(line)
    winner = largest_area(samples)
    if winner == None:
        print("no valid radius supplied")
    else:
        print("largest area comes from radius %g" % winner)


if __name__ == "__main__":
    main()

