STATUS_TEXTS = {
    100: "Continue",
    200: "OK",
    201: "Created",
    204: "No Content",
    301: "Moved Permanently",
    304: "Not Modified",
    400: "Bad Request",
    401: "Unauthorized",
    403: "Forbidden",
    404: "Not Found",
    500: "Internal Server Error",
    503: "Service Unavailable",
}

CLASS_NAMES = {
    1: "Informational",
    2: "Success",
    3: "Redirection",
    4: "Client Error",
    5: "Server Error",
}


def get_http_status_desc(status_code):
    description = STATUS_TEXTS.get(status_code)
    if description is not None:
        return description
    return "Unknown Status"


def get_status_class(status_code):
    return CLASS_NAMES.get(status_code // 100)


def parse_status_code(value):
    if isinstance(value, int):
        return value
    text = str(value).strip()
    if not text.isdigit():
        return None
    return int(text)


def format_status_line(value):
    code = parse_status_code(value)
    if code is None:
        return "%r -> invalid status code" % (value,)
    description = get_http_status_desc(code)
    class_name = get_status_class(code)
    if class_name is None:
        return "%d %s (unclassified)" % (code, description)
    return "%d %s [%s]" % (code, description, class_name)


def summarize(values):
    counts = {}
    for value in values:
        code = parse_status_code(value)
        if code is None:
            key = "Invalid"
        else:
            key = get_status_class(code)
            if key is None:
                key = "Unclassified"
        counts[key] = counts.get(key, 0) + 1
    return counts


