def _require_list(name, value):
    if value is None:
        raise ValueError("%s must not be None" % name)
    if not isinstance(value, list):
        raise TypeError("%s must be a list" % name)
    return value


def _fingerprint(item, key):
    if key is None:
        return item
    return key(item)


def list_intersection(list1, list2, key=None):
    """Return the unique elements that appear in both lists, in list1 order."""
    _require_list("list1", list1)
    _require_list("list2", list2)
    second = set()
    for item in list2:
        second.add(_fingerprint(item, key))
    common_elements = []
    seen = set()
    for item in list1:
        mark = _fingerprint(item, key)
        if mark in second and mark not in seen:
            seen.add(mark)
            common_elements.append(item)
    return common_elements


def intersect_all(lists, key=None):
    """Intersect any number of lists, keeping the order of the first one."""
    common = None
    for items in lists:
        if common is None:
            common = _require_list("lists[0]", items)[:]
        else:
            common = list_intersection(common, items, key=key)
    if common is None:
        return []
    return common


def first_common(list1, list2, key=None):
    """Return the first shared element, or None when the lists are disjoint."""
    shared = list_intersection(list1, list2, key=key)
    if not shared:
        return None
    return shared[0]


def describe(list1, list2, key=None, limit=None):
    """Build a one-line report about the intersection of two lists."""
    shared = list_intersection(list1, list2, key=key)
    if limit is not None and len(shared) > limit:
        shown = shared[:limit]
        tail = ", ... (+%d more)" % (len(shared) - limit)
    else:
        shown = shared
        tail = ""
    body = ", ".join(repr(item) for item in shown)
    return "%d common: [%s%s]" % (len(shared), body, tail)


def main():
    pairs = [
        ([1, 2, 3, 4], [3, 4, 5, 6], None, None),
        (["a", "b"], ["c", "d"], None, None),
        ([1, 1, 2, 2, 3], [2, 3, 3], None, None),
        (["Ann", "BOB", "cal"], ["bob", "ann", "dee"], str.lower, None),
        (list(range(20)), list(range(10, 30)), None, 4),
    ]
    for list1, list2, key, limit in pairs:
        print(describe(list1, list2, key=key, limit=limit))
        head = first_common(list1, list2, key=key)
        if head is not None:
            print("  first shared element: %r" % (head,))
        else:
            print("  no shared elements")

    groups = [[1, 2, 3, 4, 5], [2, 3, 4, 9], [3, 4, 5, 2]]
    print("shared by all groups: %r" % (intersect_all(groups),))


if __name__ == "__main__":
    main()

