def fibonacci_iterative(n):
    """Return the nth Fibonacci number, computed iteratively."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    previous, current = 0, 1
    for _ in range(n):
        previous, current = current, previous + current
    return previous


def fib_cached(n):
    """Return fib(n), reusing values already computed during this run."""
    value = _CACHE.get(n)
    if value is None:
        value = fibonacci_iterative(n)
        _CACHE[n] = value
    return value


def parse_index(text):
    """Convert a user-supplied token to an index, or None if it is not valid."""
    token = text.strip()
    try:
        value = int(token)
    except ValueError:
        return None
    if value < 0:
        return None
    return value


def describe(text):
    """Format a one-line report for a requested index given as text."""
    index = parse_index(text)
    if index is None:
        return "%r is not a valid non-negative index" % (text,)
    return "fib(%d) = %d" % (index, fib_cached(index))


def fibonacci_series(count):
    """Return the first `count` Fibonacci numbers."""
    return [fib_cached(i) for i in range(count)]


def find_index_of(value):
    """Return the index of `value` in the sequence, or None if absent."""
    index = 0
    while True:
        candidate = fib_cached(index)
        if candidate == value:
            return index
        if candidate > value:
            return None
        index += 1


def describe_membership(value):
    """Report whether `value` occurs in the Fibonacci sequence."""
    position = find_index_of(value)
    if position is None:
        return "%d is not a Fibonacci number" % value
    return "%d appears at index %d" % (value, position)


def largest_below(limit):
    """Return the biggest Fibonacci number strictly below `limit`, or None."""
    best = None
    index = 0
    while True:
        candidate = fib_cached(index)
        if candidate >= limit:
            return best
        if best is None or candidate > best:
            best = candidate
        index += 1


def describe_largest_below(limit):
    """Report the largest Fibonacci number below `limit`."""
    biggest = largest_below(limit)
    if biggest is None:
        return "no Fibonacci number below %d" % limit
    return "largest Fibonacci below %d is %d" % (limit, biggest)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    for token in argv or ["0", "6", "10", "abc", "-3", "  30 "]:
        print(describe(token))
    print("first ten:", fibonacci_series(10))
    for target in [8, 55, 100]:
        print(describe_membership(target))
    for limit in [1, 90]:
        print(describe_largest_below(limit))


if __name__ == "__main__":
    main()

